/// The paragraphs directly in the body.
fn body(doc: &FlowDocument) -> Vec<&FlowParagraph> {
    doc.body.iter().filter_map(|b| if let Block::Paragraph(p) = b { Some(p) } else { None }).collect()
}

fn flow(p: &Presentation) -> &FlowDocument {
    p.flow.as_deref().expect("a document")
}

fn text_screen_pos(s: &mut Scenario, pos: FlowPos) -> (f32, f32) {
    let (page, x, y, h, vertical) = s.update(|e, _, cx| {
        let lines = e.flow_lines();
        let vert = crate::shell::editor::SlideEditor::line_of(&lines, pos).is_some_and(|l| l.vertical);
        let (page, x, y, h) = e.caret_box(&lines, pos).expect("the position is laid out");
        e.scroll_into_view(page, y, h, cx);
        (page, x, y, h, vert)
    });
    let (origin, k) = s.with(|e, _| e.page_origin(page)).expect("the page is placed");
    if vertical {
        (f32::from(origin.x) + (x + h / 2.0) * k, f32::from(origin.y) + (y + 1.0) * k)
    } else {
        (f32::from(origin.x) + x * k + 0.5, f32::from(origin.y) + (y + h / 2.0) * k)
    }
}

/// A document's steps, on the shell's driver.
pub(crate) trait DocSteps {
    /// Click at a position of the text (the paragraph's id and an offset).
    fn click_text(&mut self, pos: FlowPos);
    /// Double-click at a position of the text (selects the word).
    fn double_click_text(&mut self, pos: FlowPos);
    /// Triple-click at a position of the text (selects the paragraph).
    fn triple_click_text(&mut self, pos: FlowPos);
    /// The body paragraph `index`'s id and text.
    fn paragraph(&mut self, index: usize) -> (u32, String);
    /// The caret, and the other end of the selection.
    fn selection(&mut self) -> Option<(FlowPos, FlowPos)>;
    /// The document now.
    fn document(&mut self) -> FlowDocument;
}

impl DocSteps for Scenario {
    fn click_text(&mut self, pos: FlowPos) {
        let (px, py) = text_screen_pos(self, pos);
        self.click((px, py));
    }

    fn double_click_text(&mut self, pos: FlowPos) {
        let (px, py) = text_screen_pos(self, pos);
        self.double_click((px, py));
    }

    fn triple_click_text(&mut self, pos: FlowPos) {
        let (px, py) = text_screen_pos(self, pos);
        self.triple_click((px, py));
    }

    fn paragraph(&mut self, index: usize) -> (u32, String) {
        self.with(|e, _| {
            let p = body(flow(e.presentation()))[index];
            (p.id, p.text())
        })
    }

    fn selection(&mut self) -> Option<(FlowPos, FlowPos)> {
        self.with(|e, _| e.text_selection())
    }

    fn document(&mut self) -> FlowDocument {
        self.with(|e, _| flow(e.presentation()).clone())
    }
}

/// The body paragraph with this id in a document.
fn para(doc: &FlowDocument, id: u32) -> &FlowParagraph {
    body(doc).into_iter().find(|p| p.id == id).expect("the paragraph")
}

/// The first body paragraph of plain text at least `min` long, by index.
fn text_paragraph(s: &mut Scenario, min: usize) -> (usize, u32, String) {
    let doc = s.document();
    let (i, p) = body(&doc).into_iter().enumerate().find(|(_, p)| p.len() >= min && !p.text().contains('\u{fffc}') && p.list.is_none()).expect("a paragraph of text");
    (i, p.id, p.text())
}

/// A6: select a word, make it bold, italic and red with the toolbar, see the
/// toolbar follow, undo, save and read the file back.
fn a6_character_formatting() {
    let mut s = Scenario::open(REPORT);
    let (_, id, _) = text_paragraph(&mut s, 10);
    s.click_text(FlowPos::new(id, 2));
    assert_eq!(s.selection().map(|(_, c)| c), Some(FlowPos::new(id, 2)), "the click put the caret there");
    for _ in 0..3 {
        s.key("shift-right");
    }
    assert_eq!(s.selection(), Some((FlowPos::new(id, 2), FlowPos::new(id, 5))));
    assert_eq!(s.toolbar_state("bold").map(|t| t.on), Some(false));
    s.toolbar("bold");
    s.toolbar("italic");
    s.toolbar_menu("text-color", "docx.color.red");
    assert_eq!(s.toolbar_state("bold").map(|t| t.on), Some(true), "the toolbar shows the selection bold");
    assert_eq!(s.toolbar_state("italic").map(|t| t.on), Some(true));
    let doc = s.document();
    let p = para(&doc, id);
    let styled: Vec<_> = p.runs.iter().filter(|r| r.style.bold).collect();
    // The CJK characters and the space carry different East Asian hints, so they stay two runs: the selection
    // (3 characters) is what is bold, italic and red.
    assert_eq!(styled.iter().map(|r| r.len()).sum::<usize>(), 3);
    assert!(styled.iter().all(|r| r.style.color.0 == 0xff0000 && r.style.italic));
    s.screenshot("formatted");
    // Undo the colour: bold and italic stay.
    s.key("cmd-z");
    let doc = s.document();
    assert!(para(&doc, id).runs.iter().any(|r| r.style.bold && r.style.color.0 != 0xff0000));
    s.save_as("a6.docx");
    let saved = s.reopen();
    let p = body(flow(&saved)).into_iter().find(|p| p.text() == para(&doc, id).text()).expect("the paragraph read back").clone();
    assert!(p.runs.iter().any(|r| r.style.bold && r.style.italic));
}

/// A7: ⌘B with nothing selected, type, ⌘B again, type: only the first
/// word is bold.
fn a7_format_before_typing() {
    let mut s = Scenario::open(REPORT);
    let (_, id, text) = text_paragraph(&mut s, 10);
    let end = text.chars().count();
    s.click_text(FlowPos::new(id, end));
    s.key("cmd-b");
    assert_eq!(s.toolbar_state("bold").map(|t| t.on), Some(true), "bold is on for what is typed");
    s.type_text("Bold");
    s.key("cmd-b");
    s.type_text("Plain");
    let doc = s.document();
    let p = para(&doc, id);
    assert!(p.text().ends_with("BoldPlain"));
    let bold: String = p.runs.iter().filter(|r| r.style.bold).filter_map(|r| if let FlowRunKind::Text(t) = &r.kind { Some(t.as_str()) } else { None }).collect();
    assert!(bold.ends_with("Bold"), "{bold}");
    s.save_as("a7.docx");
    let saved = s.reopen();
    assert!(body(flow(&saved)).iter().any(|p| p.text().ends_with("BoldPlain")));
}

/// A3: a paragraph made a bullet item with the toolbar, Enter makes the
/// next item, Enter on the empty item ends the list; saved and read back.
fn a3_bullets() {
    let mut s = Scenario::open(REPORT);
    let (index, id, text) = text_paragraph(&mut s, 10);
    s.click_text(FlowPos::new(id, 1));
    s.toolbar("bullets");
    assert_eq!(s.toolbar_state("bullets").map(|t| t.on), Some(true));
    assert!(s.with(|e, _| body(flow(e.presentation()))[index].list.is_some()), "the paragraph is a list item");
    s.click_text(FlowPos::new(id, text.chars().count()));
    s.key("enter");
    s.type_text("next item");
    s.key("enter");
    s.key("enter"); // the empty item: no longer a list item
    s.type_text("after the list");
    let doc = s.document();
    let ps = body(&doc);
    assert!(ps[index + 1].list.is_some() && ps[index + 1].text() == "next item");
    assert!(ps[index + 2].list.is_none() && ps[index + 2].text() == "after the list");
    s.screenshot("list");
    s.save_as("a3.docx");
    let saved = s.reopen();
    let ps = body(flow(&saved));
    assert!(ps[index].list.is_some() && ps[index + 1].list.is_some() && ps[index + 2].list.is_none());
}

/// A9: centre (⌘E), line spacing 1.5 from the toolbar's menu, indent
/// more; saved and read back.
fn a9_alignment_and_spacing() {
    let mut s = Scenario::open(STATEMENT);
    let (_, id, _) = text_paragraph(&mut s, 10);
    s.click_text(FlowPos::new(id, 1));
    s.key("cmd-e");
    s.toolbar_menu("line-spacing", "docx.spacing.1.5");
    s.toolbar("indent-more");
    let doc = s.document();
    let p = para(&doc, id);
    assert_eq!(p.align, FlowAlign::Center);
    assert_eq!(p.line, LineHeight::Auto(360));
    assert!(p.left > 0);
    let text = p.text();
    s.save_as("a9.docx");
    let saved = s.reopen();
    let p = body(flow(&saved)).into_iter().find(|p| p.text() == text).expect("the paragraph").clone();
    assert_eq!((p.align, p.line), (FlowAlign::Center, LineHeight::Auto(360)));
}

/// A12: the input method: composing text is not in the document; the
/// committed text is, as one step of undo.
fn a12_input_method() {
    let mut s = Scenario::open(REPORT);
    let (_, id, _) = text_paragraph(&mut s, 5);
    s.click_text(FlowPos::new(id, 1));
    let before = s.document();
    s.ime("かくう", "架空");
    let doc = s.document();
    assert!(para(&doc, id).text().chars().skip(1).collect::<String>().starts_with("架空"));
    s.key("cmd-z");
    assert!(s.document() == before, "one undo takes the committed text away");
}

/// B1: Enter in the middle of a paragraph makes two, Backspace at the
/// second's start joins them again; the saved file has the paragraph back.
fn b1_split_and_join() {
    let mut s = Scenario::open(REPORT);
    let (index, id, text) = text_paragraph(&mut s, 8);
    let count = s.with(|e, _| body(flow(e.presentation())).len());
    s.click_text(FlowPos::new(id, 3));
    s.key("enter");
    assert_eq!(s.with(|e, _| body(flow(e.presentation())).len()), count + 1);
    let (_, _, second) = (0, 0, s.paragraph(index + 1).1);
    assert_eq!(second, text.chars().skip(3).collect::<String>());
    assert_eq!(s.selection().map(|(_, c)| c.offset), Some(0), "the caret at the new paragraph's start");
    s.key("backspace");
    assert_eq!(s.with(|e, _| body(flow(e.presentation())).len()), count);
    assert_eq!(s.paragraph(index).1, text);
    s.save_as("b1.docx");
    let saved = s.reopen();
    assert_eq!(body(flow(&saved))[index].text(), text);
}

/// B5: a run of edits, undone and redone through the keys; the file saved
/// halfway, and all undone saves the original file.
fn b5_undo_and_redo() {
    let mut s = Scenario::open(REPORT);
    let original = std::fs::read(crate::shell::scenario::repo_root().join(REPORT)).unwrap();
    let (_, id, _) = text_paragraph(&mut s, 8);
    let start = s.document();
    s.click_text(FlowPos::new(id, 2));
    s.type_text("ab");
    s.key("shift-left");
    s.key("cmd-b");
    s.key("enter");
    s.toolbar("bullets");
    let after = s.document();
    s.key("cmd-z");
    s.key("cmd-z");
    s.key("cmd-shift-z");
    s.key("cmd-shift-z");
    assert!(s.document() == after, "redo gives the edited document again");
    for _ in 0..8 {
        s.key("cmd-z");
    }
    assert!(s.document() == start, "undo gives the first document");
    let path = s.save_as("b5.docx");
    assert!(std::fs::read(path).unwrap() == original, "all undone, the save is the original file");
}

/// B8: ⌥→ moves by words, ⌥⇧→ selects them, ⌘A selects everything.
fn b8_word_selection() {
    let mut s = Scenario::open(REPORT);
    let (_, id, text) = text_paragraph(&mut s, 10);
    s.click_text(FlowPos::new(id, 0));
    s.key("alt-right");
    let first = s.selection().unwrap().1.offset;
    assert!(first > 0 && first < text.chars().count(), "moved by a word: {first}");
    s.key("alt-shift-right");
    let (a, c) = s.selection().unwrap();
    assert!(a.offset == first && c.offset > first);
    s.key("cmd-a");
    let (a, c) = s.selection().unwrap();
    assert!(a != c);
    let doc = s.document();
    assert_eq!(a.offset, 0);
    assert_eq!(c.offset, ibis_doc_model::flow_command::paragraph(&doc, c.para).unwrap().len());
}

/// B9: ⌘↓ to the end of the 150-page document, type three paragraphs,
/// save; the time of a character is written down.
fn b9_append_at_the_end_of_a_long_document() {
    let mut s = Scenario::open(STATEMENT);
    s.key("cmd-down");
    let (_, end) = s.selection().unwrap();
    let pages = s.with(|e, _| e.presentation().slides.len());
    let started = crate::clock::Instant::now();
    s.type_text("末尾に追記");
    let per_char = started.elapsed().as_secs_f32() / 5.0;
    eprintln!("b9: {pages} ページの文書で 1 文字 {per_char:.3} 秒");
    s.key("enter");
    s.type_text("second");
    s.key("enter");
    s.type_text("third");
    let doc = s.document();
    assert!(ibis_doc_model::flow_command::paragraph(&doc, end.para).unwrap().text().ends_with("末尾に追記"));
    s.save_as("b9.docx");
    let saved = s.reopen();
    let texts: Vec<String> = flow(&saved).body.iter().rev().filter_map(|b| if let Block::Paragraph(p) = b { Some(p.text()) } else { None }).take(3).collect();
    assert_eq!(texts[0], "third");
    assert_eq!(texts[1], "second");
}

/// F1: open and save: the same file byte for byte.
fn f1_save_without_edits() {
    for file in [REPORT, STATEMENT] {
        let mut s = Scenario::open(file);
        let original = std::fs::read(crate::shell::scenario::repo_root().join(file)).unwrap();
        let path = s.save_as("f1.docx");
        assert!(std::fs::read(path).unwrap() == original, "{file}");
    }
}

/// A .docm opens (saying its macros do not run), takes typing, and saves
/// under its own name with its macros (vbaProject.bin) as they were.
fn f1_macro_file() {
    let root = crate::shell::scenario::repo_root();
    let input = root.join("target/scenario-input/docx-macro.docm");
    std::fs::create_dir_all(input.parent().unwrap()).unwrap();
    std::fs::write(&input, ibis_pptx::test_files::docx_with_macros(&std::fs::read(root.join(REPORT)).unwrap(), b"VBA bytes kept as they are")).unwrap();
    let mut s = Scenario::open("target/scenario-input/docx-macro.docm");
    assert!(s.with(|e, _| e.status.as_ref().is_some_and(|t| t.contains("マクロは実行されません"))));
    let (_, id, _) = text_paragraph(&mut s, 6);
    s.click_text(FlowPos::new(id, 1));
    s.type_text("追記");
    s.key("cmd-s");
    let path = s.with(|e, _| e.path.clone()).unwrap();
    assert_eq!(path.extension().unwrap(), "docm");
    let saved = std::fs::read(&path).unwrap();
    assert_eq!(ibis_pptx::test_files::part_bytes(&saved, "word/vbaProject.bin").unwrap(), b"VBA bytes kept as they are");
    assert!(ibis_pptx::test_files::part_text(&saved, "[Content_Types].xml").unwrap().contains("macroEnabled.main+xml"));
    let reread = ibis_pptx::read(&saved).unwrap();
    assert!(ibis_doc_model::flow_command::paragraph(flow(&reread), id).unwrap().text().contains("追記"));
}

/// NUMPAGES and SECTIONPAGES in the footers show the document's and the
/// section's number of pages as laid out (not the saved 9 and IX), with
/// SECTIONPAGES's \* ROMAN; the file saves unchanged.
/// 表スタイルのオプション: the heading row and the rows' bands of a table
/// style, turned off and on; the fills and bold text follow, and the
/// options are saved.
fn c4_table_style_options() {
    let root = crate::shell::scenario::repo_root();
    let data = ibis_pptx::test_files::docx_with_styled_table(&std::fs::read(root.join(REPORT)).unwrap());
    let input = root.join("target/scenario-input/docx-styled-table.docx");
    std::fs::create_dir_all(input.parent().unwrap()).unwrap();
    std::fs::write(&input, &data).unwrap();
    let mut s = Scenario::open("target/scenario-input/docx-styled-table.docx");
    let table = |doc: &FlowDocument| doc.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t.clone()) } else { None }).unwrap();
    let fills = |t: &ibis_doc_model::FlowTable| t.rows.iter().map(|r| r.cells[1].style_fill.map(|c| c.0)).collect::<Vec<_>>();
    let bold = |t: &ibis_doc_model::FlowTable| match &t.rows[0].cells[0].blocks[0] { Block::Paragraph(p) => p.runs[0].style.bold, _ => false };
    let t = table(&s.document());
    assert_eq!(fills(&t), vec![Some(0x4472C4), Some(0xE2EFDA), None]);
    assert!(bold(&t));
    // The caret in the table; the heading row off: the bands start at the top.
    let first = match &t.rows[1].cells[0].blocks[0] { Block::Paragraph(p) => p.id, _ => unreachable!() };
    s.click_text(FlowPos::new(first, 0));
    s.menu("docx.table.look.first-row");
    let t = table(&s.document());
    assert_eq!(fills(&t), vec![Some(0xE2EFDA), None, Some(0xE2EFDA)]);
    assert!(!bold(&t));
    // The bands off too.
    s.menu("docx.table.look.row-bands");
    assert_eq!(fills(&table(&s.document())), vec![None, None, None]);
    s.screenshot("options-off");
    s.save_as("c4.docx");
    let saved = s.reopen();
    assert_eq!(fills(&table(flow(&saved))), vec![None, None, None], "read back");
    s.key("cmd-z");
    s.key("cmd-z");
    assert_eq!(fills(&table(&s.document())), vec![Some(0x4472C4), Some(0xE2EFDA), None]);
}

/// 段組み: a section in two columns fills the left one, then the right
/// one, a line between them; saved unchanged, the same file.
fn h6_columns() {
    let root = crate::shell::scenario::repo_root();
    let data = ibis_pptx::test_files::docx_with_two_columns(&std::fs::read(root.join(REPORT)).unwrap());
    let input = root.join("target/scenario-input/docx-columns.docx");
    std::fs::create_dir_all(input.parent().unwrap()).unwrap();
    std::fs::write(&input, &data).unwrap();
    let mut s = Scenario::open("target/scenario-input/docx-columns.docx");
    let (pages, page) = s.with(|e, _| {
        let doc = e.presentation().flow.clone().unwrap();
        (super::flow_layout::pages(&doc, &e.resources), doc.page)
    });
    let cols = page.columns.layout(page.size.width - page.left - page.right);
    let pt = |v: i64| v as f32 / ibis_doc_model::EMU_PER_POINT as f32;
    let (left, right) = (pt(page.left) + pt(cols[0].0), pt(page.left) + pt(cols[1].0));
    // The page the numbered paragraphs start on.
    let first = pages.pages.iter().find(|p| p.items.iter().any(|it| matches!(it, super::flow_layout::Item::Text { text, .. } if text.contains("段組みの行")))).unwrap();
    let xs: Vec<f32> = first.items.iter().filter_map(|it| if let super::flow_layout::Item::Text { x, .. } = it { Some(*x) } else { None }).collect();
    assert!(xs.iter().any(|&x| x < left + pt(cols[0].1)), "text in the left column");
    assert!(xs.iter().any(|&x| x >= right - 0.5), "text in the right column");
    assert!(!xs.iter().any(|&x| x > left + pt(cols[0].1) + 1.0 && x < right - 0.5), "nothing between the columns");
    let middle = (left + pt(cols[0].1) + right) / 2.0;
    let rects: Vec<String> = first.items.iter().filter_map(|it| if let super::flow_layout::Item::Rect { x, y, w, h, .. } = it { Some(format!("{x},{y},{w},{h}")) } else { None }).collect();
    assert!(first.items.iter().any(|it| matches!(it, super::flow_layout::Item::Rect { x, h, .. } if (x - middle).abs() < 1.0 && *h > 100.0)), "the line between at {middle}: {rects:?} sections {}", pages.pages.iter().map(|p| p.section.to_string()).collect::<Vec<_>>().join(","));
    s.screenshot("columns");
    let path = s.save_as("h6-columns.docx");
    assert_eq!(std::fs::read(path).unwrap(), data);
}

fn h6_page_count_fields() {
    let root = crate::shell::scenario::repo_root();
    let data = ibis_pptx::test_files::docx_with_page_count_footer(&std::fs::read(root.join(REPORT)).unwrap());
    let input = root.join("target/scenario-input/docx-page-count.docx");
    std::fs::create_dir_all(input.parent().unwrap()).unwrap();
    std::fs::write(&input, &data).unwrap();
    let mut s = Scenario::open("target/scenario-input/docx-page-count.docx");
    let pages = s.with(|e, _| {
        let doc = e.presentation().flow.clone().unwrap();
        super::flow_layout::pages(&doc, &e.resources)
    });
    let total = pages.pages.len();
    assert!(total > 1, "a document of several pages");
    let text = |n: usize| pages.pages[n].items.iter().filter_map(|it| if let super::flow_layout::Item::Text { text, .. } = it { Some(text.to_string()) } else { None }).collect::<String>();
    let roman = |n: usize| ibis_doc_model::format_page_number(n as u32, "upperRoman");
    for n in [0, total - 1] {
        let in_section = pages.pages.iter().filter(|p| p.section == pages.pages[n].section).count();
        let want = format!("{} / {total} ({})", pages.pages[n].number, roman(in_section));
        assert!(text(n).replace('\u{200b}', "").contains(&want), "page {}: want {want} in {}", n + 1, text(n));
    }
    let path = s.save_as("h6-page-count.docx");
    assert_eq!(std::fs::read(path).unwrap(), data);
}

/// The style list offers the document's other paragraph styles (見出し 4,
/// 引用文, …) after the six, and applies them; Enter at the end of a
/// heading starts a 標準 paragraph (the heading's w:next), and in its
/// middle keeps the heading on both halves.
fn h3_document_styles_and_next_style() {
    let mut s = Scenario::open(REPORT);
    let doc = s.document();
    let others = super::toolbar::document_paragraph_styles(&doc);
    let (id4, label4) = others.iter().find(|(_, l)| l == "見出し 4").cloned().expect("見出し 4 offered");
    assert!(others.iter().any(|(_, l)| l == "引用文"));
    let at = others.iter().position(|(i, _)| *i == id4).unwrap();
    let (_, id, _) = text_paragraph(&mut s, 6);
    s.click_text(FlowPos::new(id, 1));
    s.toolbar_menu("style", super::toolbar::DOC_STYLE_IDS[at]);
    assert_eq!(para(&s.document(), id).style.as_deref(), Some(id4.as_str()), "{label4}");
    // Heading 1 (w:next = 標準): Enter at its end, then in its middle.
    let h1 = doc.styles.paragraph_style_named("heading 1").map(str::to_string).expect("heading 1");
    let normal = doc.styles.styles.get(&h1).and_then(|st| st.next.clone()).expect("heading 1 has a next style");
    s.toolbar_menu("style", "docx.style.heading1");
    let len = para(&s.document(), id).len();
    s.click_text(FlowPos::new(id, len));
    s.key("enter");
    s.type_text("本文");
    let after = s.document();
    let next = body(&after).iter().position(|p| p.id == id).map(|i| body(&after)[i + 1].clone()).unwrap();
    assert_eq!(para(&after, id).style.as_deref(), Some(h1.as_str()));
    assert_eq!(next.style.as_deref(), Some(normal.as_str()));
    assert_eq!(next.text(), "本文");
    s.click_text(FlowPos::new(id, 2));
    s.key("enter");
    let split = s.document();
    let i = body(&split).iter().position(|p| p.id == id).unwrap();
    assert_eq!(body(&split)[i + 1].style.as_deref(), Some(h1.as_str()));
    s.save_as("h3-next-style.docx");
    let saved = s.reopen();
    let i = body(flow(&saved)).iter().position(|p| p.text() == "本文").unwrap();
    assert_eq!(body(flow(&saved))[i].style.as_deref(), Some(normal.as_str()));
}

/// Searching for the end of a paragraph and its mark (「…^p」) finds it
/// and replacing it with 「^t」 joins the two paragraphs with a tab; ^^ is
/// a caret. Undo gives the paragraphs back.
/// 挿入 > 日付と時刻: the date as text, and (自動的に更新する) as a DATE
/// field that is saved and read back with its picture.
fn b8_insert_date() {
    let mut s = Scenario::open(REPORT);
    let first = body(&s.document())[0].id;
    s.click_text(FlowPos::new(first, 0));
    let today = crate::clock::local_now();
    let text = ibis_doc_model::date_field::format_picture(&today, "yyyy'年'M'月'd'日'");
    s.menu("docx.date.1");
    assert!(para(&s.document(), first).text().starts_with(&text), "{}", para(&s.document(), first).text());
    s.menu("docx.date.update");
    s.menu("docx.date.0");
    s.menu("docx.date.update");
    let field = |doc: &FlowDocument| para(doc, first).runs.iter().find_map(|r| if let FlowRunKind::Field { instruction, shown } = &r.kind { Some((instruction.clone(), shown.clone())) } else { None });
    let slash = ibis_doc_model::date_field::format_picture(&today, "yyyy/MM/dd");
    assert_eq!(field(&s.document()), Some(("DATE \\@ \"yyyy/MM/dd\"".to_string(), slash.clone())));
    s.save_as("b8.docx");
    let saved = s.reopen();
    let p = &body(flow(&saved))[0];
    assert!(p.text().starts_with(&text), "the text read back: {}", p.text());
    let read = p.runs.iter().find_map(|r| if let FlowRunKind::Field { instruction, shown } = &r.kind { Some((instruction.clone(), shown.clone())) } else { None });
    assert_eq!(read, Some(("DATE \\@ \"yyyy/MM/dd\"".to_string(), slash)), "the field read back");
}

/// In English (設定 > 言語), the document's menus, toolbar, status bar and
/// a panel have no Japanese left, but for what is the document's own
/// (its styles, fonts, captions; the dates' formats).
fn i8_english_ui() {
    use crate::shell::chrome::{MenuEntry, ToolItem};
    use crate::shell::i18n::{self, Language};
    let japanese = |t: &str| t.chars().any(|c| matches!(c as u32, 0x3040..=0x30ff | 0x3400..=0x9fff));
    let mut s = Scenario::open(REPORT);
    i18n::show(Language::English);
    s.update(|_, _, _| {});
    let left: Vec<String> = s.with(|e, _| {
        fn walk(entries: &[MenuEntry], out: &mut Vec<String>) {
            for entry in entries {
                match entry {
                    MenuEntry::Item(i) => {
                        let own = ["docx.font.", "docx.style.doc.", "docx.cstyle.", "docx.xref.", "docx.date.0", "docx.date.1", "docx.date.2", "docx.date.3", "docx.date.4", "docx.date.5", "docx.date.6", "docx.date.7", "file.recent.", "window.open."].iter().any(|p| i.id.starts_with(p));
                        if !own {
                            out.push(format!("{}={}", i.id, i18n::text(&i.label)));
                        }
                    }
                    MenuEntry::Submenu(sub) => {
                        out.push(format!("{}={}", sub.id, i18n::text(&sub.label)));
                        walk(&sub.items, out);
                    }
                    _ => {}
                }
            }
        }
        let mut out = Vec::new();
        for (_, entries) in &e.menus().menus {
            walk(entries, &mut out);
        }
        for item in e.toolbar_items() {
            match item {
                // As the toolbar draws them (in the UI's language).
                ToolItem::Button(b) => out.push(format!("{}={}", b.id, i18n::text(&b.tooltip))),
                ToolItem::Select { id, tooltip, menu, .. } => {
                    out.push(format!("{id}={}", i18n::text(&tooltip)));
                    if id != "font" && id != "style" {
                        walk(&menu, &mut out);
                    }
                }
                _ => {}
            }
        }
        out
    });
    let japanese_left: Vec<&String> = left.iter().filter(|t| japanese(t)).collect();
    assert!(japanese_left.is_empty(), "Japanese in English: {japanese_left:?}");
    let status = s.status_texts();
    assert!(status.iter().all(|t| !japanese(t)), "{status:?}");
    // Word's styles by their English names.
    assert_eq!(super::toolbar::style_display_name("heading 1"), "Heading 1");
    assert_eq!(super::toolbar::style_display_name("heading 5"), "Heading 5");
    s.update(|e, window, cx| e.open_paragraph_edit(None, window, cx));
    s.screenshot("english-paragraph-panel");
    s.update(|e, window, cx| e.open_find(window, cx));
    s.screenshot("english-find-panel");
    i18n::show(Language::Japanese);
    s.update(|_, _, _| {});
}

/// 表示形式 > テキスト > 傍点: marks over the selected characters, drawn
/// above them, saved and read back.
fn b9_emphasis_mark() {
    use ibis_doc_model::EmphasisMark;
    let mut s = Scenario::open(REPORT);
    let doc = s.document();
    let p = body(&doc).iter().find(|p| p.text().chars().count() > 6 && !p.text().contains('\u{fffc}')).copied().unwrap();
    s.click_text(FlowPos::new(p.id, 0));
    for _ in 0..4 {
        s.key("shift-right");
    }
    s.menu("docx.text.emphasis.dot");
    let marked = |doc: &FlowDocument| para(doc, p.id).runs.iter().filter(|r| r.style.emphasis == EmphasisMark::Dot).map(|r| r.len()).sum::<usize>();
    assert_eq!(marked(&s.document()), 4);
    // Drawn: a mark over each of the 4 characters.
    let marks = s.with(|e, _| {
        let doc = e.presentation().flow.clone().unwrap();
        super::flow_layout::pages(&doc, &e.resources).pages.iter().flat_map(|pg| pg.items.iter()).filter(|it| matches!(it, super::flow_layout::Item::Text { text, .. } if text.as_ref() == "．")).count()
    });
    assert!(marks >= 4, "{marks} marks drawn");
    s.screenshot("emphasis");
    s.save_as("b9.docx");
    let saved = s.reopen();
    assert_eq!(marked(flow(&saved)), 4, "read back");
    s.key("cmd-z");
    assert_eq!(marked(&s.document()), 0);
}

/// 表示形式 > テキスト > ルビ…: ruby over the selected characters, drawn
/// above them, saved and read back; taken away, the text stays.
fn b9_ruby() {
    let mut s = Scenario::open(REPORT);
    let doc = s.document();
    let p = body(&doc).iter().find(|p| p.text().chars().count() > 6 && !p.text().contains('\u{fffc}')).copied().unwrap();
    let text = p.text();
    let base: String = text.chars().take(2).collect();
    s.click_text(FlowPos::new(p.id, 0));
    s.key("shift-right");
    s.key("shift-right");
    s.menu("docx.text.ruby");
    s.update(|e, _, cx| e.set_ruby("かくう", cx));
    let ruby = |doc: &FlowDocument| para(doc, p.id).runs.iter().find_map(|r| if let FlowRunKind::Ruby { base, text, .. } = &r.kind { Some((base.clone(), text.clone())) } else { None });
    assert_eq!(ruby(&s.document()), Some((base.clone(), "かくう".to_string())));
    let drawn = s.with(|e, _| {
        let doc = e.presentation().flow.clone().unwrap();
        super::flow_layout::pages(&doc, &e.resources).pages.iter().flat_map(|pg| pg.items.iter()).any(|it| matches!(it, super::flow_layout::Item::Text { text, .. } if text.as_ref() == "かくう"))
    });
    assert!(drawn, "the ruby is drawn");
    s.screenshot("ruby");
    s.save_as("b9-ruby.docx");
    let saved = s.reopen();
    assert_eq!(ruby(flow(&saved)), Some((base.clone(), "かくう".to_string())), "read back");
    // Taken away: the text as it was.
    s.update(|e, _, cx| e.set_ruby("", cx));
    assert_eq!(ruby(&s.document()), None);
    assert_eq!(para(&s.document(), p.id).text(), text);
}

