/// 表示形式 > テキスト > 囲い文字: 1–2 characters in a shape (an EQ \o
/// field), change enclosure, clear back to plain text, and draw scaled.
fn b9_enclosed_character() {
    let mut s = Scenario::open(REPORT);
    let doc = s.document();
    let p = body(&doc).iter().find(|p| p.text().chars().count() > 6 && !p.text().contains('\u{fffc}')).cloned().unwrap();
    let first: String = p.text().chars().take(1).collect();
    let two: String = p.text().chars().take(2).collect();

    // 1. Enclose 1 character in a circle.
    s.click_text(FlowPos::new(p.id, 0));
    s.key("shift-right");
    s.menu("docx.text.enclose.circle");
    let field = |doc: &FlowDocument| para(doc, p.id).runs.iter().find_map(|r| if let FlowRunKind::Field { instruction, .. } = &r.kind { Some(instruction.clone()) } else { None });
    assert_eq!(field(&s.document()), Some(format!("EQ \\o\\ac(○,{first})")));

    // 2. Change enclosure directly from circle to square.
    s.menu("docx.text.enclose.square");
    assert_eq!(field(&s.document()), Some(format!("EQ \\o\\ac(□,{first})")));

    // 3. Clear enclosed character: returns to plain text.
    s.menu("docx.text.enclose.none");
    assert_eq!(field(&s.document()), None, "enclosed field cleared");
    assert!(para(&s.document(), p.id).text().starts_with(&first));

    // 4. Enclose 2 characters in a circle.
    s.click_text(FlowPos::new(p.id, 0));
    s.key("shift-right");
    s.key("shift-right");
    s.menu("docx.text.enclose.circle");
    assert_eq!(field(&s.document()), Some(format!("EQ \\o\\ac(○,{two})")), "2 characters enclosed");

    let drawn = s.with(|e, _| {
        let doc = e.presentation().flow.clone().unwrap();
        let items: Vec<String> = super::flow_layout::pages(&doc, &e.resources).pages.iter().flat_map(|pg| pg.items.iter()).filter_map(|it| if let super::flow_layout::Item::Text { text, .. } = it { Some(text.to_string()) } else { None }).collect();
        items
    });
    assert!(drawn.iter().any(|t| t.starts_with('○')) && drawn.iter().any(|t| *t == two), "the circle and the 2 characters");
    s.screenshot("enclosed");
    s.save_as("b9-enclosed.docx");
    let saved = s.reopen();
    assert_eq!(field(flow(&saved)), Some(format!("EQ \\o\\ac(○,{two})")), "read back");

    // 5. Undo restores plain text.
    s.key("cmd-z");
    assert_eq!(field(&s.document()), None, "undo restored plain text");
}

