fn a11_format_brush() {
    let mut s = Scenario::open(REPORT);
    let (_, id, text) = text_paragraph(&mut s, 12);
    s.click_text(FlowPos::new(id, 1));
    for _ in 0..3 { s.key("shift-right"); }
    s.menu("docx.underline.wave");
    s.menu("docx.underline.red");
    s.key("cmd-b");
    let source = para(&s.document(), id).runs.iter().find(|r| matches!(&r.kind, FlowRunKind::Text(t) if t == &text.chars().skip(1).take(3).collect::<String>())).unwrap().style.clone();
    s.toolbar("format-paint");
    assert_eq!(s.toolbar_state("format-paint").map(|t| t.on), Some(true));
    s.toolbar("format-paint");
    assert_eq!(s.toolbar_state("format-paint").map(|t| t.on), Some(false));
    s.toolbar("format-paint");
    s.click_text(FlowPos::new(id, 6));
    assert_eq!(s.toolbar_state("format-paint").map(|t| t.on), Some(true), "empty click keeps brush");
    for _ in 0..3 { s.key("shift-right"); }
    let before = s.document();
    s.menu("docx.format-brush.apply");
    assert_eq!(s.toolbar_state("format-paint").map(|t| t.on), Some(false));
    let after = s.document();
    assert_eq!(para(&after, id).text(), text);
    let target: String = text.chars().skip(6).take(3).collect();
    assert_eq!(para(&after, id).runs.iter().find(|r| matches!(&r.kind, FlowRunKind::Text(t) if t == &target)).unwrap().style, source);
    assert_eq!(para(&after, id).runs[0].style, para(&before, id).runs[0].style);
    s.key("cmd-z"); assert_eq!(s.document(), before);
    s.key("cmd-shift-z"); assert_eq!(s.document(), after);
    s.save_as("a11-format-brush.docx");
    let saved = s.reopen();
    let p = body(flow(&saved)).into_iter().find(|p| p.text() == text).unwrap();
    assert_eq!(p.runs.iter().find(|r| matches!(&r.kind, FlowRunKind::Text(t) if t == &target)).unwrap().style, source);
    // Real mouse selection consumes the captured format once as well.
    s.click_text(FlowPos::new(id, 1));
    s.toolbar("format-paint");
    let coords = |s: &mut Scenario, offset| s.with(|e, _| {
        let (page, x, y, h) = e.caret_box(&e.flow_lines(), FlowPos::new(id, offset)).unwrap();
        let (o, k) = e.page_origin(page).unwrap();
        (f32::from(o.x) + x*k + 0.5, f32::from(o.y) + (y+h/2.0)*k)
    });
    let a = coords(&mut s, 9); let b = coords(&mut s, 11);
    let before = s.document();
    s.drag(a,b);
    assert_eq!(s.toolbar_state("format-paint").map(|t| t.on), Some(false));
    let after = s.document();
    assert_ne!(after, before);
    assert_eq!(para(&after, id).text(), text);
    s.key("cmd-z"); assert_eq!(s.document(), before);
    s.key("cmd-shift-z"); assert_eq!(s.document(), after);
    s.save_as("a11-format-brush-drag.docx");
    assert_eq!(body(flow(&s.reopen())).into_iter().find(|p| p.text() == text).unwrap().text(), text);
}

fn edit012_format_brush_repeat() {
    let mut s = Scenario::open(REPORT);
    let paragraphs: Vec<_> = body(&s.document()).into_iter().filter(|p| p.len() >= 5 && !p.text().contains('\u{fffc}') && p.list.is_none()).cloned().collect();
    assert!(paragraphs.len() >= 4);
    let id0 = paragraphs[0].id;
    let text0 = paragraphs[0].text();
    let id1 = paragraphs[1].id;
    let text1 = paragraphs[1].text();
    let id2 = paragraphs[2].id;
    let text2 = paragraphs[2].text();
    let id3 = paragraphs[3].id;

    s.click_text(FlowPos::new(id0, 1));
    for _ in 0..3 { s.key("shift-right"); }
    s.menu("docx.underline.wave");
    s.key("cmd-b");
    s.key("cmd-r");
    assert_eq!(para(&s.document(), id0).align, ibis_doc_model::FlowAlign::Right);
    let target_str: String = text0.chars().skip(1).take(3).collect();
    let source_style = para(&s.document(), id0).runs.iter().find(|r| matches!(&r.kind, FlowRunKind::Text(t) if t == &target_str)).unwrap().style.clone();

    // Lock repeat mode
    s.click_text(FlowPos::new(id0, 2));
    s.menu("docx.format-brush.lock");
    assert_eq!(s.toolbar_state("format-paint").map(|t| t.on), Some(true));

    // First application
    assert_ne!(para(&s.document(), id1).align, ibis_doc_model::FlowAlign::Right);
    s.click_text(FlowPos::new(id1, 0));
    for _ in 0..4 { s.key("shift-right"); }
    s.menu("docx.format-brush.apply");

    assert_eq!(s.toolbar_state("format-paint").map(|t| t.on), Some(true), "brush remains on in repeat mode");
    assert_eq!(para(&s.document(), id1).align, ibis_doc_model::FlowAlign::Right);
    let applied1: String = text1.chars().take(4).collect();
    assert_eq!(para(&s.document(), id1).runs.iter().find(|r| matches!(&r.kind, FlowRunKind::Text(t) if t == &applied1)).unwrap().style, source_style);

    // Second application
    assert_ne!(para(&s.document(), id2).align, ibis_doc_model::FlowAlign::Right);
    s.click_text(FlowPos::new(id2, 0));
    for _ in 0..3 { s.key("shift-right"); }
    s.menu("docx.format-brush.apply");

    assert_eq!(s.toolbar_state("format-paint").map(|t| t.on), Some(true), "brush remains on after second application");
    assert_eq!(para(&s.document(), id2).align, ibis_doc_model::FlowAlign::Right);
    let applied2: String = text2.chars().take(3).collect();
    assert_eq!(para(&s.document(), id2).runs.iter().find(|r| matches!(&r.kind, FlowRunKind::Text(t) if t == &applied2)).unwrap().style, source_style);

    // Cancel format brush with Escape
    s.key("escape");
    assert_eq!(s.toolbar_state("format-paint").map(|t| t.on), Some(false), "escape cancels format brush");

    // Undo / Redo (single step undo)
    let doc_after_apply2 = s.document();
    s.key("cmd-z");
    assert_ne!(para(&s.document(), id2).align, ibis_doc_model::FlowAlign::Right);
    s.key("cmd-shift-z");
    assert_eq!(s.document(), doc_after_apply2);

    // Shortcut copy and paste (alt-cmd-c / alt-cmd-v)
    s.click_text(FlowPos::new(id0, 2));
    s.key("alt-cmd-c");
    assert_eq!(s.toolbar_state("format-paint").map(|t| t.on), Some(true));

    assert_ne!(para(&s.document(), id3).align, ibis_doc_model::FlowAlign::Right);
    s.click_text(FlowPos::new(id3, 0));
    for _ in 0..3 { s.key("shift-right"); }
    s.key("alt-cmd-v");
    assert_eq!(para(&s.document(), id3).align, ibis_doc_model::FlowAlign::Right);

    // Save and reopen
    s.save_as("edit012-format-brush-repeat.docx");
    let saved = s.reopen();
    let p1 = body(flow(&saved)).into_iter().find(|p| p.text() == text1).unwrap();
    assert_eq!(p1.align, ibis_doc_model::FlowAlign::Right);
}

fn bullet001_bullet_symbol_and_font() {
    let mut s = Scenario::open(REPORT);
    let (_, id, text) = text_paragraph(&mut s, 10);
    s.click_text(FlowPos::new(id, 1));

    // Initially not a list item
    assert!(para(&s.document(), id).list.is_none());

    // 1. Apply square bullet from toolbar menu
    s.toolbar_menu("bullet-types", "docx.bullet.square");
    let doc1 = s.document();
    let p1 = para(&doc1, id);
    assert!(p1.list.is_some(), "paragraph became a list item");
    let l1 = p1.list.unwrap();
    let lvl1 = doc1.styles.numbering.level(l1.num_id, l1.level).expect("level exists");
    assert_eq!(lvl1.format, "bullet");
    assert_eq!(lvl1.text, "■");
    assert_eq!(lvl1.run.font.as_deref(), Some("Wingdings"));
    assert_eq!(lvl1.suffix, ibis_doc_model::ListSuffix::Tab);

    // Menu check states
    assert_eq!(s.menu_state("docx.bullet.square"), Some((true, true)));
    assert_eq!(s.menu_state("docx.bullet.disc"), Some((true, false)));
    assert_eq!(s.menu_state("docx.bullet.circle"), Some((true, false)));

    // 2. Change bullet to circle (○, Courier New)
    s.toolbar_menu("bullet-types", "docx.bullet.circle");
    let doc2 = s.document();
    let p2 = para(&doc2, id);
    let l2 = p2.list.unwrap();
    let lvl2 = doc2.styles.numbering.level(l2.num_id, l2.level).expect("level exists");
    assert_eq!(lvl2.format, "bullet");
    assert_eq!(lvl2.text, "○");
    assert_eq!(lvl2.run.font.as_deref(), Some("Courier New"));
    assert_eq!(s.menu_state("docx.bullet.circle"), Some((true, true)));
    assert_eq!(s.menu_state("docx.bullet.square"), Some((true, false)));

    // 3. Change suffix to Space
    s.menu("docx.bullet.suffix-space");
    let doc3 = s.document();
    let p3 = para(&doc3, id);
    let l3 = p3.list.unwrap();
    let lvl3 = doc3.styles.numbering.level(l3.num_id, l3.level).expect("level exists");
    assert_eq!(lvl3.suffix, ibis_doc_model::ListSuffix::Space);

    // 4. Undo and Redo
    s.key("cmd-z"); // Undo suffix change
    let doc_u1 = s.document();
    let lvl_u1 = doc_u1.styles.numbering.level(l3.num_id, l3.level).unwrap();
    assert_eq!(lvl_u1.suffix, ibis_doc_model::ListSuffix::Tab);
    assert_eq!(lvl_u1.text, "○");

    s.key("cmd-z"); // Undo circle change -> back to square
    let doc_u2 = s.document();
    let lvl_u2 = doc_u2.styles.numbering.level(l3.num_id, l3.level).unwrap();
    assert_eq!(lvl_u2.text, "■");
    assert_eq!(lvl_u2.run.font.as_deref(), Some("Wingdings"));

    s.key("cmd-z"); // Undo list application -> back to non-list
    assert!(para(&s.document(), id).list.is_none());

    s.key("cmd-shift-z"); // Redo list application
    let doc_r = s.document();
    let p_r = para(&doc_r, id);
    assert!(p_r.list.is_some());
    let l_r = p_r.list.unwrap();
    let lvl_r = doc_r.styles.numbering.level(l_r.num_id, l_r.level).unwrap().clone();
    assert_eq!(lvl_r.text, "■");

    // 5. Save and reopen
    s.save_as("bullet001.docx");
    let saved = s.reopen();
    let saved_flow = flow(&saved);
    let p_saved = body(saved_flow).into_iter().find(|p| p.text() == text).expect("the paragraph exists");
    assert!(p_saved.list.is_some(), "reopened paragraph is still a list item");
    let l_saved = p_saved.list.unwrap();
    let lvl_saved = saved_flow.styles.numbering.level(l_saved.num_id, l_saved.level).expect("saved level exists");
    assert_eq!(lvl_saved.format, "bullet");
    assert_eq!(lvl_saved.text, "■");
}

fn a9_paragraph_decorations() {
    let mut s=Scenario::open(REPORT);
    let (_,id,text)=text_paragraph(&mut s,12);
    s.click_text(FlowPos::new(id,1));
    for _ in 0..3 {s.key("shift-right");}
    let selection=s.selection();
    for (name,style) in super::paragraph_decorations::BORDERS {
        let before=s.document();
        let menu=format!("docx.paragraph.border.{name}");
        s.menu(&menu);
        assert_eq!(s.selection(),selection);
        let after=s.document();
        assert_eq!(para(&after,id).text(),text);
        assert!(para(&after,id).borders.iter().all(|b|b.is_some_and(|b|b.style==*style)));
        assert_eq!(s.menu_state(&menu),Some((true,true)));
        for p in body(&before) {if p.id!=id {assert_eq!(para(&after,p.id),p);}}
        s.key("cmd-z");assert_eq!(s.document(),before);
        s.key("cmd-shift-z");assert_eq!(s.document(),after);
        s.save_as(&format!("a9-paragraph-border-{name}.docx"));
        let saved=s.reopen();
        let p=body(flow(&saved)).into_iter().find(|p|p.text()==text).unwrap();
        assert_eq!(p.borders,para(&after,id).borders);
    }
    for (menu,width) in [("half",6350),("one",12700),("one-half",19050),("three",38100)] {
        let before=s.document();s.menu(&format!("docx.paragraph.border-width.{menu}"));let after=s.document();
        assert!(para(&after,id).borders.iter().all(|b|b.unwrap().width==width));
        s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
        s.save_as(&format!("a9-paragraph-width-{menu}.docx"));
        let saved=s.reopen();assert_eq!(body(flow(&saved)).into_iter().find(|p|p.text()==text).unwrap().borders,para(&after,id).borders);
    }
    s.menu("docx.paragraph.border-color.red");
    for (menu,color) in [("black",0),("red",0xff0000),("blue",0x0000ff),("green",0x008000)] {
        let before=s.document();s.menu(&format!("docx.paragraph.border-color.{menu}"));let after=s.document();
        assert!(para(&after,id).borders.iter().all(|b|b.unwrap().color==ibis_doc_model::Rgb(color)));
        s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
        s.save_as(&format!("a9-paragraph-color-{menu}.docx"));
        let saved=s.reopen();assert_eq!(body(flow(&saved)).into_iter().find(|p|p.text()==text).unwrap().borders,para(&after,id).borders);
    }
    s.save_as("a9-paragraph-border-color-width.docx");
    let saved=s.reopen();
    assert_eq!(body(flow(&saved)).into_iter().find(|p|p.text()==text).unwrap().borders,para(&s.document(),id).borders);
    for (name,color) in [("blue",Some(0xdeeaf6)),("green",Some(0xe2efd9)),("yellow",Some(0xfff2cc)),("red",Some(0xfbe4d5)),("gray",Some(0xd9d9d9)),("none",None)] {
        let before=s.document();s.menu(&format!("docx.paragraph.fill.{name}"));let after=s.document();
        assert_eq!(para(&after,id).shading,color.map(ibis_doc_model::Rgb));
        assert_eq!(para(&after,id).borders,para(&before,id).borders);
        s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
        s.save_as(&format!("a9-paragraph-fill-{name}.docx"));
        let saved=s.reopen();assert_eq!(body(flow(&saved)).into_iter().find(|p|p.text()==text).unwrap().shading,color.map(ibis_doc_model::Rgb));
    }
    let before=s.document();s.menu("docx.paragraph.border.none");let after=s.document();
    assert_eq!(para(&after,id).borders,[None;4]);
    s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
    s.save_as("a9-paragraph-border-none.docx");
    let saved=s.reopen();assert_eq!(body(flow(&saved)).into_iter().find(|p|p.text()==text).unwrap().borders,[None;4]);
}

fn a9_paragraph_decoration_range() {
    let mut s=Scenario::open(REPORT);
    let first=body(&s.document()).into_iter().find(|p|p.len()>0).unwrap().id;
    let before=s.document();
    s.click_text(FlowPos::new(first,0));
    s.key("cmd-a");
    s.menu("docx.paragraph.fill.yellow");
    let after=s.document();
    for p in body(&after) {assert_eq!(p.shading,Some(ibis_doc_model::Rgb(0xfff2cc)));assert_eq!(p.text(),para(&before,p.id).text());}
    assert_eq!(s.menu_state("docx.paragraph.fill.yellow"),Some((true,true)));
    for (old,new) in before.body.iter().zip(&after.body) {
        if let (Block::Table(old),Block::Table(new))=(old,new) {
            assert_eq!(new.columns,old.columns);
            for (a,b) in old.rows.iter().zip(&new.rows) {for (a,b) in a.cells.iter().zip(&b.cells) {
                assert_eq!(a.own_borders,b.own_borders);assert_eq!(a.diagonals,b.diagonals);
                for (a,b) in a.blocks.iter().zip(&b.blocks) {if let (Block::Paragraph(a),Block::Paragraph(b))=(a,b) {assert_eq!(b.shading,Some(ibis_doc_model::Rgb(0xfff2cc)));assert_eq!(b.text(),a.text());assert_eq!(b.runs,a.runs);}}
            }}
        }
    }
    s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
    s.save_as("a9-paragraph-decoration-range.docx");
    let saved=s.reopen();assert!(body(flow(&saved)).iter().all(|p|p.shading==Some(ibis_doc_model::Rgb(0xfff2cc))));
}

/// 分割ボタン（文字の色）: 左を押すと、最後に使った色（初めは既定の色）がすぐ付き、▼のパレットで選んだ色が次の色になる。
fn split_text_color_button() {
    let mut s=Scenario::open(REPORT);
    let (_,id,_)=text_paragraph(&mut s,12);
    s.click_text(FlowPos::new(id,1));for _ in 0..3 {s.key("shift-right");}
    let color=|s:&mut Scenario| s.with(|e,_| e.toolbar_items().into_iter().find_map(|t| match t {crate::shell::chrome::ToolItem::Button(b) if b.id=="text-color" => b.color,_=>None}));
    let before=color(&mut s);
    assert!(before.is_some(), "the bar of the button");
    s.toolbar("text-color");
    s.toolbar_menu("text-color","docx.color.blue");
    s.key("shift-right");
    assert_ne!(color(&mut s),before,"the button now shows the picked colour");
    s.screenshot("split");
}

fn a6_highlight_colors() {
    let mut s=Scenario::open(REPORT);
    let (_,id,text)=text_paragraph(&mut s,12);
    s.click_text(FlowPos::new(id,1));for _ in 0..3 {s.key("shift-right");}
    let selection=s.selection();let selected:String=text.chars().skip(1).take(3).collect();
    for &(menu,_,color) in super::toolbar::HIGHLIGHTS {
        let before=s.document();s.toolbar_menu("highlight",menu);let after=s.document();
        assert_eq!(s.selection(),selection);
        assert!(s.with(|e,_| e.toolbar_items().into_iter().any(|item| {
            if let crate::shell::chrome::ToolItem::Button(b)=item && b.id=="highlight" {
                return b.menu.unwrap_or_default().into_iter().any(|entry| match entry {crate::shell::chrome::MenuEntry::Item(i)=>i.id==menu && i.checked && i.enabled(),crate::shell::chrome::MenuEntry::Palette(p)=>p.find(menu).is_some_and(|i| i.checked && i.enabled()),_=>false});
            }
            false
        })));
        let p=para(&after,id);
        assert_eq!(p.text(),text);
        assert_eq!(p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t==&selected)).unwrap().style.highlight,Some(ibis_doc_model::Rgb(color)));
        assert_eq!(p.runs[0].style,para(&before,id).runs[0].style);
        s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
        s.save_as(&format!("a6-highlight-{}.docx",menu.trim_start_matches("docx.highlight.")));
        let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==text).unwrap();
        assert_eq!(p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t==&selected)).unwrap().style.highlight,Some(ibis_doc_model::Rgb(color)));
    }
    let before=s.document();s.toolbar_menu("highlight","docx.highlight-none");let after=s.document();
    assert!(para(&after,id).runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t==&selected)).unwrap().style.highlight.is_none());
    s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
    s.save_as("a6-highlight-none.docx");
    let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==text).unwrap();
    assert!(p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t==&selected)).unwrap().style.highlight.is_none());
}

fn picture_field(s:&mut Scenario,index:usize,value:&str) {
    s.update(|e,window,cx| {
        let f=e.doc_state().unwrap().picture_edit.as_ref().unwrap().fields[index].clone();
        f.update(cx,|i,cx|i.focus(window,cx));
    });
    s.key("cmd-a");if value.is_empty() {s.key("backspace");} else {s.type_text(value); }
}
fn c7_picture_size() {
    use crate::shell::scenario::button_probe as buttons;
    use gpui_kit::component::input::InputEvent;
    let _probe=buttons::Probe::new();
    let mut s=Scenario::open(REPORT);
    let(id,offset,initial)=s.with(|e,_|body(flow(e.presentation())).into_iter().find_map(|p|{let mut offset=0;for r in &p.runs{if let FlowRunKind::Picture{size,..}=r.kind{return Some((p.id,offset,size));}offset+=r.len();}None}).unwrap());
    s.click_text(FlowPos::new(id,offset));let before=s.document();let undo_before=s.with(|e,_|e.document.undo_len());
    s.menu("docx.picture.size");picture_field(&mut s,0,"90");
    let expected=ibis_doc_model::EmuSize::new(90*12700,(90.*12700.*initial.height as f64/initial.width as f64).round() as i64);
    assert_eq!(s.with(|e,_|e.picture_at_caret().unwrap().2),expected,"each typed character updates the picture without rounding its aspect ratio repeatedly");
    let after=s.document();let steps=s.with(|e,_|e.document.undo_len())-undo_before;
    s.screenshot("picture-size-live");s.click_text(FlowPos::new(id,offset));
    for _ in 0..steps{s.key("cmd-z");}assert_eq!(s.document(),before);
    for _ in 0..steps{s.key("cmd-shift-z");}assert_eq!(s.document(),after);
    s.save_as("c7-picture-ratio.docx");let saved=s.reopen();assert!(body(flow(&saved)).iter().any(|p|p.runs.iter().any(|r|matches!(r.kind,FlowRunKind::Picture{size,..}if size==expected))));
    s.menu("docx.picture.size");buttons::click(&mut s,"picture-ratio");picture_field(&mut s,0,"72");picture_field(&mut s,1,"48");
    assert_eq!(s.with(|e,_|e.picture_at_caret().unwrap().2),ibis_doc_model::EmuSize::new(72*12700,48*12700));
    for value in ["0","-1","NaN","inf","1585","abc"] {
        let before=s.document();s.update(|e,w,cx|{let f=e.doc_state().unwrap().picture_edit.as_ref().unwrap().fields[0].clone();f.update(cx,|i,cx|{i.set_value(value,w,cx);cx.emit(InputEvent::Change);});});assert_eq!(s.document(),before,"invalid pasted size must preserve the last valid picture: {value}");
    }
    s.save_as("c7-picture-unlocked.docx");let saved=s.reopen();assert!(body(flow(&saved)).iter().any(|p|p.runs.iter().any(|r|matches!(r.kind,FlowRunKind::Picture{size,..}if size==ibis_doc_model::EmuSize::new(72*12700,48*12700)))));
}

