fn c2_table_dimensions() {
    let mut s=Scenario::open(REPORT);
    let (table_id,para_id)=s.with(|e,_| {
        let t=flow(e.presentation()).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();
        let p=t.rows[0].cells[0].blocks.iter().find_map(|b|if let Block::Paragraph(p)=b {Some(p)}else{None}).unwrap();
        (t.id,p.id)
    });
    let table=|s:&mut Scenario|s.document().body.into_iter().find_map(|b|if let Block::Table(t)=b && t.id==table_id {Some(t)}else{None}).unwrap();
    s.click_text(FlowPos::new(para_id,0));
    for (name,height) in [("minimum",ibis_doc_model::RowHeight::AtLeast(30*12700)),("exact",ibis_doc_model::RowHeight::Exact(24*12700)),("auto",ibis_doc_model::RowHeight::Auto)] {
        s.menu("docx.table.size");{let rule=match name {"minimum"=>super::table_size_panel::HeightRule::AtLeast,"exact"=>super::table_size_panel::HeightRule::Exact,_=>super::table_size_panel::HeightRule::Auto};s.update(|e,w,cx|e.choose_table_height(rule,w,cx));}
        let before=s.document();let old=table(&mut s);
        table_size_field(&mut s,0,"56.5");
        if name!="auto" {table_size_field(&mut s,1,if name=="minimum" {"30"}else{"24"});}
        paragraph_submit(&mut s);let after=s.document();let t=table(&mut s);
        assert_eq!(t.columns[0],(56.5*12700.) as i64);assert_eq!(t.rows[0].height,height);
        assert_eq!(t.rows[0].cells,old.rows[0].cells);assert_eq!(t.rows[1..],old.rows[1..]);
        assert_eq!(t.rows[0].header,old.rows[0].header);assert_eq!(t.rows[0].cant_split,old.rows[0].cant_split);assert_eq!(t.columns[1..],old.columns[1..]);
        for p in body(&before) {assert_eq!(para(&after,p.id),p);}
        close_modal(&mut s);s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
        s.save_as(&format!("c2-table-{name}.docx"));let saved=s.reopen();
        let t=flow(&saved).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();
        assert_eq!(t.columns[0],(56.5*12700.) as i64);assert_eq!(t.rows[0].height,height);
    }
    s.menu("docx.table.size");s.screenshot("table-size");
    let before=s.document();s.update(|e,w,cx|e.choose_table_height(super::table_size_panel::HeightRule::Exact,w,cx));
    assert!(s.with(|e,_|e.doc_state().unwrap().table_size.as_ref().unwrap().rule==super::table_size_panel::HeightRule::Exact));
    table_size_field(&mut s,0,"84");table_size_field(&mut s,1,"18");paragraph_submit(&mut s);
    let after=s.document();assert_eq!(table(&mut s).rows[0].height,ibis_doc_model::RowHeight::Exact(18*12700));assert_eq!(table(&mut s).columns[0],84*12700);
    close_modal(&mut s);s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
    s.save_as("c2-table-buttons.docx");let saved=s.reopen();
    let t=flow(&saved).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();
    assert_eq!(t.rows[0].height,ibis_doc_model::RowHeight::Exact(18*12700));assert_eq!(t.columns[0],84*12700);
    for (index,value) in [(0,"0"),(0,"-1"),(0,"NaN"),(0,"1585"),(1,"inf"),(1,"abc")] {
        s.menu("docx.table.size");let before=s.document();table_size_field(&mut s,index,value);paragraph_submit(&mut s);assert_eq!(s.document(),before);close_modal(&mut s);
    }
    s.menu("docx.table.size");let before=s.document();table_size_field(&mut s,0,"100");
    let (other,_)=s.paragraph(0);s.update(|e,_,cx|e.set_caret(FlowPos::new(other,0),false,cx));
    s.update(|e,window,cx|e.apply_table_size(window,cx));assert_eq!(s.document(),before);
}

fn c3_cell_borders() {
    let mut s=Scenario::open(REPORT);
    let (table_id,para_id)=s.with(|e,_| {
        let t=flow(e.presentation()).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();
        let p=t.rows[0].cells[0].blocks.iter().find_map(|b|if let Block::Paragraph(p)=b {Some(p)}else{None}).unwrap();(t.id,p.id)
    });
    let table=|s:&mut Scenario|s.document().body.into_iter().find_map(|b|if let Block::Table(t)=b && t.id==table_id {Some(t)}else{None}).unwrap();
    let saved_cell=|s:&mut Scenario| {
        let p=s.reopen();let t=flow(&p).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();t.rows[0].cells[0].clone()
    };
    s.click_text(FlowPos::new(para_id,0));
    for &(name,style) in super::paragraph_decorations::BORDERS {
        let before=s.document();let old=table(&mut s);let menu=format!("docx.cell.border.{name}");s.menu(&menu);
        let after=s.document();let t=table(&mut s);
        assert_eq!(s.menu_state(&menu),Some((true,true)));
        assert!(t.rows[0].cells[0].borders.iter().all(|b|b.is_some_and(|b|b.style==style)));
        assert_eq!(t.rows[0].cells[0].blocks,old.rows[0].cells[0].blocks);assert_eq!(t.rows[0].cells[1..],old.rows[0].cells[1..]);assert_eq!(t.rows[1..],old.rows[1..]);
        for p in body(&before) {assert_eq!(para(&after,p.id),p);}
        s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
        s.save_as(&format!("c3-cell-border-{name}.docx"));assert_eq!(saved_cell(&mut s).own_borders,t.rows[0].cells[0].own_borders);
    }
    for (menu,width) in [("half",6350),("one",12700),("one-half",19050),("three",38100)] {
        let before=s.document();s.menu(&format!("docx.cell.border-width.{menu}"));let after=s.document();
        let c=table(&mut s).rows[0].cells[0].clone();assert!(c.borders.iter().all(|b|b.unwrap().width==width));
        s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
        s.save_as(&format!("c3-cell-width-{menu}.docx"));assert_eq!(saved_cell(&mut s).own_borders,c.own_borders);
    }
    s.menu("docx.cell.border-color.red");
    for (menu,color) in [("black",0),("red",0xff0000),("blue",0x0000ff),("green",0x008000)] {
        let before=s.document();s.menu(&format!("docx.cell.border-color.{menu}"));let after=s.document();
        let c=table(&mut s).rows[0].cells[0].clone();assert!(c.borders.iter().all(|b|b.unwrap().color==ibis_doc_model::Rgb(color)));
        s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
        s.save_as(&format!("c3-cell-color-{menu}.docx"));assert_eq!(saved_cell(&mut s).own_borders,c.own_borders);
    }
    let green=s.document();s.menu("docx.cell.border-color.green");assert_eq!(s.document(),green);
    s.key("cmd-z");assert!(table(&mut s).rows[0].cells[0].borders.iter().all(|b|b.unwrap().color==ibis_doc_model::Rgb(0x0000ff)),"same-value edit created an undo");
    s.key("cmd-shift-z");assert_eq!(s.document(),green);
    for (i,name) in [(0,"down"),(1,"up")] {
        for on in [true,false] {
            let before=s.document();let menu=format!("docx.cell.diagonal.{name}");s.menu(&menu);let after=s.document();
            let c=table(&mut s).rows[0].cells[0].clone();assert_eq!(c.diagonals[i].is_some(),on);
            assert_eq!(s.menu_state(&menu),Some((true,on)));
            s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
            s.save_as(&format!("c3-cell-diagonal-{name}-{on}.docx"));assert_eq!(saved_cell(&mut s).diagonals,c.diagonals);
        }
    }
    let before=s.document();s.menu("docx.cell.border.none");let after=s.document();
    assert_eq!(table(&mut s).rows[0].cells[0].borders,[None;4]);
    s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
    s.save_as("c3-cell-border-none.docx");assert_eq!(saved_cell(&mut s).own_borders,[Some(None);4]);
}

fn c4_horizontal_merge_split() {
    let mut s=Scenario::open(REPORT);
    let (table_id,para_id)=s.with(|e,_|{
        let t=flow(e.presentation()).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();
        let p=t.rows[0].cells[0].blocks.iter().find_map(|b|if let Block::Paragraph(p)=b {Some(p)}else{None}).unwrap();(t.id,p.id)
    });
    let table=|s:&mut Scenario|s.document().body.into_iter().find_map(|b|if let Block::Table(t)=b && t.id==table_id {Some(t)}else{None}).unwrap();
    s.click_text(FlowPos::new(para_id,0));
    assert_eq!(s.menu_state("docx.cell.merge-right"),Some((true,false)));
    assert_eq!(s.menu_state("docx.cell.split-grid"),Some((false,false)));
    let before=s.document();let old=table(&mut s);
    let original_blocks=old.rows[0].cells[0].blocks.iter().chain(&old.rows[0].cells[1].blocks).cloned().collect::<Vec<_>>();
    s.menu("docx.cell.merge-right");let merged=s.document();let t=table(&mut s);
    assert_eq!(t.rows[0].cells.len(),old.rows[0].cells.len()-1);
    assert_eq!(t.rows[0].cells[0].span,2);assert_eq!(t.rows[0].cells[0].blocks,original_blocks);
    assert_eq!(t.rows[1..],old.rows[1..]);assert_eq!(t.columns,old.columns);
    s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),merged);
    s.save_as("c4-cell-merge.docx");let saved=s.reopen();
    let t=flow(&saved).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();
    assert_eq!(t.rows[0].cells[0].span,2);
    let expected_text:Vec<_>=original_blocks.iter().map(|b|if let Block::Paragraph(p)=b {p.text()}else{panic!()}).collect();
    assert_eq!(t.rows[0].cells[0].blocks.iter().map(|b|if let Block::Paragraph(p)=b {p.text()}else{panic!()}).collect::<Vec<_>>(),expected_text);
    assert_eq!(s.menu_state("docx.cell.split-grid"),Some((true,false)));
    s.menu("docx.cell.split-grid");let split=s.document();let t=table(&mut s);
    assert_eq!(t.rows[0].cells.len(),old.rows[0].cells.len());assert!(t.rows[0].cells.iter().all(|c|c.span==1));
    assert_eq!(t.rows[0].cells[0].blocks,original_blocks);
    assert!(t.rows[0].cells[1].blocks.iter().all(|b|matches!(b,Block::Paragraph(p) if p.is_empty())));
    assert_eq!(t.columns,old.columns);assert_eq!(t.rows[1..],old.rows[1..]);
    s.key("cmd-z");assert_eq!(s.document(),merged);s.key("cmd-shift-z");assert_eq!(s.document(),split);
    s.save_as("c4-cell-split.docx");let saved=s.reopen();
    let t=flow(&saved).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();
    assert!(t.rows[0].cells.iter().all(|c|c.span==1));
    assert_eq!(t.rows[0].cells[0].blocks.iter().map(|b|if let Block::Paragraph(p)=b {p.text()}else{panic!()}).collect::<Vec<_>>(),expected_text);
}

fn c4_vertical_merge_and_equal_columns() {
    let mut s=Scenario::open(REPORT);
    let (table_id,para_id)=s.with(|e,_|{
        let t=flow(e.presentation()).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();
        let p=t.rows[0].cells[0].blocks.iter().find_map(|b|if let Block::Paragraph(p)=b {Some(p)}else{None}).unwrap();(t.id,p.id)
    });
    let table=|s:&mut Scenario|s.document().body.into_iter().find_map(|b|if let Block::Table(t)=b && t.id==table_id {Some(t)}else{None}).unwrap();
    // The cell below the first one made empty.
    let (below_id,below_len)=s.with(|e,_|{
        let t=flow(e.presentation()).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();
        let p=t.rows[1].cells[0].blocks.iter().find_map(|b|if let Block::Paragraph(p)=b {Some(p)}else{None}).unwrap();(p.id,p.text().chars().count())
    });
    s.click_text(FlowPos::new(below_id,below_len));
    for _ in 0..below_len {s.key("backspace");}
    s.click_text(FlowPos::new(para_id,0));
    assert_eq!(s.menu_state("docx.cell.merge-below"),Some((true,false)));
    assert_eq!(s.menu_state("docx.cell.unmerge-below"),Some((false,false)));
    let before=s.document();let old=table(&mut s);
    s.menu("docx.cell.merge-below");let merged=s.document();let t=table(&mut s);
    assert_eq!((t.rows[0].cells[0].merge,t.rows[1].cells[0].merge),(ibis_doc_model::VerticalMerge::Start,ibis_doc_model::VerticalMerge::Continue));
    assert_eq!(t.rows[0].cells.len(),old.rows[0].cells.len());
    s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),merged);
    s.save_as("c4-vertical-merge.docx");let saved=s.reopen();
    let t=flow(&saved).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();
    assert_eq!((t.rows[0].cells[0].merge,t.rows[1].cells[0].merge),(ibis_doc_model::VerticalMerge::Start,ibis_doc_model::VerticalMerge::Continue));
    assert_eq!(s.menu_state("docx.cell.unmerge-below"),Some((true,false)));
    s.menu("docx.cell.unmerge-below");let t=table(&mut s);
    assert!(t.rows.iter().all(|r|r.cells.iter().all(|c|c.merge==ibis_doc_model::VerticalMerge::None)));
    s.menu("docx.table.equal-columns");let t=table(&mut s);
    assert_eq!(t.columns.iter().sum::<i64>(),old.columns.iter().sum::<i64>());
    assert!(t.columns[..t.columns.len()-1].windows(2).all(|w|w[0]==w[1]));
}

/// 文字列を表にする・表を文字列にする: two paragraphs of two texts each
/// between a tab become a 2 × 2 table (undone, redone, saved and read
/// back), and the table becomes the paragraphs again.
fn c4_text_to_table_and_back() {
    let mut s=Scenario::open(REPORT);
    s.key("cmd-down");s.key("enter");
    s.type_text("甲");s.key("tab");s.type_text("乙");s.key("enter");
    s.type_text("丙");s.key("tab");s.type_text("丁");
    s.key("shift-up");s.key("shift-home");
    assert_eq!(s.menu_state("docx.table.from-text"),Some((true,false)));
    let before=s.document();
    s.menu("docx.table.from-text");let converted=s.document();
    let table=|d:&ibis_doc_model::FlowDocument|d.body.iter().filter_map(|b|if let Block::Table(t)=b {Some(t.clone())}else{None}).last().unwrap();
    let t=table(&converted);
    let texts=|t:&ibis_doc_model::FlowTable|t.rows.iter().map(|r|r.cells.iter().map(|c|c.blocks.iter().map(|b|if let Block::Paragraph(p)=b {p.text()}else{String::new()}).collect::<String>()).collect::<Vec<_>>()).collect::<Vec<_>>();
    assert_eq!(texts(&t),vec![vec!["甲","乙"],vec!["丙","丁"]]);
    s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),converted);
    s.save_as("c4-text-to-table.docx");let saved=s.reopen();
    assert_eq!(texts(&table(flow(&saved))),vec![vec!["甲","乙"],vec!["丙","丁"]]);
    // Back to text: the caret in the table.
    let id=t.rows[0].cells[0].blocks.iter().find_map(|b|if let Block::Paragraph(p)=b {Some(p.id)}else{None}).unwrap();
    s.click_text(FlowPos::new(id,0));
    assert_eq!(s.menu_state("docx.table.to-text"),Some((true,false)));
    s.menu("docx.table.to-text");
    let d=s.document();
    assert!(d.body.iter().all(|b|!matches!(b,Block::Table(t) if t.id==table(&converted).id)));
    let lines:Vec<String>=d.body.iter().filter_map(|b|if let Block::Paragraph(p)=b {Some(p.text())}else{None}).filter(|t|t.contains('甲')||t.contains('丙')).collect();
    assert_eq!(lines,vec!["甲\t乙".to_string(),"丙\t丁".to_string()]);
}

fn c4_complex_merge_rejected() {
    let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let data=ibis_pptx::test_files::docx_with_wrapped_cell_paragraph(&std::fs::read(root.join(REPORT)).unwrap());
    let dir=root.join("target/scenario-fixtures");std::fs::create_dir_all(&dir).unwrap();
    let path=dir.join("docx-merge-wrapped.docx");std::fs::write(&path,&data).unwrap();
    let mut s=Scenario::open(path.to_str().unwrap());
    let id=s.with(|e,_| {
        let t=flow(e.presentation()).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();
        t.rows[0].cells[0].blocks.iter().find_map(|b|if let Block::Paragraph(p)=b {Some(p.id)}else{None}).unwrap()
    });
    s.click_text(FlowPos::new(id,0));let before=s.document();s.menu("docx.cell.merge-right");
    assert_eq!(s.document(),before,"rejected merge changed document");
    assert!(s.with(|e,_|e.status.as_ref().is_some_and(|s|s.contains("保存できません"))));
    let p=s.save_as("c4-wrapped-unchanged.docx");assert_eq!(std::fs::read(p).unwrap(),data);
}

fn custom_color_field(s:&mut Scenario,value:&str) {
    s.update(|e,window,cx| {let field=e.doc_state().unwrap().color_edit.as_ref().unwrap().field.clone();field.update(cx,|i,cx|i.focus(window,cx));});
    s.key("cmd-a");if value.is_empty() {s.key("backspace");} else {s.type_text(value); }
}
fn a6_custom_colors() {
    use ibis_doc_model::Rgb;
    let mut s=Scenario::open(REPORT);
    let (_,id,text)=text_paragraph(&mut s,12);
    let selected:String=text.chars().skip(1).take(3).collect();
    for underline in [false,true] {
        s.click_text(FlowPos::new(id,1));for _ in 0..3 {s.key("shift-right");}
        if underline {s.menu("docx.underline.custom");} else {s.toolbar_menu("text-color","docx.color.custom");}
        let before=s.document();
        for invalid in ["", "12345", "1234567", "GG0000", "0x123456", "-12345"] {
            custom_color_field(&mut s,invalid);s.key("cmd-enter");assert!(s.document()==before);
            assert!(s.with(|e,_|e.doc_state().unwrap().color_edit.as_ref().unwrap().error.is_some()));
        }
        custom_color_field(&mut s,"#2a7fc1");s.key("cmd-enter");
        let after=s.document();assert!(after!=before);
        let p=para(&after,id);let run=p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t==&selected)).unwrap();
        if underline {assert_eq!(run.style.underline_color,Some(Rgb(0x2a7fc1)));assert!(run.style.underline);} else {assert_eq!(run.style.color,Rgb(0x2a7fc1));}
        assert_eq!(p.text(),text);assert_eq!(p.runs[0].style,para(&before,id).runs[0].style);
        for p in body(&before) {if p.id!=id {assert_eq!(para(&after,p.id),p);}}
        custom_color_field(&mut s,"2A7FC1");s.key("cmd-enter");assert!(s.document()==after);
        let selection_before=s.selection();s.click_text(FlowPos::new(id,8));
        assert_eq!(s.selection(),selection_before,"the modal color form preserves its frozen target");
        // A modal form blocks document Undo; close it before checking document history.
        s.key("escape");s.key("cmd-z");assert!(s.document()==before);
        s.key("cmd-shift-z");assert!(s.document()==after);
        s.save_as(if underline {"a6-custom-underline.docx"} else {"a6-custom-text.docx"});
        let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==text).unwrap();
        let run=p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t==&selected)).unwrap();
        if underline {assert_eq!(run.style.underline_color,Some(Rgb(0x2a7fc1)));} else {assert_eq!(run.style.color,Rgb(0x2a7fc1));}
    }
}

fn d4_section_start_types() {
    use ibis_doc_model::SectionBreak;
    for (name,kind) in [("continuous",SectionBreak::Continuous),("next",SectionBreak::NextPage),("odd",SectionBreak::OddPage),("even",SectionBreak::EvenPage)] {
        let mut s=Scenario::open(REPORT);
        let (_,id,text)=text_paragraph(&mut s,12);
        s.click_text(FlowPos::new(id,3));
        let before=s.document();
        s.menu(&format!("docx.section-{name}"));
        let after=s.document();assert_ne!(after,before);
        let p=para(&after,id);assert_eq!(p.section_break,kind);
        assert_eq!(p.text(),text.chars().take(3).collect::<String>());
        let remainder=body(&after).into_iter().find(|p|p.id==s.selection().unwrap().1.para).unwrap();
        assert_eq!(remainder.text(),text.chars().skip(3).collect::<String>());
        let remainder_id=remainder.id;
        let (first_page,next_page,next_number)=s.with(|e,_| {
            let pages=super::flow_layout::pages(e.flow().unwrap(),&e.resources);
            let first=pages.pages.iter().position(|p|p.items.iter().any(|i|matches!(i,super::flow_layout::Item::Line {para,..} if *para==id))).unwrap();
            let next=pages.pages.iter().position(|p|p.items.iter().any(|i|matches!(i,super::flow_layout::Item::Line {para,..} if *para==remainder_id))).unwrap();
            (first,next,pages.pages[next].number)
        });
        match kind {
            SectionBreak::Continuous=>assert_eq!(first_page,next_page),
            SectionBreak::NextPage=>assert_eq!(next_page,first_page+1),
            SectionBreak::OddPage=>{assert!(next_page>first_page);assert_eq!(next_number%2,1);},
            SectionBreak::EvenPage=>{assert!(next_page>first_page);assert_eq!(next_number%2,0);},
            _=>unreachable!(),
        }

        for p in body(&before) {if p.id!=id {assert_eq!(para(&after,p.id),p);}}
        for section in ibis_doc_model::flow_command::sections(&after) {
            assert_eq!(ibis_doc_model::flow_command::resolved_part(&after,section,ibis_doc_model::PartKind::Header),before.header);
            assert_eq!(ibis_doc_model::flow_command::resolved_part(&after,section,ibis_doc_model::PartKind::Footer),before.footer);
        }
        assert_eq!(after.styles,before.styles);
        s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
        s.save_as(&format!("d4-section-{name}.docx"));let saved=s.reopen();let d=flow(&saved);
        assert!(body(d).iter().any(|p|p.section_break==kind && p.text()==text.chars().take(3).collect::<String>()));
        assert!(body(d).iter().any(|p|p.text()==text.chars().skip(3).collect::<String>()));
    }
}

fn a9_paragraph_border_edges() {
    let mut s=Scenario::open(REPORT);let (_,id,text)=text_paragraph(&mut s,12);s.click_text(FlowPos::new(id,1));
    for (i,name) in ["top","right","bottom","left"].into_iter().enumerate() {
        let before=s.document();s.menu(&format!("docx.paragraph.border-edge.{name}"));assert_eq!(s.document(),before);
        assert_eq!(s.menu_state(&format!("docx.paragraph.border-edge.{name}")),Some((true,true)));
        for menu in ["docx.paragraph.border.double".to_string(),format!("docx.paragraph.border-width.{}",["half","one","one-half","three"][i]),format!("docx.paragraph.border-color.{}",["red","blue","green","black"][i])] {
            let step_before=s.document();s.menu(&menu);let step_after=s.document();
            if step_before!=step_after {s.key("cmd-z");assert_eq!(s.document(),step_before);s.key("cmd-shift-z");assert_eq!(s.document(),step_after);}
        }
        let after=s.document();let p=para(&after,id);assert_eq!(p.text(),text);
        for j in 0..4 {if j!=i {assert_eq!(p.borders[j],para(&before,id).borders[j]);}}
        for p in body(&before) {if p.id!=id {assert_eq!(para(&after,p.id),p);}}
        s.save_as(&format!("a9-border-edge-{name}.docx"));let saved=s.reopen();assert_eq!(body(flow(&saved)).into_iter().find(|p|p.text()==text).unwrap().borders,p.borders);
    }
    s.menu("docx.paragraph.border-edge.all");
    assert_eq!(s.menu_state("docx.paragraph.border.double"),Some((true,true)));
    for menu in ["docx.paragraph.border-color.red","docx.paragraph.border-color.blue","docx.paragraph.border-color.green","docx.paragraph.border-color.black","docx.paragraph.border-width.half","docx.paragraph.border-width.one"] {assert_eq!(s.menu_state(menu),Some((true,false)));}
    let before=s.document();s.menu("docx.paragraph.border.dotted");let after=s.document();
    for i in 0..4 {let b=para(&after,id).borders[i].unwrap();let a=para(&before,id).borders[i].unwrap();assert_eq!(b.width,a.width);assert_eq!(b.color,a.color);assert_eq!(b.style,ibis_doc_model::BorderStyle::Dotted);}
    s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
    s.menu("docx.paragraph.border.dotted");s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
    s.menu("docx.paragraph.border-edge.right");s.menu("docx.paragraph.border.none");let removed=s.document();
    s.menu("docx.paragraph.border-edge.all");assert_eq!(s.menu_state("docx.paragraph.border.none"),Some((true,false)));assert_eq!(s.menu_state("docx.paragraph.border.dotted"),Some((true,false)));
    assert!(para(&removed,id).borders[1].is_none());for i in [0,2,3] {assert_eq!(para(&removed,id).borders[i],para(&after,id).borders[i]);}
    s.key("cmd-z");assert_eq!(s.document(),after);s.key("cmd-shift-z");assert_eq!(s.document(),removed);
    s.save_as("a9-border-edge-removed.docx");let saved=s.reopen();assert_eq!(body(flow(&saved)).into_iter().find(|p|p.text()==text).unwrap().borders,para(&removed,id).borders);
}

fn c3_cell_border_edges() {
    let mut s=Scenario::open(REPORT);
    let (table_id,id)=s.with(|e,_| {let t=flow(e.presentation()).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();let p=t.rows[0].cells[0].blocks.iter().find_map(|b|if let Block::Paragraph(p)=b {Some(p)}else{None}).unwrap();(t.id,p.id)});
    let table=|d:&FlowDocument|d.body.iter().find_map(|b|if let Block::Table(t)=b && t.id==table_id {Some(t.clone())}else{None}).unwrap();
    s.click_text(FlowPos::new(id,0));
    for (i,name) in ["top","right","bottom","left"].into_iter().enumerate() {
        let before=s.document();s.menu(&format!("docx.cell.border-edge.{name}"));assert_eq!(s.document(),before);
        assert_eq!(s.menu_state(&format!("docx.cell.border-edge.{name}")),Some((true,true)));
        for menu in ["docx.cell.border.double".to_string(),format!("docx.cell.border-width.{}",["half","one","one-half","three"][i]),format!("docx.cell.border-color.{}",["red","blue","green","black"][i])] {
            let old=s.document();s.menu(&menu);let new=s.document();if old!=new {s.key("cmd-z");assert_eq!(s.document(),old);s.key("cmd-shift-z");assert_eq!(s.document(),new);}
        }
        let after=s.document();let t=table(&after);let old=table(&before);let cell=&t.rows[0].cells[0];
        for j in 0..4 {if j!=i {assert_eq!(cell.own_borders[j],old.rows[0].cells[0].own_borders[j]);}}
        assert_eq!(cell.blocks,old.rows[0].cells[0].blocks);assert_eq!(cell.diagonals,old.rows[0].cells[0].diagonals);
        assert_eq!(t.rows[0].cells[1..],old.rows[0].cells[1..]);assert_eq!(t.rows[1..],old.rows[1..]);
        s.save_as(&format!("c3-cell-edge-{name}.docx"));let saved=s.reopen();let t=flow(&saved).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();assert_eq!(t.rows[0].cells[0].own_borders,cell.own_borders);
    }
    s.menu("docx.cell.border-edge.all");
    assert_eq!(s.menu_state("docx.cell.border.double"),Some((true,true)));
    for menu in ["docx.cell.border-color.red","docx.cell.border-color.blue","docx.cell.border-color.green","docx.cell.border-color.black","docx.cell.border-width.half","docx.cell.border-width.one"] {assert_eq!(s.menu_state(menu),Some((true,false)));}
    let before=s.document();s.menu("docx.cell.border.dotted");let after=s.document();let t=table(&after);let old=table(&before);
    for i in 0..4 {let b=t.rows[0].cells[0].borders[i].unwrap();let a=old.rows[0].cells[0].borders[i].unwrap();assert_eq!(b.width,a.width);assert_eq!(b.color,a.color);}
    s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
    s.menu("docx.cell.border-edge.right");s.menu("docx.cell.border.none");let removed=s.document();
    s.menu("docx.cell.border-edge.all");assert_eq!(s.menu_state("docx.cell.border.none"),Some((true,false)));assert_eq!(s.menu_state("docx.cell.border.dotted"),Some((true,false)));assert_eq!(table(&removed).rows[0].cells[0].own_borders[1],Some(None));
    for i in [0,2,3] {assert_eq!(table(&removed).rows[0].cells[0].own_borders[i],table(&after).rows[0].cells[0].own_borders[i]);}
    s.key("cmd-z");assert_eq!(s.document(),after);s.key("cmd-shift-z");assert_eq!(s.document(),removed);
    s.save_as("c3-cell-edge-removed.docx");let saved=s.reopen();let t=flow(&saved).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();assert_eq!(t.rows[0].cells[0].own_borders,table(&removed).rows[0].cells[0].own_borders);
}

fn c3_cell_vertical_alignment() {
    use ibis_doc_model::CellAnchor;
    let root = crate::shell::scenario::repo_root();
    let original = std::fs::read(root.join(REPORT)).unwrap();
    let mut s = Scenario::open(REPORT);
    let (table_id, para_id) = s.with(|e, _| {
        let t = flow(e.presentation()).body.iter().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
        let p = t.rows[0].cells[0].blocks.iter().find_map(|b| if let Block::Paragraph(p) = b { Some(p) } else { None }).unwrap();
        (t.id, p.id)
    });
    let outside_id = body(&s.document()).into_iter().find(|p| p.field_start.is_none() && p.id != para_id).unwrap().id;
    s.click_text(FlowPos::new(outside_id, 0));
    assert_eq!(s.menu_state("docx.table.valign-top").map(|m| m.0), Some(false), "valign disabled outside table");
    assert_eq!(s.menu_state("docx.table.valign-center").map(|m| m.0), Some(false));
    assert_eq!(s.menu_state("docx.table.valign-bottom").map(|m| m.0), Some(false));

    let table = |s: &mut Scenario| s.document().body.into_iter().find_map(|b| if let Block::Table(t) = b && t.id == table_id { Some(t) } else { None }).unwrap();
    let saved_cell = |s: &mut Scenario| {
        let p = s.reopen();
        let t = flow(&p).body.iter().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
        t.rows[0].cells[0].clone()
    };

    s.click_text(FlowPos::new(para_id, 0));
    assert_eq!(s.menu_state("docx.table.valign-top"), Some((true, true)));
    assert_eq!(s.menu_state("docx.table.valign-center"), Some((true, false)));
    assert_eq!(s.menu_state("docx.table.valign-bottom"), Some((true, false)));
    assert_eq!(table(&mut s).rows[0].cells[0].anchor, CellAnchor::Top);

    // Apply Center via menu
    let before = s.document();
    let old_table = table(&mut s);
    s.menu("docx.table.valign-center");
    let center_doc = s.document();
    let t_center = table(&mut s);
    assert_eq!(t_center.rows[0].cells[0].anchor, CellAnchor::Center);
    assert_eq!(s.menu_state("docx.table.valign-center"), Some((true, true)));
    assert_eq!(s.menu_state("docx.table.valign-top"), Some((true, false)));
    assert_eq!(s.menu_state("docx.table.valign-bottom"), Some((true, false)));
    assert_eq!(t_center.rows[0].cells[0].blocks, old_table.rows[0].cells[0].blocks);
    assert_eq!(t_center.rows[0].cells[1..], old_table.rows[0].cells[1..]);
    assert_eq!(t_center.rows[1..], old_table.rows[1..]);
    for p in body(&before) {
        assert_eq!(para(&center_doc, p.id), p);
    }

    // Undo -> original
    s.key("cmd-z");
    assert_eq!(s.document(), before);
    let undone = s.save_as("b8-cell-valign-undone.docx");
    assert_eq!(std::fs::read(undone).unwrap(), original);

    // Redo -> Center
    s.key("cmd-shift-z");
    assert_eq!(s.document(), center_doc);
    let center_path = s.save_as("b8-cell-valign-center.docx");
    assert_eq!(saved_cell(&mut s).anchor, CellAnchor::Center);
    let center_bytes = std::fs::read(center_path).unwrap();
    let center_xml = ibis_pptx::test_files::part_text(&center_bytes, "word/document.xml").unwrap();
    assert!(center_xml.contains(r#"<w:vAlign w:val="center"/>"#));

    // Apply Bottom via toolbar_menu
    s.toolbar_menu("cell-valign", "docx.cell.valign-bottom");
    let bottom_doc = s.document();
    assert_eq!(table(&mut s).rows[0].cells[0].anchor, CellAnchor::Bottom);
    assert_eq!(s.menu_state("docx.table.valign-bottom"), Some((true, true)));

    // Same-value edit must be no-op (no extra undo)
    s.toolbar_menu("cell-valign", "docx.cell.valign-bottom");
    assert_eq!(s.document(), bottom_doc);
    s.key("cmd-z");
    assert_eq!(s.document(), center_doc, "same-value click did not add extra undo step");

    s.key("cmd-shift-z");
    assert_eq!(s.document(), bottom_doc);
    let bottom_path = s.save_as("b8-cell-valign-bottom.docx");
    assert_eq!(saved_cell(&mut s).anchor, CellAnchor::Bottom);
    let bottom_bytes = std::fs::read(bottom_path).unwrap();
    let bottom_xml = ibis_pptx::test_files::part_text(&bottom_bytes, "word/document.xml").unwrap();
    assert!(bottom_xml.contains(r#"<w:vAlign w:val="bottom"/>"#));

    // Apply Top via toolbar_menu
    s.toolbar_menu("cell-valign", "docx.cell.valign-top");
    assert_eq!(table(&mut s).rows[0].cells[0].anchor, CellAnchor::Top);
    assert_eq!(s.menu_state("docx.table.valign-top"), Some((true, true)));
    let top_path = s.save_as("b8-cell-valign-top.docx");
    assert_eq!(saved_cell(&mut s).anchor, CellAnchor::Top);
    let top_bytes = std::fs::read(top_path).unwrap();
    let top_xml = ibis_pptx::test_files::part_text(&top_bytes, "word/document.xml").unwrap();
    assert!(!top_xml.contains(r#"<w:vAlign w:val="center"/>"#));
    assert!(!top_xml.contains(r#"<w:vAlign w:val="bottom"/>"#));
}

fn c3_table_borders_and_margins() {
    let mut s = Scenario::open(REPORT);
    let doc = s.document();
    // 1. Check existing table default cell margins:
    let t = doc.body.iter().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).expect("table exists");
    for row in &t.rows {
        for cell in &row.cells {
            // In REPORT, the table specifies custom cell margins (99 twips = 62865 EMU)
            assert_eq!(cell.margins[1], 99 * 635, "cell right margin");
            assert_eq!(cell.margins[3], 99 * 635, "cell left margin");
        }
    }

    // 2. Check layout border items: inside horizontal and inside vertical lines do not protrude past the table bounds
    let before_path = s.save_as("c3-table-before.docx");
    let original_bytes = std::fs::read(&before_path).unwrap();

    // 3. Insert a new 3x3 table, verify default margins and borders
    let (_, id, text) = text_paragraph(&mut s, 6);
    s.click_text(FlowPos::new(id, text.chars().count()));
    s.menu("docx.table.insert-3x3");

    let doc_after = s.document();
    assert_ne!(doc_after, doc);
    let new_t = s.with(|e, _| {
        let (tbl_id, _, _) = e.table_at_caret().unwrap();
        flow(e.presentation()).body.iter().find_map(|b| if let Block::Table(t) = b && t.id == tbl_id { Some(t.clone()) } else { None }).unwrap()
    });
    assert_eq!((new_t.rows.len(), new_t.columns.len()), (3, 3));
    for row in &new_t.rows {
        for cell in &row.cells {
            assert_eq!(cell.margins[1], 108 * 635);
            assert_eq!(cell.margins[3], 108 * 635);
        }
    }

    // 4. Save and verify w:tblStyle and schema validation
    let saved_path = s.save_as("c3-table-inserted.docx");
    let saved_bytes = std::fs::read(&saved_path).unwrap();
    let saved_xml = ibis_pptx::test_files::part_text(&saved_bytes, "word/document.xml").unwrap();
    assert!(saved_xml.contains("<w:tblStyle"));

    // 5. Undo restores original document byte-for-byte
    s.key("cmd-z");
    assert_eq!(s.document(), doc);
    let undone_path = s.save_as("c3-table-undone.docx");
    assert_eq!(std::fs::read(&undone_path).unwrap(), original_bytes);

    // 6. Redo restores the table
    s.key("cmd-shift-z");
    assert_eq!(s.document(), doc_after);
    s.save_as("c3-table-redone.docx");
    let reopened = s.reopen();
    let reloaded_t = flow(&reopened).body.iter().find_map(|b| if let Block::Table(t) = b && (t.rows.len(), t.columns.len()) == (3, 3) { Some(t.clone()) } else { None }).expect("reloaded 3x3 table");
    for row in &reloaded_t.rows {
        for cell in &row.cells {
            assert_eq!(cell.margins[1], 108 * 635);
            assert_eq!(cell.margins[3], 108 * 635);
        }
    }
}

fn c4_wrapped_split_preserved() {
    let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let data=ibis_pptx::test_files::docx_with_wrapped_spanned_cell(&std::fs::read(root.join(REPORT)).unwrap());
    let dir=root.join("target/scenario-fixtures");std::fs::create_dir_all(&dir).unwrap();let path=dir.join("docx-split-wrapped.docx");std::fs::write(&path,&data).unwrap();
    let mut s=Scenario::open(path.to_str().unwrap());
    let before=s.document();let old=before.body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();let c=&old.rows[0].cells[1];assert_eq!(c.span,2);
    let id=c.blocks.iter().find_map(|b|if let Block::Paragraph(p)=b {Some(p.id)}else{None}).unwrap();s.click_text(FlowPos::new(id,0));
    assert_eq!(s.menu_state("docx.cell.split-grid"),Some((true,false)));s.menu("docx.cell.split-grid");let after=s.document();assert_ne!(after,before);
    let t=after.body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();assert_eq!(t.rows[0].cells[1].blocks,c.blocks);assert_eq!(t.rows[0].cells[1].span,1);
    assert_eq!(t.rows[0].cells[0],old.rows[0].cells[0]);assert_eq!(t.rows[1..],old.rows[1..]);assert_eq!(t.columns,old.columns);
    s.key("cmd-z");assert_eq!(s.document(),before);let undone=s.save_as("c4-wrapped-split-undone.docx");assert_eq!(std::fs::read(undone).unwrap(),data);
    s.key("cmd-shift-z");assert_eq!(s.document(),after);let path=s.save_as("c4-wrapped-split.docx");let saved=s.reopen();
    let t=flow(&saved).body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();assert_eq!(t.rows[0].cells[1].span,1);
    assert!(t.rows[0].cells[2].blocks.iter().all(|b|matches!(b,Block::Paragraph(p) if p.is_empty())));
    let original=ibis_pptx::test_files::part_text(&data,"word/document.xml").unwrap();let changed=ibis_pptx::test_files::part_text(&std::fs::read(path).unwrap(),"word/document.xml").unwrap();
    let wrapped=original.split("<w:sdt>").nth(1).unwrap().split("</w:sdt>").next().unwrap();
    assert!(changed.contains(&format!("<w:sdt>{wrapped}</w:sdt>")));assert_eq!(changed.matches("<w:sdt>").count(),original.matches("<w:sdt>").count());
}

/// The font panel's three fields are chosen from font dropdowns: set what a menu entry sets.
fn custom_font_field(s:&mut Scenario,index:usize,value:&str) {
    s.update(|e,window,cx| {let field=e.doc_state().unwrap().font_edit.as_ref().unwrap().fields[index].clone();field.update(cx,|i,cx|i.set_value(value.to_string(),window,cx));});
}
fn font_apply(s:&mut Scenario) { s.update(|e,w,cx|e.apply_font_edit(w,cx)); }
fn a6_custom_fonts() {
    let mut s=Scenario::open(REPORT);let (_,id,text)=text_paragraph(&mut s,12);s.click_text(FlowPos::new(id,1));for _ in 0..3 {s.key("shift-right");}
    let selected:String=text.chars().skip(1).take(3).collect();
    s.toolbar_menu("font","docx.font.custom");let before=s.document();
    let initial=s.with(|e,cx|e.doc_state().unwrap().font_edit.as_ref().unwrap().fields.clone().map(|field|field.read(cx).value().to_string()));
    let nonempty=initial.iter().position(|value|!value.is_empty()).unwrap();
    custom_font_field(&mut s,nonempty,"");custom_font_field(&mut s,1-nonempty,"Arial");assert_eq!(s.with(|e,cx|e.doc_state().unwrap().font_edit.as_ref().unwrap().fields[nonempty].read(cx).value().to_string()),"");font_apply(&mut s);assert_eq!(s.document(),before);assert!(s.with(|e,_|e.doc_state().unwrap().font_edit.as_ref().unwrap().error.is_some()));
    for i in 0..2 {custom_font_field(&mut s,i,&initial[i]);}
    custom_font_field(&mut s,1,&initial[1]);custom_font_field(&mut s,0,&"X".repeat(129));font_apply(&mut s);assert_eq!(s.document(),before);
    for (index,name) in [(0,"Arial"),(1,"Yu Gothic")] {
        let before=s.document();if s.with(|e,_|e.doc_state().unwrap().font_edit.is_none()) {s.toolbar_menu("font","docx.font.custom");}custom_font_field(&mut s,index,name);font_apply(&mut s);let after=s.document();assert_ne!(after,before);
        let p=para(&after,id);let run=p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t==&selected)).unwrap();
        if index==0 {assert_eq!(run.style.font.as_deref(),Some(name));} else {assert_eq!(run.style.east_asian_font.as_deref(),Some(name));}
        assert_eq!(p.text(),text);assert_eq!(p.runs[0].style,para(&before,id).runs[0].style);
        for p in body(&before) {if p.id!=id {assert_eq!(para(&after,p.id),p);}}
        close_modal(&mut s);s.key("cmd-z");assert_eq!(s.document(),before);close_modal(&mut s);s.key("cmd-shift-z");assert_eq!(s.document(),after);
        s.save_as(&format!("a6-custom-font-{index}.docx"));let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==text).unwrap();let r=p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t==&selected)).unwrap();assert_eq!(r.style,run.style);
        s.toolbar_menu("font","docx.font.custom");custom_font_field(&mut s,index,name);font_apply(&mut s);close_modal(&mut s);s.key("cmd-z");assert_eq!(s.document(),before);close_modal(&mut s);s.key("cmd-shift-z");assert_eq!(s.document(),after);
    }
    let before=s.document();s.toolbar_menu("font","docx.font.custom");s.update(|e,_,cx|e.set_caret(FlowPos::new(id,8),false,cx));custom_font_field(&mut s,0,"Calibri");font_apply(&mut s);assert_eq!(s.document(),before);assert!(s.with(|e,_|e.doc_state().unwrap().font_edit.as_ref().unwrap().error.is_some()));
    close_modal(&mut s);s.toolbar_menu("font","docx.font.custom");let before=s.document();
    custom_font_field(&mut s,0,"Times New Roman");custom_font_field(&mut s,1,"Yu Gothic");font_apply(&mut s);assert_eq!(s.document(),before);
    close_modal(&mut s);s.type_text("Z");let after=s.document();let expected=format!("{}Z{}",text.chars().take(8).collect::<String>(),text.chars().skip(8).collect::<String>());
    let p=para(&after,id);assert_eq!(p.text(),expected);let r=p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t=="Z")).unwrap();assert_eq!(r.style.font.as_deref(),Some("Times New Roman"));assert_eq!(r.style.east_asian_font.as_deref(),Some("Yu Gothic"));
    close_modal(&mut s);s.key("cmd-z");assert_eq!(s.document(),before);close_modal(&mut s);s.key("cmd-shift-z");assert_eq!(s.document(),after);
    s.save_as("a6-custom-font-pending.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==expected).unwrap();let r=p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t=="Z")).unwrap();assert_eq!(r.style.font.as_deref(),Some("Times New Roman"));assert_eq!(r.style.east_asian_font.as_deref(),Some("Yu Gothic"));

}

fn d4_section_nonbody_rejected() {
    let mut s=Scenario::open(REPORT);let before=s.document();
    let mut ids=Vec::new();
    for blocks in [&before.header,&before.footer] {ids.push(blocks.iter().find_map(|b|if let Block::Paragraph(p)=b {Some(p.id)}else{None}).unwrap());}
    let t=before.body.iter().find_map(|b|if let Block::Table(t)=b {Some(t)}else{None}).unwrap();ids.push(t.rows[0].cells[0].blocks.iter().find_map(|b|if let Block::Paragraph(p)=b {Some(p.id)}else{None}).unwrap());
    for id in ids {
        s.click_text(FlowPos::new(id,0));assert_eq!(s.selection().unwrap().1,FlowPos::new(id,0));
        for (name,kind) in [("continuous",ibis_doc_model::SectionBreak::Continuous),("next",ibis_doc_model::SectionBreak::NextPage),("odd",ibis_doc_model::SectionBreak::OddPage),("even",ibis_doc_model::SectionBreak::EvenPage)] {
            assert_eq!(s.menu_state(&format!("docx.section-{name}")),Some((false,false)));
            s.update(|e,_,cx|e.insert_section_break(kind,cx));assert_eq!(s.document(),before);
        }
    }
    let file=s.save_as("d4-nonbody-unchanged.docx");assert_eq!(std::fs::read(file).unwrap(),std::fs::read(crate::shell::scenario::repo_root().join(REPORT)).unwrap());
}

