fn a9_mixed_paragraph_decorations() {
    let mut s=Scenario::open(REPORT);
    let (first,first_length,last,length)=s.with(|e,_| {let ps=body(flow(e.presentation()));let pair=ps.windows(2).find(|ps|!ps[0].is_empty() && !ps[1].is_empty()).unwrap();(pair[0].id,pair[0].len(),pair[1].id,pair[1].len())});
    s.click_text(FlowPos::new(first,0));s.menu("docx.paragraph.fill.red");s.menu("docx.paragraph.border.single");
    s.click_text(FlowPos::new(last,0));s.menu("docx.paragraph.fill.blue");s.menu("docx.paragraph.border.double");
    s.click_text(FlowPos::new(first,0));for _ in 0..first_length+1+length {s.key("shift-right");}
    assert_eq!(s.selection(),Some((FlowPos::new(first,0),FlowPos::new(last,length))));
    let before=s.document();
    for menu in ["docx.paragraph.fill.red","docx.paragraph.fill.blue","docx.paragraph.fill.none","docx.paragraph.border.single","docx.paragraph.border.double","docx.paragraph.border.none"] {assert_eq!(s.menu_state(menu),Some((true,false)));}
    s.menu("docx.paragraph.fill.red");let filled=s.document();assert_eq!(s.menu_state("docx.paragraph.fill.red"),Some((true,true)));
    for id in [first,last] {assert_eq!(para(&filled,id).shading,Some(ibis_doc_model::Rgb(0xfbe4d5)));assert_eq!(para(&filled,id).borders,para(&before,id).borders);assert_eq!(para(&filled,id).text(),para(&before,id).text());}
    for p in body(&before) {if p.id!=first && p.id!=last {assert_eq!(para(&filled,p.id),p);}}
    s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),filled);
    s.menu("docx.paragraph.border.single");let after=s.document();assert_eq!(s.menu_state("docx.paragraph.border.single"),Some((true,true)));
    for id in [first,last] {assert!(para(&after,id).borders.iter().all(|b|b.is_some_and(|b|b.style==ibis_doc_model::BorderStyle::Single)));assert_eq!(para(&after,id).shading,para(&filled,id).shading);}
    s.key("cmd-z");assert_eq!(s.document(),filled);s.key("cmd-shift-z");assert_eq!(s.document(),after);
    s.save_as("a9-mixed-paragraph-decoration.docx");let saved=s.reopen();
    for id in [first,last] {let original=para(&after,id);let p=body(flow(&saved)).into_iter().find(|p|p.text()==original.text()).unwrap();assert_eq!(p.shading,original.shading);assert_eq!(p.borders,original.borders);}
}

