fn h9_full_paragraph_format_rejection() {
    let mut s=Scenario::open(REPORT);let (_,id,text)=text_paragraph(&mut s,12);s.menu("docx.track.record");s.click_text(FlowPos::new(id,0));for _ in 0..text.chars().count() {s.key("shift-right");}let before=s.document();s.key("cmd-b");let after=s.document();assert_ne!(after,before);assert_eq!(para(&after,id).mark_format,para(&before,id).mark_format,"tracking must not silently change the paragraph mark");assert!(para(&after,id).runs.iter().all(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Format(_)))));
    s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);s.save_as("h9-full-paragraph-format.docx");let saved=s.reopen();assert!(body(flow(&saved)).iter().find(|p|p.text()==text).unwrap().runs.iter().all(|r|r.revision.is_some()));
    s.menu("docx.track.reject-all");let rejected=s.document();assert_eq!(para(&rejected,id),para(&before,id));s.key("cmd-z");assert_eq!(s.document(),after);s.key("cmd-shift-z");assert_eq!(s.document(),rejected);s.save_as("h9-full-paragraph-rejected.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==text).unwrap();assert_eq!(p.mark_format,para(&before,id).mark_format);assert!(p.runs.iter().all(|r|r.revision.is_none()));
}

