fn h9_hidden_native_format() {
    let (mut s,id)=hidden_revision_document();s.menu("docx.track.record");assert!(!s.document().track_changes);assert!(!super::flow_layout::showing_markup());s.click_text(FlowPos::new(id,0));for _ in 0..4 {s.key("shift-right");}assert_eq!(s.selection(),Some((FlowPos::new(id,0),FlowPos::new(id,7))));let before=s.document();
    let deleted=|doc:&FlowDocument|para(doc,id).runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>();s.toolbar("bold");let after=s.document();assert_eq!(deleted(&after),deleted(&before),"hidden deleted runs retain original content, formatting and revision");assert_eq!(final_text(para(&after,id)),"abcd");assert!(para(&after,id).runs.iter().filter(|r|r.revision.is_none()).all(|r|r.style.bold));assert_eq!(after.header,before.header);assert_eq!(after.footer,before.footer);assert_eq!(after.styles,before.styles);
    s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);s.save_as("h9-hidden-native-bold.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()=="abX Ycd").unwrap();assert_eq!(p.runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>(),deleted(&before));assert_eq!(final_text(p),"abcd");
    s.toolbar_menu("text-color","docx.color.red");let red=s.document();assert_eq!(deleted(&red),deleted(&before));assert!(para(&red,id).runs.iter().filter(|r|r.revision.is_none()).all(|r|r.style.color==ibis_doc_model::Rgb(0xff0000)));s.key("cmd-z");assert_eq!(s.document(),after);s.key("cmd-shift-z");assert_eq!(s.document(),red);s.save_as("h9-hidden-native-red.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()=="abX Ycd").unwrap();assert_eq!(p.runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>(),deleted(&before));
    s.toolbar("clear-format");let clear=s.document();assert_eq!(deleted(&clear),deleted(&before));for run in para(&clear,id).runs.iter().filter(|r|r.revision.is_none()) {assert_eq!(run.format,ibis_doc_model::RunFormat {hidden:run.format.hidden,..Default::default()});}s.key("cmd-z");assert_eq!(s.document(),red);s.key("cmd-shift-z");assert_eq!(s.document(),clear);s.save_as("h9-hidden-native-clear.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()=="abX Ycd").unwrap();assert_eq!(p.runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>(),deleted(&before));s.menu("docx.track.show");
}

fn h9_hidden_caret_format() {
    let (mut s,id)=hidden_revision_document();s.menu("docx.track.record");s.click_text(FlowPos::new(id,0));for _ in 0..4 {s.key("shift-right");}s.toolbar("bold");let before=s.document();let deleted=|doc:&FlowDocument|para(doc,id).runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>();assert!(deleted(&before).iter().all(|r|!r.style.bold));
    s.click_text(FlowPos::new(id,5));assert_eq!(s.selection(),Some((FlowPos::new(id,5),FlowPos::new(id,5))));assert_eq!(s.toolbar_state("bold").map(|t|t.on),Some(true),"caret reflects preceding visible text, not hidden deleted text");s.type_text("N");let typed=s.document();assert_eq!(deleted(&typed),deleted(&before));assert!(para(&typed,id).runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t.contains('N'))).unwrap().style.bold);s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),typed);s.save_as("h9-hidden-caret-typed.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()=="abX YNcd").unwrap();assert!(p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t.contains('N'))).unwrap().style.bold);
    s.click_text(FlowPos::new(id,5));s.key("cmd-b");assert_eq!(s.toolbar_state("bold").map(|t|t.on),Some(false));s.type_text("P");let pending=s.document();assert_eq!(deleted(&pending),deleted(&before));assert!(!para(&pending,id).runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t.contains('P'))).unwrap().style.bold);s.key("cmd-z");assert_eq!(s.document(),typed);s.key("cmd-shift-z");assert_eq!(s.document(),pending);s.save_as("h9-hidden-caret-pending.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()=="abX YPNcd").unwrap();assert!(!p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t.contains('P'))).unwrap().style.bold);s.menu("docx.track.show");
}

fn h9_hidden_caret_format_edges() {
    for (name,value,from,to,caret,visible,expected,bold) in [("prefix","X Yab",0,3,3,2,"Nab",true),("suffix","abX Y",2,5,5,2,"abN",true),("all","XY",0,2,2,0,"N",false)] {
        let (mut s,id)=revision_document(value,from,to);s.menu("docx.track.record");
        if visible>0 {s.click_text(FlowPos::new(id,if name=="prefix" {3}else{0}));for _ in 0..visible {s.key("shift-right");}s.toolbar("bold");}
        else {s.menu("docx.track.show");s.click_text(FlowPos::new(id,1));s.key("shift-right");s.toolbar("bold");s.menu("docx.track.show");assert!(!para(&s.document(),id).mark.bold);assert!(para(&s.document(),id).runs.last().unwrap().style.bold);}
        let before=s.document();let deleted=para(&before,id).runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>();s.click_text(FlowPos::new(id,caret));assert_eq!(s.selection(),Some((FlowPos::new(id,caret),FlowPos::new(id,caret))));assert_eq!(s.toolbar_state("bold").map(|t|t.on),Some(bold),"{name} visible/mark format");s.type_text("N");let after=s.document();let p=para(&after,id);assert_eq!(final_text(p),expected);assert_eq!(p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t.contains('N'))).unwrap().style.bold,bold);assert_eq!(p.runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>(),deleted);assert_eq!(after.header,before.header);assert_eq!(after.footer,before.footer);assert_eq!(after.styles,before.styles);
        s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);s.save_as(&format!("h9-hidden-caret-{name}.docx"));let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==para(&after,id).text()).unwrap();assert_eq!(final_text(p),expected);assert_eq!(p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t.contains('N'))).unwrap().style.bold,bold);assert_eq!(p.runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>(),deleted);s.menu("docx.track.show");
    }
}

/// Flip 検索パネル's 大文字小文字を区別 (the box's place moves with the panel's layout, so
/// the editor's own setter is used, not a click).
pub(crate) fn toggle_find_case(s: &mut Scenario) {
    s.update(|e, _, cx| {
        let on = e.doc_state().and_then(|d| d.find.as_ref()).is_some_and(|f| f.case_sensitive);
        e.set_find_case_sensitive(!on, cx);
    });
}

/// Flip 検索パネル's 単語単位で検索.
pub(crate) fn toggle_find_whole_words(s: &mut Scenario) {
    s.update(|e, _, cx| {
        let on = e.doc_state().and_then(|d| d.find.as_ref()).is_some_and(|f| f.whole_words);
        e.set_find_whole_words(!on, cx);
    });
}

fn find_query(s:&mut Scenario,value:&str) {
    s.update(|e,window,cx| {let field=e.doc_state().unwrap().find.as_ref().unwrap().query.clone();field.update(cx,|i,cx|i.focus(window,cx));});s.key("cmd-a");s.key("backspace");s.type_text(value);
}
fn b7_hidden_find_replace() {
    let (mut s,id)=hidden_revision_document();s.menu("docx.track.record");s.click_text(FlowPos::new(id,0));for _ in 0..4 {s.key("shift-right");}s.toolbar("bold");let before=s.document();let deleted=para(&before,id).runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>();
    s.menu("edit.find-replace");s.type_text("X Y");assert!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.is_empty()),"hidden deleted text is not a final-view search result");find_query(&mut s,"bc");assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),vec![(FlowPos::new(id,1),FlowPos::new(id,6))]);s.update(|e,_,cx|e.replace_current("Q",cx));let after=s.document();let p=para(&after,id);assert_eq!(final_text(p),"aQd");assert_eq!(p.runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>(),deleted);assert!(p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t.contains('Q'))).unwrap().style.bold);assert_eq!(after.header,before.header);assert_eq!(after.footer,before.footer);assert_eq!(after.styles,before.styles);
    s.update(|e,window,cx|e.focus_handle.focus(window,cx));s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);s.save_as("b7-hidden-replaced.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==para(&after,id).text()).unwrap();assert_eq!(final_text(p),"aQd");assert_eq!(p.runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>(),deleted);
    find_query(&mut s,"Q");s.click_text(FlowPos::new(id,1));s.type_text("Z");let changed=s.document();assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),vec![(FlowPos::new(id,1),FlowPos::new(id,2))]);s.update(|e,_,cx|e.replace_current("WRONG",cx));assert_eq!(s.document(),changed,"stale search range never replaces changed text");assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),vec![(FlowPos::new(id,2),FlowPos::new(id,3))]);s.update(|e,window,cx|e.focus_handle.focus(window,cx));s.key("cmd-z");assert_eq!(s.document(),after);s.key("cmd-shift-z");assert_eq!(s.document(),changed);s.save_as("b7-hidden-stale-guard.docx");let saved=s.reopen();assert!(body(flow(&saved)).iter().any(|p|final_text(p)=="aZQd"));s.menu("docx.track.show");
}

fn b7_tracked_hidden_replace() {
    let (mut s,id)=hidden_revision_document();s.menu("docx.track.record");s.click_text(FlowPos::new(id,0));for _ in 0..4 {s.key("shift-right");}s.toolbar("bold");s.menu("docx.track.record");let before=s.document();let old=para(&before,id).runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t=="X Y")).unwrap().clone();s.menu("edit.find-replace");s.type_text("bc");assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),vec![(FlowPos::new(id,1),FlowPos::new(id,6))]);s.update(|e,_,cx|e.replace_current("Q",cx));let after=s.document();assert_eq!(final_text(para(&after,id)),"aQd");assert_eq!(para(&after,id).runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t=="X Y")).unwrap(),&old);assert!(para(&after,id).runs.iter().any(|r|matches!(&r.kind,FlowRunKind::Text(t) if t.contains('Q'))&&matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Insert))));s.update(|e,window,cx|e.focus_handle.focus(window,cx));s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);s.save_as("b7-tracked-hidden-Q.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==para(&after,id).text()).unwrap();assert_eq!(p.runs,para(&after,id).runs);assert!(flow(&saved).track_changes);
    find_query(&mut s,"Q");s.update(|e,_,cx|e.replace_current("A\nB",cx));assert_eq!(s.document(),after);
    let count=s.update(|e,_,cx|e.replace_all("Q","R",cx));assert_eq!(count,1);let all=s.document();assert_eq!(final_text(para(&all,id)),"aRd");assert_eq!(para(&all,id).runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t=="X Y")).unwrap(),&old);s.update(|e,window,cx|e.focus_handle.focus(window,cx));s.key("cmd-z");assert_eq!(s.document(),after);s.key("cmd-shift-z");assert_eq!(s.document(),all);s.save_as("b7-tracked-hidden-R.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==para(&all,id).text()).unwrap();assert_eq!(p.runs,para(&all,id).runs);assert!(flow(&saved).track_changes);
    assert_eq!(s.update(|e,_,cx|e.replace_all("R","A\nB",cx)),0);assert_eq!(s.document(),all);s.menu("docx.track.reject-all");let rejected=s.document();assert_eq!(para(&rejected,id).text(),"abX Ycd");assert!(para(&rejected,id).runs.iter().all(|r|r.revision.is_none()));s.update(|e,window,cx|e.focus_handle.focus(window,cx));s.key("cmd-z");assert_eq!(s.document(),all);s.key("cmd-shift-z");assert_eq!(s.document(),rejected);s.save_as("b7-tracked-hidden-rejected.docx");let saved=s.reopen();assert!(body(flow(&saved)).iter().any(|p|p.text()=="abX Ycd"&&p.runs.iter().all(|r|r.revision.is_none())));s.menu("docx.track.show");
}

fn h9_hidden_typed_replacement() {
    let (mut s,id)=hidden_revision_document();s.menu("docx.track.record");s.click_text(FlowPos::new(id,0));for _ in 0..4 {s.key("shift-right");}s.toolbar("bold");let before=s.document();let deleted=para(&before,id).runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>();s.click_text(FlowPos::new(id,1));s.key("shift-right");s.key("shift-right");assert_eq!(s.selection(),Some((FlowPos::new(id,1),FlowPos::new(id,6))));s.type_text("Q");let after=s.document();let p=para(&after,id);assert_eq!(final_text(p),"aQd");assert_eq!(p.runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>(),deleted,"typing over visible text retains older hidden deletion history");assert!(p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t.contains('Q'))).unwrap().style.bold);assert_eq!(after.header,before.header);assert_eq!(after.footer,before.footer);assert_eq!(after.styles,before.styles);s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);s.save_as("h9-hidden-typed-replace.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==para(&after,id).text()).unwrap();assert_eq!(p.runs,para(&after,id).runs);s.menu("docx.track.show");
}

fn h9_inserted_typed_replacement() {
    let mut s=Scenario::open(REPORT);if super::flow_layout::showing_markup() {s.menu("docx.track.show");}let (_,id,text)=text_paragraph(&mut s,12);s.click_text(FlowPos::new(id,0));for _ in text.chars() {s.key("shift-right");}s.type_text("abcd");s.menu("docx.track.record");s.click_text(FlowPos::new(id,2));s.key("cmd-b");s.type_text("Q");let before=s.document();assert_eq!(final_text(para(&before,id)),"abQcd");s.click_text(FlowPos::new(id,2));s.key("shift-right");s.type_text("R");let after=s.document();assert_eq!(final_text(para(&after,id)),"abRcd");assert!(para(&after,id).runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t.contains('R'))).unwrap().style.bold);s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);s.save_as("h9-inserted-typed-replace.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==para(&after,id).text()).unwrap();assert_eq!(p.runs,para(&after,id).runs);
    s.click_text(FlowPos::new(id,2));s.key("shift-right");s.key("shift-right");s.type_text("S");let mixed=s.document();assert_eq!(final_text(para(&mixed,id)),"abSd");assert!(para(&mixed,id).runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t.contains('S'))).unwrap().style.bold);assert_eq!(mixed.header,before.header);assert_eq!(mixed.footer,before.footer);assert_eq!(mixed.styles,before.styles);s.key("cmd-z");assert_eq!(s.document(),after);s.key("cmd-shift-z");assert_eq!(s.document(),mixed);s.save_as("h9-mixed-typed-replace.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==para(&mixed,id).text()).unwrap();assert_eq!(p.runs,para(&mixed,id).runs);
    s.menu("docx.track.reject-all");let rejected=s.document();assert_eq!(para(&rejected,id).text(),"abcd");assert!(para(&rejected,id).runs.iter().all(|r|r.revision.is_none()));s.key("cmd-z");assert_eq!(s.document(),mixed);s.key("cmd-shift-z");assert_eq!(s.document(),rejected);s.save_as("h9-typed-rejected.docx");let saved=s.reopen();assert!(body(flow(&saved)).iter().any(|p|p.text()=="abcd"&&p.runs.iter().all(|r|r.revision.is_none())));s.menu("docx.track.show");
}

fn h9_original_history_typed_replacement() {
    let root = crate::shell::scenario::repo_root();
    let data = ibis_pptx::test_files::docx_with_original_deletion_history(&std::fs::read(root.join(REPORT)).unwrap());
    let input = root.join("target/scenario-input/docx-original-history.docx");
    std::fs::create_dir_all(input.parent().unwrap()).unwrap();
    std::fs::write(&input, &data).unwrap();
    for tracked in [false, true] {
        let mut s = Scenario::open("target/scenario-input/docx-original-history.docx");
        if super::flow_layout::showing_markup() { s.menu("docx.track.show"); }
        if s.document().track_changes != tracked { s.menu("docx.track.record"); }
        let before = s.document();
        let id = body(&before).into_iter().find(|p| p.text() == "abX Ycd").unwrap().id;
        s.click_text(FlowPos::new(id, 1));s.key("shift-right");s.key("shift-right");
        assert_eq!(s.selection(), Some((FlowPos::new(id, 1), FlowPos::new(id, 6))));
        s.type_text("Q");let after = s.document();assert_eq!(final_text(para(&after, id)), "aQd");
        assert_eq!(after.header, before.header);assert_eq!(after.footer, before.footer);assert_eq!(after.styles, before.styles);
        s.key("cmd-z");assert_eq!(s.document(), before);s.key("cmd-shift-z");assert_eq!(s.document(), after);
        let saved = s.save_as(&format!("h9-original-history-typed-{tracked}.docx"));
        let xml = ibis_pptx::test_files::part_text(&std::fs::read(saved).unwrap(), "word/document.xml").unwrap();
        assert!(xml.contains(ibis_pptx::test_files::ORIGINAL_DELETION_XML), "old ZIP deletion XML must remain separate and exact");
        let reread = s.reopen();let p = body(flow(&reread)).into_iter().find(|p| final_text(p) == "aQd").unwrap();assert_eq!(p.runs, para(&after, id).runs);
        if tracked {
            s.menu("docx.track.reject-all");let rejected = s.document();assert_eq!(para(&rejected, id).text(), "abX Ycd");assert!(para(&rejected, id).runs.iter().all(|r|r.revision.is_none()));
            s.key("cmd-z");assert_eq!(s.document(), after);s.key("cmd-shift-z");assert_eq!(s.document(), rejected);
            s.save_as("h9-original-history-rejected.docx");let reread=s.reopen();assert!(body(flow(&reread)).iter().any(|p|p.text()=="abX Ycd"&&p.runs.iter().all(|r|r.revision.is_none())));
        }
        s.menu("docx.track.show");
    }
}

fn b7_hidden_history_edges() {
    let root=crate::shell::scenario::repo_root();
    let data=ibis_pptx::test_files::docx_with_search_history_edges(&std::fs::read(root.join(REPORT)).unwrap());
    let input=root.join("target/scenario-input/docx-search-history-edges.docx");std::fs::create_dir_all(input.parent().unwrap()).unwrap();std::fs::write(input,&data).unwrap();
    for tracked in [false,true] {
        let mut s=Scenario::open("target/scenario-input/docx-search-history-edges.docx");
        if super::flow_layout::showing_markup() {s.menu("docx.track.show");}
        if s.document().track_changes!=tracked {s.menu("docx.track.record");}
        let before=s.document();let prefix=body(&before).into_iter().find(|p|p.text()=="X Ypq").unwrap().id;let suffix=body(&before).into_iter().find(|p|p.text()=="rsX Y").unwrap().id;let multiple=body(&before).into_iter().find(|p|p.text()=="abX Ycd abX Ycd").unwrap().id;
        s.menu("edit.find-replace");s.type_text("X Y");assert!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.is_empty()),"including all-deleted paragraph, old history is not searchable");
        for (name,query,id,from,to) in [("prefix","pq",prefix,3,5),("suffix","rs",suffix,0,2)] {
            find_query(&mut s,query);assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),vec![(FlowPos::new(id,from),FlowPos::new(id,to))]);s.update(|e,_,cx|e.replace_current("UV",cx));let after=s.document();assert_eq!(final_text(para(&after,id)),"UV");
            assert_eq!(after.header,before.header);assert_eq!(after.footer,before.footer);assert_eq!(after.styles,before.styles);
            s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);
            let file=s.save_as(&format!("b7-history-{name}-{tracked}.docx"));let xml=ibis_pptx::test_files::part_text(&std::fs::read(file).unwrap(),"word/document.xml").unwrap();for id in ["841","842","843","844","845"] {assert!(xml.contains(&ibis_pptx::test_files::ORIGINAL_DELETION_XML.replace("841",id)));}let reread=s.reopen();assert!(body(flow(&reread)).iter().any(|p|p.runs==para(&after,id).runs));s.key("cmd-z");assert_eq!(s.document(),before);
        }
        find_query(&mut s,"bc");assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),vec![(FlowPos::new(multiple,1),FlowPos::new(multiple,6)),(FlowPos::new(multiple,9),FlowPos::new(multiple,14))]);assert_eq!(s.update(|e,_,cx|e.replace_all("bc","Q",cx)),2);let after=s.document();assert_eq!(final_text(para(&after,multiple)),"aQd aQd");
        assert_eq!(after.header,before.header);assert_eq!(after.footer,before.footer);assert_eq!(after.styles,before.styles);
        s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),before,"both replacements are one undo");s.key("cmd-shift-z");assert_eq!(s.document(),after);
        let file=s.save_as(&format!("b7-history-multiple-{tracked}.docx"));let xml=ibis_pptx::test_files::part_text(&std::fs::read(file).unwrap(),"word/document.xml").unwrap();for id in ["841","842","843","844","845"] {assert!(xml.contains(&ibis_pptx::test_files::ORIGINAL_DELETION_XML.replace("841",id)),"old deletion {id} changed");}let reread=s.reopen();assert!(body(flow(&reread)).iter().any(|p|p.runs==para(&after,multiple).runs));
        if tracked {
            let commands=ibis_doc_model::flow_command::resolve_revisions(&before,None,false);let mut base=s.with(|e,_|e.presentation().clone());base.flow=Some(std::sync::Arc::new(before.clone()));let mut expected=ibis_doc_model::Document::new(base);expected.execute(commands.into_iter().map(ibis_doc_model::Command::Flow).collect()).unwrap();
            s.menu("docx.track.reject-all");let rejected=s.document();assert_eq!(rejected.body,flow(expected.presentation()).body);s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),after);s.key("cmd-shift-z");assert_eq!(s.document(),rejected);s.save_as("b7-history-multiple-rejected.docx");let reread=s.reopen();assert!(body(flow(&reread)).iter().any(|p|p.text()=="abX Ycd abX Ycd"&&p.runs.iter().all(|r|r.revision.is_none())));
        }
        s.menu("docx.track.show");
    }
}

