fn a11_hidden_source() {
    for all_hidden in [false,true] {
        let (mut s,id)=if all_hidden {revision_document("XY",0,2)}else{revision_document("abX Y",2,5)};s.menu("docx.track.record");
        if all_hidden {s.menu("docx.track.show");s.click_text(FlowPos::new(id,1));s.key("shift-right");s.toolbar("bold");s.menu("docx.track.show");}
        else {s.click_text(FlowPos::new(id,0));s.key("shift-right");s.key("shift-right");s.toolbar("bold");}
        let before=s.document();let source=if all_hidden {para(&before,id).mark.clone()}else{para(&before,id).runs.first().unwrap().style.clone()};assert_eq!(source.bold,!all_hidden);
        let deleted=para(&before,id).runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>();
        let target=body(&before).into_iter().find(|p|p.id!=id&&p.len()>=3&&p.runs.iter().all(|r|matches!(r.kind,FlowRunKind::Text(_)))).unwrap().id;
        let target_text=para(&before,target).text();let selected=target_text.chars().take(2).collect::<String>();
        s.click_text(FlowPos::new(id,if all_hidden {2}else{5}));s.toolbar("format-paint");s.click_text(FlowPos::new(target,0));s.key("shift-right");s.key("shift-right");s.menu("docx.format-brush.apply");let after=s.document();let run=para(&after,target).runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t==&selected)).unwrap();assert_eq!(run.style,source,"brush uses visible/mark source instead of hidden last deleted run");assert_eq!(para(&after,id).runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>(),deleted);assert_eq!(after.header,before.header);assert_eq!(after.footer,before.footer);assert_eq!(after.styles,before.styles);
        s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);s.save_as(&format!("a11-hidden-source-{all_hidden}.docx"));let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==target_text).unwrap();assert_eq!(p.runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t==&selected)).unwrap().style,source);s.menu("docx.track.show");
    }
}

fn a11_tracked_table_rejection() {
    let root=crate::shell::scenario::repo_root();let data=ibis_pptx::test_files::docx_with_nested_table(&std::fs::read(root.join(REPORT)).unwrap());let input=root.join("target/scenario-input/docx-brush-tracked-table.docx");std::fs::create_dir_all(input.parent().unwrap()).unwrap();std::fs::write(input,&data).unwrap();let mut s=Scenario::open("target/scenario-input/docx-brush-tracked-table.docx");
    let (_,id,text)=text_paragraph(&mut s,12);s.click_text(FlowPos::new(id,1));for _ in 0..3 {s.key("shift-right");}s.menu("docx.underline.wave");s.menu("docx.underline.red");s.key("cmd-b");let selected=text.chars().skip(1).take(3).collect::<String>();let source=para(&s.document(),id).runs.iter().find(|r|matches!(&r.kind,FlowRunKind::Text(t) if t==&selected)).unwrap().style.clone();
    if !s.document().track_changes {s.menu("docx.track.record");}s.toolbar("format-paint");s.key("cmd-a");let before=s.document();s.menu("docx.format-brush.apply");let after=s.document();
    fn check(blocks:&[Block],style:&ibis_doc_model::FlowRunStyle) {for b in blocks {match b {Block::Paragraph(p)=>for r in &p.runs {assert_eq!(&r.style,style);assert!(matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Format(_))));},Block::Table(t)=>for row in &t.rows {for cell in &row.cells {check(&cell.blocks,style);}}}}}
    check(&after.body,&source);assert_eq!(after.header,before.header);assert_eq!(after.footer,before.footer);assert_eq!(after.styles,before.styles);
    s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);s.save_as("a11-tracked-table-brush.docx");let saved=s.reopen();check(&flow(&saved).body,&source);
    s.menu("docx.track.reject-all");let rejected=s.document();assert_eq!(rejected.body,before.body,"reject restores text, run properties, marks and table metadata");assert_eq!(rejected.header,before.header);assert_eq!(rejected.footer,before.footer);assert_eq!(rejected.styles,before.styles);s.key("cmd-z");assert_eq!(s.document(),after);s.key("cmd-shift-z");assert_eq!(s.document(),rejected);s.save_as("a11-tracked-table-rejected.docx");let saved=s.reopen();
    fn untracked(blocks:&[Block]) {for b in blocks {match b {Block::Paragraph(p)=>assert!(p.runs.iter().all(|r|r.revision.is_none())),Block::Table(t)=>for row in &t.rows {for cell in &row.cells {untracked(&cell.blocks);}}}}}untracked(&flow(&saved).body);
}

fn b7_unicode_lowercase_offsets() {
    let (mut s,id)=revision_document("AİX YZB İZ",2,5);s.menu("docx.track.record");s.click_text(FlowPos::new(id,1));s.key("shift-right");s.toolbar("bold");let before=s.document();let deleted=para(&before,id).runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>();
    s.menu("edit.find-replace");s.type_text("İ");assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),vec![(FlowPos::new(id,1),FlowPos::new(id,2)),(FlowPos::new(id,8),FlowPos::new(id,9))],"a character must find itself even when lowercase expands");
    find_query(&mut s,"\u{0307}");assert!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.is_empty()),"a partial lowercase expansion must not become a destructive source range");
    find_query(&mut s,"i\u{0307}Z");assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),vec![(FlowPos::new(id,1),FlowPos::new(id,6)),(FlowPos::new(id,8),FlowPos::new(id,10))]);
    find_query(&mut s,"İZ");assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),vec![(FlowPos::new(id,1),FlowPos::new(id,6)),(FlowPos::new(id,8),FlowPos::new(id,10))]);assert_eq!(s.update(|e,_,cx|e.replace_all("İZ","Q",cx)),2);let after=s.document();let p=para(&after,id);assert_eq!(final_text(p),"AQB Q");assert!(p.format_at(2).2.bold);assert!(!p.format_at(8).2.bold);assert_eq!(p.runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>(),deleted);assert_eq!(after.header,before.header);assert_eq!(after.footer,before.footer);assert_eq!(after.styles,before.styles);
    s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);s.save_as("b7-unicode-replaced.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|final_text(p)=="AQB Q").unwrap();assert_eq!(p.runs,para(&after,id).runs);s.menu("docx.track.show");
}

fn a9_stale_paragraph_details() {
    let mut s=Scenario::open(REPORT);let (_,id,text)=text_paragraph(&mut s,12);s.click_text(FlowPos::new(id,1));let before=s.document();s.menu("docx.paragraph.details");paragraph_field(&mut s,0,"17");paragraph_submit(&mut s);let after=s.document();assert_eq!(para(&after,id).space_before,17*12_700);// The modal blocks Cmd+Z; the document changes underneath it as it would from another window.
    s.update(|e,w,cx|e.undo(&crate::Undo,w,cx));assert_eq!(s.document(),before);
    for value in ["17","19"] {paragraph_field(&mut s,0,value);paragraph_submit(&mut s);assert_eq!(s.document(),before,"stale document rejects without mutation");assert!(s.with(|e,_|e.doc_state().unwrap().paragraph_edit.as_ref().unwrap().error.is_some()),"stale panel must explain reopening instead of silently doing nothing");}
    let guarded=s.save_as("a9-stale-paragraph-guard.docx");assert_eq!(std::fs::read(guarded).unwrap(),std::fs::read(crate::shell::scenario::repo_root().join(REPORT)).unwrap());s.update(|e,w,cx|e.focus_handle.focus(w,cx));close_modal(&mut s);s.key("cmd-shift-z");assert_eq!(s.document(),after,"rejections preserve redo stack");
    s.menu("docx.paragraph.details");paragraph_field(&mut s,0,"19");paragraph_submit(&mut s);let recovered=s.document();assert_eq!(para(&recovered,id).space_before,19*12_700);assert!(s.with(|e,_|e.doc_state().unwrap().paragraph_edit.as_ref().unwrap().error.is_none()));assert_eq!(recovered.header,before.header);assert_eq!(recovered.footer,before.footer);assert_eq!(recovered.styles,before.styles);close_modal(&mut s);s.key("cmd-z");assert_eq!(s.document(),after);close_modal(&mut s);s.key("cmd-shift-z");assert_eq!(s.document(),recovered);s.save_as("a9-stale-paragraph-recovered.docx");let saved=s.reopen();let p=body(flow(&saved)).into_iter().find(|p|p.text()==text).unwrap();assert_eq!(paragraph_metrics(p),paragraph_metrics(para(&recovered,id)));
}

fn b7_first_even_story_search() {
    use ibis_doc_model::PartKind;
    let root=crate::shell::scenario::repo_root();let mut s=Scenario::open(REPORT);let (_,id,_)=text_paragraph(&mut s,12);s.click_text(FlowPos::new(id,1));s.menu("docx.section.title-page");s.menu("docx.section.even-odd");
    let stories=[("docx.section.edit-first-header",PartKind::HeaderFirst),("docx.section.edit-first-footer",PartKind::FooterFirst),("docx.section.edit-even-header",PartKind::HeaderEven),("docx.section.edit-even-footer",PartKind::FooterEven)];
    for (index,(menu,_)) in stories.iter().enumerate() {s.menu(menu);s.type_text(&format!("StoryFind{index}"));}
    let input=root.join("target/scenario-input/docx-search-stories-ui-base.docx");std::fs::create_dir_all(input.parent().unwrap()).unwrap();s.save_as(input.to_str().unwrap());drop(s);let mut s=Scenario::open("target/scenario-input/docx-search-stories-ui-base.docx");let before=s.document();
    s.menu("edit.find-replace");s.type_text("StoryFind0");
    for (index,(_,kind)) in stories.iter().enumerate() {
        let query=format!("StoryFind{index}");find_query(&mut s,&query);let blocks=ibis_doc_model::flow_command::resolved_part(&before,0,*kind);let p=blocks.iter().find_map(|b|if let Block::Paragraph(p)=b&&p.text().contains(&query) {Some(p)}else{None}).unwrap();let text=p.text();let start=text[..text.find(&query).unwrap()].chars().count();assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),vec![(FlowPos::new(p.id,start),FlowPos::new(p.id,start+query.chars().count()))],"first/even story has one real search result");
    }
    assert_eq!(s.update(|e,_,cx|e.replace_all("StoryFind","StoryDone",cx)),stories.len());let after=s.document();assert_eq!(after.body,before.body);assert_eq!(after.header,before.header);assert_eq!(after.footer,before.footer);assert_eq!(after.styles,before.styles);s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),before);let undone=s.save_as("b7-first-even-stories-undone.docx");assert_eq!(std::fs::read(undone).unwrap(),std::fs::read(root.join("target/scenario-input/docx-search-stories-ui-base.docx")).unwrap());s.key("cmd-shift-z");assert_eq!(s.document(),after);s.save_as("b7-first-even-stories-replaced.docx");let saved=s.reopen();
    for (index,(_,kind)) in stories.iter().enumerate() {let blocks=ibis_doc_model::flow_command::resolved_part(flow(&saved),0,*kind);assert!(blocks.iter().any(|b|matches!(b,Block::Paragraph(p) if p.text().contains(&format!("StoryDone{index}")))));}
}

fn b7_section_story_search() {
    use ibis_doc_model::{PartKind,flow_command};
    let root=crate::shell::scenario::repo_root();let mut s=Scenario::open(REPORT);let (_,id,text)=text_paragraph(&mut s,12);s.click_text(FlowPos::new(id,text.chars().count()/2));s.menu("docx.section-next");s.click_text(FlowPos::new(id,1));s.menu("docx.section.edit-header");s.type_text("SectionNeedle");
    let input=root.join("target/scenario-input/docx-search-section-story-base.docx");std::fs::create_dir_all(input.parent().unwrap()).unwrap();s.save_as(input.to_str().unwrap());drop(s);let data=std::fs::read(&input).unwrap();let mut s=Scenario::open("target/scenario-input/docx-search-section-story-base.docx");let before=s.document();let section=flow_command::sections(&before)[0];let setup=flow_command::section_setup(&before,section).unwrap();assert!(setup.parts[PartKind::Header.index()].is_some());assert!(before.linked[PartKind::Header.index()]);let blocks=flow_command::resolved_part(&before,section,PartKind::Header);let p=blocks.iter().find_map(|b|if let Block::Paragraph(p)=b&&p.text().contains("SectionNeedle") {Some(p)}else{None}).unwrap();let value=p.text();let start=value[..value.find("SectionNeedle").unwrap()].chars().count();let expected=vec![(FlowPos::new(p.id,start),FlowPos::new(p.id,start+"SectionNeedle".chars().count()))];
    s.menu("edit.find-replace");s.type_text("SectionNeedle");assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),expected,"inherited story is one source match");for forward in [true,false,true] {s.update(|e,_,cx|e.find_next(forward,cx));assert_eq!(s.selection(),Some(expected[0]));}
    s.update(|e,_,cx|e.replace_current("SectionChanged",cx));let after=s.document();let mut changed_setup=flow_command::section_setup(&after,section).unwrap();changed_setup.parts[PartKind::Header.index()]=setup.parts[PartKind::Header.index()].clone();assert_eq!(changed_setup,setup);let mut body=after.body.clone();for block in &mut body {if let Block::Paragraph(p)=block&&p.id==section {p.section=para(&before,section).section.clone();}}assert_eq!(body,before.body);assert_eq!(after.header,before.header);assert_eq!(after.footer,before.footer);assert_eq!(after.styles,before.styles);
    s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),before);let undone=s.save_as("b7-section-story-undone.docx");assert_eq!(std::fs::read(undone).unwrap(),data);s.key("cmd-shift-z");assert_eq!(s.document(),after);let file=s.save_as("b7-section-story-replaced.docx");let saved_bytes=std::fs::read(file).unwrap();for name in ["word/document.xml","word/styles.xml","word/settings.xml","word/numbering.xml"] {assert_eq!(ibis_pptx::test_files::part_text(&data,name),ibis_pptx::test_files::part_text(&saved_bytes,name),"outside part changed: {name}");}let saved=s.reopen();let first=flow_command::sections(flow(&saved))[0];let resolved=flow_command::resolved_part(flow(&saved),first,PartKind::Header);assert!(resolved.iter().any(|b|matches!(b,Block::Paragraph(p) if p.text().contains("SectionChanged"))));let inherited=flow_command::resolved_part(flow(&saved),0,PartKind::Header);assert_eq!(resolved,inherited);
}

fn b7_case_sensitive() {
    let mut s=Scenario::open(REPORT);let (_,id,text)=text_paragraph(&mut s,12);s.click_text(FlowPos::new(id,0));for _ in text.chars() {s.key("shift-right");}s.type_text("Case CASE case");let before=s.document();s.menu("edit.find-replace");s.type_text("case");assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.len()),3);s.screenshot("case-option-off");
    toggle_find_case(&mut s);assert_eq!(s.document(),before);assert!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().case_sensitive));assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),vec![(FlowPos::new(id,10),FlowPos::new(id,14))]);s.screenshot("case-option-on");
    for (query,from,to) in [("Case",0,4),("CASE",5,9),("case",10,14)] {find_query(&mut s,query);assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),vec![(FlowPos::new(id,from),FlowPos::new(id,to))]);}
    find_query(&mut s,"Case");s.update(|e,_,cx|e.replace_current("Title",cx));let current=s.document();assert_eq!(para(&current,id).text(),"Title CASE case");assert!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.is_empty()));s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),current);s.save_as("b7-case-current.docx");let saved=s.reopen();assert!(body(flow(&saved)).iter().any(|p|p.runs==para(&current,id).runs));s.key("cmd-z");assert_eq!(s.document(),before);find_query(&mut s,"case");
    assert_eq!(s.update(|e,_,cx|e.replace_all("case","lower",cx)),1);let strict=s.document();assert_eq!(para(&strict,id).text(),"Case CASE lower");assert_eq!(strict.header,before.header);assert_eq!(strict.footer,before.footer);assert_eq!(strict.styles,before.styles);s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),strict);s.save_as("b7-case-sensitive-lower.docx");let saved=s.reopen();assert!(body(flow(&saved)).iter().any(|p|p.runs==para(&strict,id).runs));
    toggle_find_case(&mut s);assert_eq!(s.document(),strict);assert!(!s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().case_sensitive));assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.len()),2);assert_eq!(s.update(|e,_,cx|e.replace_all("case","Q",cx)),2);let insensitive=s.document();assert_eq!(para(&insensitive,id).text(),"Q Q lower");s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),strict);s.key("cmd-shift-z");assert_eq!(s.document(),insensitive);s.save_as("b7-case-insensitive.docx");let saved=s.reopen();assert!(body(flow(&saved)).iter().any(|p|p.runs==para(&insensitive,id).runs));
}

fn b7_whole_words() {
    let mut s=Scenario::open(REPORT);let (_,id,text)=text_paragraph(&mut s,12);s.click_text(FlowPos::new(id,0));for _ in text.chars(){s.key("shift-right");}s.type_text("cat cats scatter _cat cat2 (cat) CAT cat");let before=s.document();s.menu("edit.find-replace");s.type_text("cat");assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.len()),8);
    toggle_find_whole_words(&mut s);assert!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().whole_words));assert_eq!(s.document(),before);assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),vec![(FlowPos::new(id,0),FlowPos::new(id,3)),(FlowPos::new(id,28),FlowPos::new(id,31)),(FlowPos::new(id,33),FlowPos::new(id,36)),(FlowPos::new(id,37),FlowPos::new(id,40))]);s.screenshot("whole-word-on");
    toggle_find_case(&mut s);assert!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().case_sensitive));assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.len()),3);toggle_find_whole_words(&mut s);assert!(!s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().whole_words));assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.len()),7);assert_eq!(s.document(),before);toggle_find_whole_words(&mut s);assert!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().whole_words));assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.len()),3);assert_eq!(s.update(|e,_,cx|e.replace_all("cat","dog",cx)),3);let after=s.document();assert_eq!(para(&after,id).text(),"dog cats scatter _cat cat2 (dog) CAT dog");assert_eq!(after.header,before.header);assert_eq!(after.footer,before.footer);assert_eq!(after.styles,before.styles);s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);s.save_as("b7-whole-word-strict.docx");let saved=s.reopen();assert!(body(flow(&saved)).iter().any(|p|p.runs==para(&after,id).runs));
    s.key("cmd-z");toggle_find_case(&mut s);find_query(&mut s,"cat");assert_eq!(s.update(|e,_,cx|e.replace_all("cat","Q",cx)),4);let after=s.document();assert_eq!(para(&after,id).text(),"Q cats scatter _cat cat2 (Q) Q Q");s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);s.save_as("b7-whole-word-insensitive.docx");let saved=s.reopen();assert!(body(flow(&saved)).iter().any(|p|p.runs==para(&after,id).runs));
}

fn b7_whole_words_history() {
    let root=crate::shell::scenario::repo_root();let data=ibis_pptx::test_files::docx_with_original_deletion_history(&std::fs::read(root.join(REPORT)).unwrap());let input=root.join("target/scenario-input/docx-whole-word-history.docx");std::fs::create_dir_all(input.parent().unwrap()).unwrap();std::fs::write(input,&data).unwrap();
    for tracked in [false,true] {
        let mut s=Scenario::open("target/scenario-input/docx-whole-word-history.docx");if super::flow_layout::showing_markup(){s.menu("docx.track.show");}if s.document().track_changes!=tracked{s.menu("docx.track.record");}let before=s.document();let id=body(&before).into_iter().find(|p|p.text()=="abX Ycd").unwrap().id;s.menu("edit.find-replace");s.type_text("bc");assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.len()),1);toggle_find_whole_words(&mut s);assert!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.is_empty()),"hidden gap does not make a visible word boundary");find_query(&mut s,"abcd");assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),vec![(FlowPos::new(id,0),FlowPos::new(id,7))]);s.update(|e,_,cx|e.replace_current("Q",cx));let after=s.document();assert_eq!(final_text(para(&after,id)),"Q");assert_eq!(after.header,before.header);assert_eq!(after.footer,before.footer);assert_eq!(after.styles,before.styles);s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);let file=s.save_as(&format!("b7-whole-word-history-{tracked}.docx"));let xml=ibis_pptx::test_files::part_text(&std::fs::read(file).unwrap(),"word/document.xml").unwrap();assert!(xml.contains(ibis_pptx::test_files::ORIGINAL_DELETION_XML));let saved=s.reopen();assert!(body(flow(&saved)).iter().any(|p|p.runs==para(&after,id).runs));
        if tracked{s.menu("docx.track.reject-all");assert_eq!(para(&s.document(),id).text(),"abX Ycd");}s.menu("docx.track.show");
    }
}

fn b7_note_story_search() {
    use ibis_doc_model::flow_command;
    let root=crate::shell::scenario::repo_root();let mut s=Scenario::open(REPORT);let (_,id,_)=text_paragraph(&mut s,12);
    for (menu,at) in [("docx.footnote",3),("docx.endnote",8)]{s.click_text(FlowPos::new(id,at));s.menu(menu);s.type_text("NoteNeedle");}
    let input=root.join("target/scenario-input/docx-search-note-stories.docx");std::fs::create_dir_all(input.parent().unwrap()).unwrap();s.save_as(input.to_str().unwrap());drop(s);let data=std::fs::read(&input).unwrap();let mut s=Scenario::open("target/scenario-input/docx-search-note-stories.docx");let before=s.document();assert_eq!(before.footnotes.len(),1);assert_eq!(before.endnotes.len(),1);
    let mut expected=Vec::new();for notes in [&before.footnotes,&before.endnotes]{for note in notes{for block in &note.blocks{if let Block::Paragraph(p)=block{let text=p.text();if let Some(at)=text.find("NoteNeedle"){let from=text[..at].chars().count();expected.push((FlowPos::new(p.id,from),FlowPos::new(p.id,from+10)));}}}}}assert_eq!(expected.len(),2);
    s.menu("edit.find-replace");s.type_text("NoteNeedle");assert_eq!(s.with(|e,_|e.doc_state().unwrap().find.as_ref().unwrap().matches.clone()),expected,"footnote and endnote source stories searched");for forward in [true,false,true]{s.update(|e,_,cx|e.find_next(forward,cx));assert!(expected.contains(&s.selection().unwrap()));}s.update(|e,_,cx|e.find_next(false,cx));assert_eq!(s.selection(),Some(expected[0]),"the footnote is the one shown");find_query(&mut s,"NoteNeedle");s.update(|e,_,cx|e.replace_current("FootChanged",cx));let current=s.document();assert_eq!(current.endnotes,before.endnotes);assert_eq!(current.body,before.body);assert_eq!(current.header,before.header);assert_eq!(current.styles,before.styles);assert!(flow_command::paragraph(&current,expected[0].0.para).unwrap().text().contains("FootChanged"));s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),before);let undone=s.save_as("b7-notes-undone.docx");assert_eq!(std::fs::read(undone).unwrap(),data);s.key("cmd-shift-z");assert_eq!(s.document(),current);let file=s.save_as("b7-note-current.docx");let bytes=std::fs::read(file).unwrap();for name in ["word/document.xml","word/styles.xml","word/endnotes.xml"]{assert_eq!(ibis_pptx::test_files::part_text(&bytes,name),ibis_pptx::test_files::part_text(&data,name),"outside part changed {name}");}let saved=s.reopen();assert_eq!(flow(&saved).footnotes[0].blocks,current.footnotes[0].blocks);
    s.key("cmd-z");assert_eq!(s.document(),before);find_query(&mut s,"NoteNeedle");assert_eq!(s.update(|e,_,cx|e.replace_all("NoteNeedle","NoteDone",cx)),2);let after=s.document();assert_eq!(after.body,before.body);assert_eq!(after.header,before.header);assert_eq!(after.footer,before.footer);assert_eq!(after.styles,before.styles);s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);let file=s.save_as("b7-note-all.docx");let bytes=std::fs::read(file).unwrap();for name in ["word/document.xml","word/styles.xml","word/settings.xml","word/numbering.xml"]{assert_eq!(ibis_pptx::test_files::part_text(&bytes,name),ibis_pptx::test_files::part_text(&data,name));}let saved=s.reopen();assert_eq!(flow(&saved).footnotes[0].blocks,after.footnotes[0].blocks);assert_eq!(flow(&saved).endnotes[0].blocks,after.endnotes[0].blocks);
}

fn h9_record_setting_only() {
    let root=crate::shell::scenario::repo_root();let mut source=root.join(REPORT);
    for wanted in [true,false] {
        let data=std::fs::read(&source).unwrap();let mut s=Scenario::open(source.to_str().unwrap());let before=s.document();assert_ne!(before.track_changes,wanted);s.menu("docx.track.record");let after=s.document();assert_eq!(after.track_changes,wanted);let mut untouched=after.clone();untouched.track_changes=before.track_changes;untouched.interaction_mode=before.interaction_mode;assert_eq!(untouched,before,"record setting must not mutate any story or style");
        s.key("cmd-z");assert_eq!(s.document(),before);let undone=s.save_as(&format!("h9-record-only-undone-{wanted}.docx"));assert_eq!(std::fs::read(undone).unwrap(),data);s.key("cmd-shift-z");assert_eq!(s.document(),after);let fixed=root.join(format!("target/scenario-input/docx-record-only-{wanted}.docx"));std::fs::create_dir_all(fixed.parent().unwrap()).unwrap();let file=s.save_as(fixed.to_str().unwrap());let bytes=std::fs::read(&file).unwrap();for part in ["word/document.xml","word/styles.xml","word/numbering.xml","word/header1.xml","word/footer1.xml","word/footnotes.xml","word/endnotes.xml","word/comments.xml"] {assert_eq!(ibis_pptx::test_files::part_text(&bytes,part),ibis_pptx::test_files::part_text(&data,part),"setting-only touched {part}");}let saved=s.reopen();assert_eq!(flow(&saved).track_changes,wanted);let mut reread=flow(&saved).clone();let mut expected=after.clone();reread.file_name=None;expected.file_name=None;reread.file_size=expected.file_size;assert_eq!(reread,expected);source=file;
    }
}

fn e1_note_links() {
    use ibis_doc_model::flow_command;
    let root=crate::shell::scenario::repo_root();let mut s=Scenario::open(REPORT);let (_,id,_)=text_paragraph(&mut s,12);for (menu,at,text) in [("docx.footnote",3,"NoteLinkA"),("docx.endnote",8,"NoteLinkB")]{s.click_text(FlowPos::new(id,at));s.menu(menu);s.type_text(text);}
    let input=root.join("target/scenario-input/docx-note-links-ui-base.docx");std::fs::create_dir_all(input.parent().unwrap()).unwrap();s.save_as(input.to_str().unwrap());drop(s);let data=std::fs::read(&input).unwrap();let mut s=Scenario::open("target/scenario-input/docx-note-links-ui-base.docx");let initial=s.document();let mut ids=Vec::new();for notes in [&initial.footnotes,&initial.endnotes]{let p=match &notes[0].blocks[0]{Block::Paragraph(p)=>p,_=>panic!("note paragraph")};ids.push(p.id);}
    for (&id,url) in ids.iter().zip(["https://example.com/ui-foot","https://example.com/ui-end"]){let before=s.document();s.click_text(FlowPos::new(id,2));for _ in 0..9{s.key("shift-right");}assert_eq!(s.selection(),Some((FlowPos::new(id,2),FlowPos::new(id,11))));s.key("cmd-k");s.type_text(url);s.key("enter");let after=s.document();assert!(flow_command::paragraph(&after,id).unwrap().runs.iter().any(|r|r.link==Some(ibis_doc_model::Link::Url(url.into()))));assert_eq!(after.body,before.body);let mut after_styles=(*after.styles).clone();after_styles.styles.remove("Hyperlink");let mut before_styles=(*before.styles).clone();before_styles.styles.remove("Hyperlink");assert_eq!(after_styles,before_styles);s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);}
    let after=s.document();let fixed=root.join("target/scenario-input/docx-note-links-ui-linked.docx");let file=s.save_as(fixed.to_str().unwrap());let bytes=std::fs::read(&file).unwrap();for part in ["word/document.xml","word/settings.xml","word/numbering.xml"]{assert_eq!(ibis_pptx::test_files::part_text(&data,part),ibis_pptx::test_files::part_text(&bytes,part));}assert!(ibis_pptx::test_files::part_text(&bytes,"word/styles.xml").unwrap().contains("Hyperlink"));let saved=s.reopen();assert_eq!(flow(&saved).footnotes[0].blocks,after.footnotes[0].blocks);assert_eq!(flow(&saved).endnotes[0].blocks,after.endnotes[0].blocks);drop(s);
    let _probe=crate::shell::scenario::button_probe::Probe::new();let mut s=Scenario::open("target/scenario-input/docx-note-links-ui-linked.docx");let before=s.document();let id=match &before.footnotes[0].blocks[0]{Block::Paragraph(p)=>p.id,_=>panic!("note")};
    // An ordinary click on a link follows it (hyperlinks.rs), so the caret is put in the linked note text directly.
    s.update(|e,_,cx|e.set_caret(FlowPos::new(id,2),false,cx));for _ in 0..9{s.key("shift-right");}assert_eq!(s.selection(),Some((FlowPos::new(id,2),FlowPos::new(id,11))));s.key("cmd-k");s.key("cmd-a");s.type_text("https://example.com/ui-foot-changed");s.key("enter");let changed=s.document();assert_eq!(changed.endnotes,before.endnotes);s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),before);let undone=s.save_as("e1-note-link-undone.docx");assert_eq!(std::fs::read(undone).unwrap(),bytes);s.key("cmd-shift-z");assert_eq!(s.document(),changed);let file=s.save_as("e1-note-link-changed.docx");let out=std::fs::read(file).unwrap();for part in ["word/document.xml","word/endnotes.xml","word/_rels/endnotes.xml.rels","word/styles.xml"]{assert_eq!(ibis_pptx::test_files::part_text(&out,part),ibis_pptx::test_files::part_text(&bytes,part));}let saved=s.reopen();assert_eq!(flow(&saved).footnotes[0].blocks,changed.footnotes[0].blocks);
    s.update(|e,_,cx|e.set_caret(FlowPos::new(id,2),false,cx));for _ in 0..9{s.key("shift-right");}s.key("cmd-k");crate::shell::scenario::button_probe::click(&mut s,"link-remove");let removed=s.document();assert!(flow_command::paragraph(&removed,id).unwrap().runs.iter().all(|r|r.link.is_none()));s.update(|e,w,cx|e.focus_handle.focus(w,cx));s.key("cmd-z");assert_eq!(s.document(),changed);s.key("cmd-shift-z");assert_eq!(s.document(),removed);s.save_as("e1-note-link-removed.docx");let saved=s.reopen();assert_eq!(flow(&saved).footnotes[0].blocks,removed.footnotes[0].blocks);assert_eq!(flow(&saved).endnotes[0].blocks,removed.endnotes[0].blocks);
}

fn h9_note_original_history() {
    use ibis_doc_model::flow_command;
    let root=crate::shell::scenario::repo_root();let data=ibis_pptx::test_files::docx_with_note_deletion_history(&std::fs::read(root.join(REPORT)).unwrap());let input=root.join("target/scenario-input/docx-note-original-history.docx");std::fs::create_dir_all(input.parent().unwrap()).unwrap();std::fs::write(input,&data).unwrap();
    for tracked in [false,true] {
        let mut s=Scenario::open("target/scenario-input/docx-note-original-history.docx");if super::flow_layout::showing_markup(){s.menu("docx.track.show");}if s.document().track_changes!=tracked{s.menu("docx.track.record");}let before=s.document();let p=match &before.footnotes[0].blocks[0]{Block::Paragraph(p)=>p,_=>panic!("note")};let id=p.id;assert_eq!(final_text(p)," abcd");let old=p.runs.iter().filter(|r|matches!(r.revision.as_ref().map(|v|&v.kind),Some(ibis_doc_model::RevisionKind::Delete))).cloned().collect::<Vec<_>>();assert_eq!(old.iter().map(|r|match &r.kind{FlowRunKind::Text(t)=>t.as_str(),_=>""}).collect::<String>(),"X Y");
        s.click_text(FlowPos::new(id,3));s.key("shift-right");s.key("shift-right");assert_eq!(s.selection(),Some((FlowPos::new(id,3),FlowPos::new(id,8))));s.type_text("Q");let after=s.document();let p=flow_command::paragraph(&after,id).unwrap();assert_eq!(final_text(p)," aQd");for r in &old{assert!(p.runs.contains(r));}assert_eq!(after.body,before.body);assert_eq!(after.header,before.header);assert_eq!(after.styles,before.styles);assert_eq!(after.comments,before.comments);s.key("cmd-z");assert_eq!(s.document(),before);s.key("cmd-shift-z");assert_eq!(s.document(),after);let file=s.save_as(&format!("h9-note-history-typed-{tracked}.docx"));let bytes=std::fs::read(file).unwrap();let xml=ibis_pptx::test_files::part_text(&bytes,"word/footnotes.xml").unwrap();assert!(xml.contains(ibis_pptx::test_files::ORIGINAL_DELETION_XML));for name in ["word/document.xml","word/comments.xml","word/styles.xml","word/numbering.xml"]{assert_eq!(ibis_pptx::test_files::part_text(&bytes,name),ibis_pptx::test_files::part_text(&data,name));}let saved=s.reopen();let saved_note=flow_command::paragraph(flow(&saved),id).unwrap();assert_eq!(saved_note.runs,p.runs);
        if tracked{s.menu("docx.track.reject-all");let rejected=s.document();let p=flow_command::paragraph(&rejected,id).unwrap();assert_eq!(final_text(p)," abX Ycd");assert!(p.runs.iter().all(|r|r.revision.is_none()));s.key("cmd-z");assert_eq!(s.document(),after);s.key("cmd-shift-z");assert_eq!(s.document(),rejected);s.save_as("h9-note-history-rejected.docx");let saved=s.reopen();assert_eq!(flow_command::paragraph(flow(&saved),id).unwrap().runs,p.runs);}s.menu("docx.track.show");
    }
}

