/// The text of a part's `w:t` elements joined, without the tags: a word
/// typed while recording can be split into two insertions (`w:ins/@w:date`
/// is to the second), so "RootCha" and "nge5" land in different runs.
fn xml_text(xml: &str) -> String {
    let mut out = String::new();
    let mut rest = xml;
    while let Some(at) = rest.find("<w:t") {
        rest = &rest[at + 4..];
        // `<w:t>` or `<w:t …>`, not `<w:tab/>`, `<w:tbl>` and the like.
        if !(rest.starts_with('>') || rest.starts_with(' ')) {
            continue;
        }
        let Some(open) = rest.find('>') else { break };
        if rest[..open].ends_with('/') {
            rest = &rest[open + 1..];
            continue;
        }
        rest = &rest[open + 1..];
        let Some(close) = rest.find("</w:t>") else { break };
        out.push_str(&rest[..close]);
        rest = &rest[close + 6..];
    }
    out
}

