fn h9_original_history_linked_typing() {
    let root = crate::shell::scenario::repo_root();
    let data = ibis_pptx::test_files::docx_with_linked_history_tail(&std::fs::read(root.join(REPORT)).unwrap());
    let input = root.join("target/scenario-input/docx-history-linked-typing.docx");
    std::fs::create_dir_all(input.parent().unwrap()).unwrap();
    std::fs::write(&input, &data).unwrap();
    for tracked in [false, true] {
        let mut s = Scenario::open("target/scenario-input/docx-history-linked-typing.docx");
        if super::flow_layout::showing_markup() { s.menu("docx.track.show"); }
        if s.document().track_changes != tracked { s.menu("docx.track.record"); }
        let before = s.document();
        let id = body(&before).into_iter().find(|p| p.text() == "abX Ycd").unwrap().id;
        assert!(para(&before, id).runs.iter().any(|r| r.link.is_some()));
        s.click_text(FlowPos::new(id, 1));
        s.key("shift-right"); s.key("shift-right");
        assert_eq!(s.selection(), Some((FlowPos::new(id, 1), FlowPos::new(id, 6))));
        s.type_text("Q");
        let after = s.document();
        assert_eq!(final_text(para(&after, id)), "aQd");
        let mut outside = after.clone();
        let original = para(&before, id).clone();
        for block in &mut outside.body { if let Block::Paragraph(p) = block && p.id == id { *p = original.clone(); } }
        assert_eq!(outside, before);
        let p = para(&after, id);
        if !tracked { assert!(p.runs.iter().any(|r| matches!(&r.kind, FlowRunKind::Text(t) if t.contains('Q')) && r.link.is_none())); }
        // Recorded insertion is placed after the selection and currently
        // inherits that insertion position's link. Native semantics remain open.
        assert!(p.runs.iter().any(|r| matches!(&r.kind, FlowRunKind::Text(t) if t == "d") && r.link == Some(ibis_doc_model::Link::Url("https://example.com/history-tail".into()))));
        s.key("cmd-z"); assert_eq!(s.document(), before);
        if !tracked { let undone = s.save_as("h9-linked-history-undone.docx"); assert_eq!(std::fs::read(undone).unwrap(), data); }
        s.key("cmd-shift-z"); assert_eq!(s.document(), after);
        let file = s.save_as(&format!("h9-linked-history-typed-{tracked}.docx"));
        let bytes = std::fs::read(file).unwrap();
        let xml = ibis_pptx::test_files::part_text(&bytes, "word/document.xml").unwrap();
        assert!(xml.contains(ibis_pptx::test_files::ORIGINAL_DELETION_XML), "unchanged original history must survive linked-tail replacement");
        for part in ["word/_rels/document.xml.rels", "word/styles.xml", "word/numbering.xml"] { assert_eq!(ibis_pptx::test_files::part_text(&bytes, part), ibis_pptx::test_files::part_text(&data, part)); }
        let saved = s.reopen(); assert!(body(flow(&saved)).iter().any(|p| p.runs == para(&after, id).runs));
        s.menu("docx.track.show");
    }
}

fn h9_original_history_split() {
    let root = crate::shell::scenario::repo_root();
    let data = ibis_pptx::test_files::docx_with_original_deletion_history(&std::fs::read(root.join(REPORT)).unwrap());
    let input = root.join("target/scenario-input/docx-history-split.docx");
    std::fs::create_dir_all(input.parent().unwrap()).unwrap(); std::fs::write(&input, &data).unwrap();
    for offset in [1, 6] {
        let mut s = Scenario::open("target/scenario-input/docx-history-split.docx");
        if super::flow_layout::showing_markup() { s.menu("docx.track.show"); }
        assert!(!s.document().track_changes);
        let before = s.document(); let id = body(&before).into_iter().find(|p| p.text() == "abX Ycd").unwrap().id;
        let new_id = before.new_id(); s.click_text(FlowPos::new(id, offset));
        assert_eq!(s.selection(), Some((FlowPos::new(id, offset), FlowPos::new(id, offset))));
        s.key("enter"); let after = s.document();
        assert_eq!(para(&after, id).text(), if offset == 1 { "a" } else { "abX Yc" });
        assert_eq!(para(&after, new_id).text(), if offset == 1 { "bX Ycd" } else { "d" });
        assert_eq!(after.header, before.header); assert_eq!(after.footer, before.footer); assert_eq!(after.styles, before.styles);
        s.key("cmd-z"); assert_eq!(s.document(), before); let undone = s.save_as(&format!("h9-history-split-undone-{offset}.docx")); assert_eq!(std::fs::read(undone).unwrap(), data);
        s.key("cmd-shift-z"); assert_eq!(s.document(), after);
        let file = s.save_as(&format!("h9-history-split-{offset}.docx")); let bytes = std::fs::read(file).unwrap();
        let xml = ibis_pptx::test_files::part_text(&bytes, "word/document.xml").unwrap();
        assert_eq!(xml.matches(ibis_pptx::test_files::ORIGINAL_DELETION_XML).count(), 1, "whole old scope survives a split on either side");
        for part in ["word/_rels/document.xml.rels", "word/styles.xml", "word/settings.xml", "word/numbering.xml"] { assert_eq!(ibis_pptx::test_files::part_text(&bytes, part), ibis_pptx::test_files::part_text(&data, part)); }
        let saved = s.reopen(); let ps = body(flow(&saved)); for expected in [para(&after,id),para(&after,new_id)] { assert!(ps.iter().any(|p| p.text()==expected.text() && p.runs==expected.runs)); }
        s.click_text(FlowPos::new(new_id,0)); s.key("backspace"); let joined = s.document(); assert_eq!(para(&joined,id).runs, para(&before,id).runs);
        s.key("cmd-z"); assert_eq!(s.document(),after); s.key("cmd-shift-z"); assert_eq!(s.document(),joined);
        let file=s.save_as(&format!("h9-history-joined-{offset}.docx")); let bytes=std::fs::read(file).unwrap(); let xml=ibis_pptx::test_files::part_text(&bytes,"word/document.xml").unwrap(); assert_eq!(xml.matches(ibis_pptx::test_files::ORIGINAL_DELETION_XML).count(),1);
        let saved=s.reopen(); assert!(body(flow(&saved)).iter().any(|p|p.runs==para(&before,id).runs));
        s.menu("docx.track.show");
    }
}

fn h9_cross_paragraph_history_guard() {
    let root=crate::shell::scenario::repo_root();
    let data=ibis_pptx::test_files::docx_with_search_history_edges(&std::fs::read(root.join(REPORT)).unwrap());
    let input=root.join("target/scenario-input/docx-cross-paragraph-history.docx");std::fs::create_dir_all(input.parent().unwrap()).unwrap();std::fs::write(&input,&data).unwrap();
    for action in ["typing","backspace","delete","cut","paste","plain-paste"] {
        let mut s=Scenario::open("target/scenario-input/docx-cross-paragraph-history.docx");if super::flow_layout::showing_markup(){s.menu("docx.track.show");}
        let doc=s.document();assert!(!doc.track_changes);let ps=body(&doc);let first=ps.iter().find(|p|p.text()=="X Ypq").unwrap().id;let last=ps.iter().find(|p|p.text()=="rsX Y").unwrap().id;
        // A real formatted text clipboard, retained even by rejected Cut.
        let (_,copy_id,_) = text_paragraph(&mut s,8); s.click_text(FlowPos::new(copy_id,1));s.key("shift-right");s.key("shift-right");s.key("cmd-c");
        let clipboard = s.update(|_,_,cx|cx.read_from_clipboard().unwrap());
        assert!(clipboard.metadata().is_some());
        // Seed an undo/redo entry before the rejected operation.
        s.click_text(FlowPos::new(first,4));s.type_text("K");let redone=s.document();s.key("cmd-z");assert_eq!(s.document(),doc);
        s.click_text(FlowPos::new(first,4));for _ in 0..4{s.key("shift-right");}
        assert_eq!(s.selection(),Some((FlowPos::new(first,4),FlowPos::new(last,5))));
        match action { "typing"=>s.type_text("Q"), "cut"=>s.key("cmd-x"), "paste"=>s.key("cmd-v"), "plain-paste"=>s.key("cmd-shift-v"), _=>s.key(action) }
        assert_eq!(s.document(),doc,"cross-paragraph final-view history must not be silently removed or moved");
        assert!(s.with(|e,_|e.status.as_ref().is_some_and(|t|t.contains("変更履歴"))),"explicit safety guidance");
        let current = s.update(|_,_,cx|cx.read_from_clipboard().unwrap());assert_eq!(current.text(),clipboard.text());assert_eq!(current.metadata(),clipboard.metadata());
        let file=s.save_as(&format!("h9-cross-history-guard-{action}.docx"));assert_eq!(std::fs::read(file).unwrap(),data);
        s.key("cmd-shift-z");assert_eq!(s.document(),redone,"refusal keeps redo entry");
        s.menu("docx.track.show");
    }
}

fn h11_paste_original_history() {
    paste_original_history_cases(false);
}

fn h11_tracked_paste_original_history() {
    paste_original_history_cases(true);
}

fn paste_original_history_cases(tracked: bool) {
    let root = crate::shell::scenario::repo_root();
    let data = ibis_pptx::test_files::docx_with_linked_history_tail(
        &std::fs::read(root.join(REPORT)).unwrap(),
    );
    let relative = if tracked {
        "target/scenario-input/docx-tracked-paste-original-history.docx"
    } else {
        "target/scenario-input/docx-paste-original-history.docx"
    };
    let prefix = if tracked {
        "h11-tracked-history"
    } else {
        "h11-history"
    };
    let input = root.join(relative);
    std::fs::create_dir_all(input.parent().unwrap()).unwrap();
    std::fs::write(&input, &data).unwrap();
    for plain in [false, true] {
        let mut source = Scenario::open(REPORT);
        let (_, id, text) = text_paragraph(&mut source, 8);
        source.click_text(FlowPos::new(id, 0));
        for _ in 0..3 {
            source.key("shift-right");
        }
        source.key("cmd-b");
        source.key("cmd-k");
        source.type_text("https://example.com/paste-source");
        source.key("enter");
        source.update(|e, w, cx| e.focus_handle.focus(w, cx));
        source.key("cmd-c");
        let clipboard = source.update(|_, _, cx| cx.read_from_clipboard().unwrap());
        let expected: String = text.chars().take(3).collect();
        drop(source);
        let mut s = Scenario::open(relative);
        s.update(|_, _, cx| cx.write_to_clipboard(clipboard));
        if super::flow_layout::showing_markup() {
            s.menu("docx.track.show");
        }
        if s.document().track_changes != tracked {
            s.menu("docx.track.record");
        }
        let before = s.document();
        assert_eq!(before.track_changes, tracked);
        let id = body(&before)
            .into_iter()
            .find(|p| p.text() == "abX Ycd")
            .unwrap()
            .id;
        let old: Vec<_> = para(&before, id)
            .runs
            .iter()
            .filter(|r| r.revision.is_some())
            .cloned()
            .collect();
        s.click_text(FlowPos::new(id, 1));
        s.key("shift-right");
        s.key("shift-right");
        assert_eq!(
            s.selection(),
            Some((FlowPos::new(id, 1), FlowPos::new(id, 6)))
        );
        s.key(if plain { "cmd-shift-v" } else { "cmd-v" });
        let after = s.document();
        let p = para(&after, id);
        assert_eq!(final_text(p), format!("a{expected}d"));
        for r in &old {
            assert!(
                p.runs.contains(r),
                "paste must keep hidden original history"
            );
        }
        let pasted = p
            .runs
            .iter()
            .find(|r| matches!(&r.kind,FlowRunKind::Text(t) if t.contains(&expected)))
            .unwrap();
        assert_eq!(pasted.style.bold, !plain);
        if tracked {
            assert!(matches!(
                pasted.revision.as_ref().map(|r| &r.kind),
                Some(ibis_doc_model::RevisionKind::Insert)
            ));
        }
        if !plain {
            assert_eq!(
                pasted.link,
                Some(ibis_doc_model::Link::Url(
                    "https://example.com/paste-source".into()
                ))
            );
        }
        assert!(
            p.runs
                .iter()
                .any(|r| matches!(&r.kind,FlowRunKind::Text(t) if t=="d")
                    && r.link
                        == Some(ibis_doc_model::Link::Url(
                            "https://example.com/history-tail".into()
                        )))
        );
        let mut outside = after.clone();
        for block in &mut outside.body {
            if let Block::Paragraph(q) = block
                && q.id == id
            {
                *q = para(&before, id).clone();
            }
        }
        assert_eq!(outside, before);
        assert_eq!(after.header, before.header);
        assert_eq!(after.footer, before.footer);
        assert_eq!(after.styles, before.styles);
        s.key("cmd-z");
        assert_eq!(s.document(), before);
        let undone = s.save_as(&format!("{prefix}-undone-{plain}.docx"));
        if !tracked {
            assert_eq!(std::fs::read(undone).unwrap(), data);
        }
        s.key("cmd-shift-z");
        assert_eq!(s.document(), after);
        let file = s.save_as(&format!("{prefix}-pasted-{plain}.docx"));
        let bytes = std::fs::read(file).unwrap();
        let xml = ibis_pptx::test_files::part_text(&bytes, "word/document.xml").unwrap();
        assert!(xml.contains(ibis_pptx::test_files::ORIGINAL_DELETION_XML));
        for part in ["word/styles.xml", "word/numbering.xml"] {
            assert_eq!(
                ibis_pptx::test_files::part_text(&bytes, part),
                ibis_pptx::test_files::part_text(&data, part)
            );
        }
        let settings = ibis_pptx::test_files::part_text(&bytes, "word/settings.xml").unwrap();
        assert_eq!(
            settings.replace("<w:trackRevisions/>", ""),
            ibis_pptx::test_files::part_text(&data, "word/settings.xml").unwrap()
        );
        assert_eq!(settings.contains("<w:trackRevisions/>"), tracked);
        let saved = s.reopen();
        assert_eq!(flow(&saved).track_changes, tracked);
        let reread = body(flow(&saved))
            .into_iter()
            .find(|q| final_text(q) == final_text(p))
            .unwrap();
        let mut expected_runs = p.runs.clone();
        for r in &mut expected_runs {
            if r.format.underline_style == Some(ibis_doc_model::UnderlineStyle::Single) {
                r.format.underline_style = None;
            }
            if r.format.underline_color == Some(None) {
                r.format.underline_color = None;
            }
            if r.format.tate_chu_yoko == Some(false) {
                r.format.tate_chu_yoko = None;
            }
            // "no fit-text" is saved as nothing.
            if r.format.fit_text == Some(None) {
                r.format.fit_text = None;
            }
        }
        assert_eq!(reread.runs, expected_runs);
        if tracked {
            s.menu("docx.track.record");
        }
        s.menu("docx.track.show");
    }
}

fn h9_original_insertion_format() {
    let root = crate::shell::scenario::repo_root();
    let data = ibis_pptx::test_files::docx_with_original_insertion_history(
        &std::fs::read(root.join(REPORT)).unwrap(),
    );
    let input = root.join("target/scenario-input/docx-original-insertion-format.docx");
    std::fs::create_dir_all(input.parent().unwrap()).unwrap();
    std::fs::write(&input, &data).unwrap();
    for count in [1, 3] {
        let mut s = Scenario::open("target/scenario-input/docx-original-insertion-format.docx");
        if super::flow_layout::showing_markup() {
            s.menu("docx.track.show");
        }
        let before = s.document();
        assert!(!before.track_changes);
        let id = body(&before)
            .into_iter()
            .find(|p| p.text() == "abX Ycd")
            .unwrap()
            .id;
        s.click_text(FlowPos::new(id, 2));
        for _ in 0..count {
            s.key("shift-right");
        }
        assert_eq!(
            s.selection(),
            Some((FlowPos::new(id, 2), FlowPos::new(id, 2 + count)))
        );
        s.key("cmd-b");
        let after = s.document();
        let p = para(&after, id);
        assert!(p.runs.iter().any(
            |r| matches!(&r.kind,FlowRunKind::Text(t) if t.contains('X'))
                && r.style.bold
                && matches!(
                    r.revision.as_ref().map(|v| &v.kind),
                    Some(ibis_doc_model::RevisionKind::Insert)
                )
        ));
        assert!(p.runs.iter().any(
            |r| matches!(&r.kind,FlowRunKind::Text(t) if t.contains('Y'))
                && r.style.bold == (count == 3)
        ));
        assert_eq!(p.text(), "abX Ycd");
        assert_eq!(after.header, before.header);
        assert_eq!(after.footer, before.footer);
        assert_eq!(after.styles, before.styles);
        s.key("cmd-z");
        assert_eq!(s.document(), before);
        let undone = s.save_as(&format!("h9-insertion-format-undone-{count}.docx"));
        assert_eq!(std::fs::read(undone).unwrap(), data);
        s.key("cmd-shift-z");
        assert_eq!(s.document(), after);
        let file = s.save_as(&format!("h9-insertion-format-bold-{count}.docx"));
        let bytes = std::fs::read(file).unwrap();
        let xml = ibis_pptx::test_files::part_text(&bytes, "word/document.xml").unwrap();
        assert!(xml.contains("w:id=\"941\""));
        assert!(xml.contains("ibis:marker=\"old\""));
        assert!(xml.contains("<!--old history container-->"));
        assert!(xml.contains("w:rsidR=\"12345678\""));
        for part in ["word/styles.xml", "word/settings.xml", "word/numbering.xml"] {
            assert_eq!(
                ibis_pptx::test_files::part_text(&bytes, part),
                ibis_pptx::test_files::part_text(&data, part)
            );
        }
        let saved = s.reopen();
        assert!(body(flow(&saved)).iter().any(|q| q.runs == p.runs));
        s.menu("docx.track.show");
    }
}

fn h9_insertion_unknown_run_save_guard() {
    let root = crate::shell::scenario::repo_root();
    let data = ibis_pptx::test_files::docx_with_insertion_run_comment(
        &std::fs::read(root.join(REPORT)).unwrap(),
    );
    let input = root.join("target/scenario-input/docx-insertion-unknown-run.docx");
    std::fs::create_dir_all(input.parent().unwrap()).unwrap();
    std::fs::write(&input, &data).unwrap();
    let mut s = Scenario::open("target/scenario-input/docx-insertion-unknown-run.docx");
    if super::flow_layout::showing_markup() {
        s.menu("docx.track.show");
    }
    let before = s.document();
    let path = s.with(|e, _| e.path.clone().unwrap());
    assert_eq!(std::fs::read(&path).unwrap(), data);
    let id = body(&before)
        .into_iter()
        .find(|p| p.text() == "abX Ycd")
        .unwrap()
        .id;
    s.click_text(FlowPos::new(id, 2));
    s.key("shift-right");
    s.key("cmd-b");
    let after = s.document();
    assert_ne!(after, before);
    s.key("cmd-s");
    assert_eq!(
        std::fs::read(&path).unwrap(),
        data,
        "unsupported save must not replace original ZIP"
    );
    assert_eq!(s.document(), after);
    assert!(
        s.with(|e, _| e
            .status
            .as_ref()
            .is_some_and(|t| t.contains("元の変更履歴"))),
        "explicit preservation refusal"
    );
    s.key("cmd-z");
    assert_eq!(s.document(), before);
    s.key("cmd-s");
    assert_eq!(std::fs::read(&path).unwrap(), data);
    s.key("cmd-shift-z");
    assert_eq!(s.document(), after);
    s.key("cmd-s");
    assert_eq!(std::fs::read(&path).unwrap(), data);
    assert_eq!(s.document(), after);
    s.menu("docx.track.show");
}

fn h9_original_insertion_page() {
    let root = crate::shell::scenario::repo_root();
    let data = ibis_pptx::test_files::docx_with_insertion_page_field(
        &std::fs::read(root.join(REPORT)).unwrap(),
    );
    let input = root.join("target/scenario-input/docx-insertion-page-field.docx");
    std::fs::create_dir_all(input.parent().unwrap()).unwrap();
    std::fs::write(&input, &data).unwrap();
    let mut s = Scenario::open("target/scenario-input/docx-insertion-page-field.docx");
    if super::flow_layout::showing_markup() {
        s.menu("docx.track.show");
    }
    let before = s.document();
    let p = body(&before)
        .into_iter()
        .find(|p| {
            p.text().starts_with("abX Y")
                && p.runs
                    .iter()
                    .any(|r| matches!(r.kind, FlowRunKind::PageNumber))
        })
        .unwrap();
    let id = p.id;
    let field = p
        .runs
        .iter()
        .find(|r| matches!(r.kind, FlowRunKind::PageNumber))
        .unwrap();
    assert!(
        matches!(
            field.revision.as_ref().map(|v| &v.kind),
            Some(ibis_doc_model::RevisionKind::Insert)
        ),
        "PAGE must inherit its original insertion wrapper"
    );
    s.click_text(FlowPos::new(id, 1));
    s.menu("docx.track.reject-all");
    let after = s.document();
    assert_eq!(para(&after, id).text(), "abcd");
    assert!(
        para(&after, id)
            .runs
            .iter()
            .all(|r| r.revision.is_none() && !matches!(r.kind, FlowRunKind::PageNumber))
    );
    assert_eq!(after.header, before.header);
    assert_eq!(after.footer, before.footer);
    assert_eq!(after.styles, before.styles);
    s.key("cmd-z");
    assert_eq!(s.document(), before);
    let undone = s.save_as("h9-insertion-page-undone.docx");
    assert_eq!(std::fs::read(undone).unwrap(), data);
    s.key("cmd-shift-z");
    assert_eq!(s.document(), after);
    let file = s.save_as("h9-insertion-page-rejected.docx");
    let bytes = std::fs::read(file).unwrap();
    let xml = ibis_pptx::test_files::part_text(&bytes, "word/document.xml").unwrap();
    assert!(!xml.contains("w:id=\"941\""));
    assert!(!xml.contains(ibis_pptx::test_files::INSERTION_COMPLEX_PAGE_XML));
    for part in ["word/styles.xml", "word/settings.xml", "word/numbering.xml"] {
        assert_eq!(
            ibis_pptx::test_files::part_text(&bytes, part),
            ibis_pptx::test_files::part_text(&data, part)
        );
    }
    let saved = s.reopen();
    assert!(
        body(flow(&saved))
            .iter()
            .any(|q| q.runs == para(&after, id).runs)
    );
    s.menu("docx.track.show");
}

fn h9_insertion_field_edit() {
    let root = crate::shell::scenario::repo_root();
    for place in 0..3 {
        let data = ibis_pptx::test_files::docx_with_insertion_page_field_at(
            &std::fs::read(root.join(REPORT)).unwrap(),
            place,
        );
        let name = format!("target/scenario-input/docx-insertion-field-edit-{place}.docx");
        let input = root.join(&name);
        std::fs::create_dir_all(input.parent().unwrap()).unwrap();
        std::fs::write(&input, &data).unwrap();
        let xml = ibis_pptx::test_files::part_text(&data, "word/document.xml").unwrap();
        let start = xml.find("<w:ins w:id=\"941\"").unwrap();
        let end = start + xml[start..].find("</w:ins>").unwrap() + "</w:ins>".len();
        let raw = xml[start..end].to_owned();
        for field in [false, true] {
            let mut s = Scenario::open(&name);
            if super::flow_layout::showing_markup() {
                s.menu("docx.track.show");
            }
            let before = s.document();
            let id = body(&before)
                .into_iter()
                .find(|p| {
                    p.text().starts_with("ab")
                        && p.runs
                            .iter()
                            .any(|r| matches!(r.kind, FlowRunKind::PageNumber))
                })
                .unwrap()
                .id;
            let p = para(&before, id);
            let field_at = p
                .runs
                .iter()
                .take_while(|r| !matches!(r.kind, FlowRunKind::PageNumber))
                .map(|r| r.len())
                .sum();
            let at = if field { field_at } else { 0 };
            s.click_text(FlowPos::new(id, at));
            s.key("shift-right");
            assert_eq!(
                s.selection(),
                Some((FlowPos::new(id, at), FlowPos::new(id, at + 1)))
            );
            s.key("cmd-b");
            let after = s.document();
            assert_ne!(after, before);
            assert_eq!(after.header, before.header);
            assert_eq!(after.footer, before.footer);
            assert_eq!(after.styles, before.styles);
            if field {
                let path = s.with(|e, _| e.path.clone().unwrap());
                s.key("cmd-s");
                assert!(
                    std::fs::read(&path).unwrap() == data,
                    "field formatting must not drop original scope metadata"
                );
                assert_eq!(s.document(), after);
                assert!(s.with(|e, _| {
                    e.status
                        .as_ref()
                        .is_some_and(|t| t.contains("元の変更履歴"))
                }));
                s.key("cmd-z");
                assert_eq!(s.document(), before);
                s.key("cmd-s");
                assert_eq!(std::fs::read(&path).unwrap(), data);
                s.key("cmd-shift-z");
                assert_eq!(s.document(), after);
                s.key("cmd-s");
                assert_eq!(std::fs::read(&path).unwrap(), data);
            } else {
                s.key("cmd-z");
                assert_eq!(s.document(), before);
                let undone = s.save_as(&format!("h9-field-outside-undone-{place}.docx"));
                assert_eq!(std::fs::read(undone).unwrap(), data);
                s.key("cmd-shift-z");
                assert_eq!(s.document(), after);
                let file = s.save_as(&format!("h9-field-outside-bold-{place}.docx"));
                let bytes = std::fs::read(file).unwrap();
                let xml = ibis_pptx::test_files::part_text(&bytes, "word/document.xml").unwrap();
                assert!(
                    xml.contains(&raw),
                    "unchanged entire original field scope must stay exact"
                );
                for part in ["word/styles.xml", "word/settings.xml", "word/numbering.xml"] {
                    assert_eq!(
                        ibis_pptx::test_files::part_text(&bytes, part),
                        ibis_pptx::test_files::part_text(&data, part)
                    );
                }
                let saved = s.reopen();
                assert!(
                    body(flow(&saved))
                        .iter()
                        .any(|p| p.runs == para(&after, id).runs)
                );
            }
            s.menu("docx.track.show");
        }
    }
}

fn h9_linked_source_insertion_format() {
    let root = crate::shell::scenario::repo_root();
    let data = ibis_pptx::test_files::docx_with_linked_insertion_history(
        &std::fs::read(root.join(REPORT)).unwrap(),
    );
    let input = root.join("target/scenario-input/docx-linked-insertion-history.docx");
    std::fs::create_dir_all(input.parent().unwrap()).unwrap();
    std::fs::write(&input, &data).unwrap();
    let raw = ibis_pptx::test_files::ORIGINAL_DELETION_XML
        .replace("w:delText", "w:t")
        .replace("w:del", "w:ins")
        .replace("841", "941");
    for inside in [false, true] {
        let mut s = Scenario::open("target/scenario-input/docx-linked-insertion-history.docx");
        if super::flow_layout::showing_markup() {
            s.menu("docx.track.show");
        }
        let before = s.document();
        let id = body(&before)
            .into_iter()
            .find(|p| p.text() == "abX Ycd")
            .unwrap()
            .id;
        s.click_text(FlowPos::new(id, 0));
        if inside {
            for _ in 0..2 {
                s.key("right");
            }
        }
        s.key("shift-right");
        s.key("cmd-b");
        let after = s.document();
        assert_eq!(para(&after, id).text(), "abX Ycd");
        let selected = if inside { "X" } else { "a" };
        assert!(
            para(&after, id)
                .runs
                .iter()
                .any(|r| matches!(&r.kind,FlowRunKind::Text(t) if t==selected)
                    && r.style.bold)
        );
        assert!(
            para(&after, id)
                .runs
                .iter()
                .filter(|r| r.revision.is_some())
                .all(|r| r.link
                    == Some(ibis_doc_model::Link::Url(
                        "https://example.com/original-insertion".into()
                    )))
        );
        assert_eq!(after.header, before.header);
        assert_eq!(after.footer, before.footer);
        assert_eq!(after.styles, before.styles);
        s.key("cmd-z");
        assert_eq!(s.document(), before);
        let undone = s.save_as(&format!("h9-linked-insertion-undone-{inside}.docx"));
        assert_eq!(std::fs::read(undone).unwrap(), data);
        s.key("cmd-shift-z");
        assert_eq!(s.document(), after);
        let file = s.save_as(&format!("h9-linked-insertion-bold-{inside}.docx"));
        let bytes = std::fs::read(file).unwrap();
        let xml = ibis_pptx::test_files::part_text(&bytes, "word/document.xml").unwrap();
        if !inside {
            assert!(
                xml.contains(&raw),
                "unmodified linked source scope stays exact"
            );
        }
        assert!(xml.contains("w:id=\"941\""));
        assert!(xml.contains("ibis:marker=\"old\""));
        assert!(xml.contains("<!--old history container-->"));
        assert!(xml.contains("w:rsidR=\"12345678\""));
        assert!(xml.contains("w:history=\"0\" w:tgtFrame=\"frame\""));
        for part in [
            "word/_rels/document.xml.rels",
            "word/styles.xml",
            "word/settings.xml",
            "word/numbering.xml",
        ] {
            assert_eq!(
                ibis_pptx::test_files::part_text(&bytes, part),
                ibis_pptx::test_files::part_text(&data, part)
            );
        }
        let saved = s.reopen();
        assert!(
            body(flow(&saved))
                .iter()
                .any(|p| p.runs == para(&after, id).runs)
        );
        s.menu("docx.track.show");
    }
}

fn h9_linked_source_insertion_typing() {
    linked_source_insertion_typing_cases(None);
}

fn h9_link_relationship_namespace_typing() {
    for variant in 0..3 {
        linked_source_insertion_typing_cases(Some(variant));
    }
}

fn linked_source_insertion_typing_cases(namespace_variant: Option<usize>) {
    let root = crate::shell::scenario::repo_root();
    let report = std::fs::read(root.join(REPORT)).unwrap();
    let data = namespace_variant.map_or_else(
        || ibis_pptx::test_files::docx_with_linked_insertion_history(&report),
        |variant| ibis_pptx::test_files::docx_with_link_relationship_namespace(&report, variant),
    );
    let relative = namespace_variant.map_or_else(
        || "target/scenario-input/docx-linked-insertion-typing.docx".to_string(),
        |v| format!("target/scenario-input/docx-link-namespace-{v}.docx"),
    );
    let prefix = namespace_variant.map_or_else(
        || "h9-linked-insertion".to_string(),
        |v| format!("h9-link-namespace-{v}"),
    );
    let input = root.join(&relative);
    std::fs::create_dir_all(input.parent().unwrap()).unwrap();
    std::fs::write(&input, &data).unwrap();
    let raw = ibis_pptx::test_files::ORIGINAL_DELETION_XML
        .replace("w:delText", "w:t")
        .replace("w:del", "w:ins")
        .replace("841", "941");
    let source_xml = ibis_pptx::test_files::part_text(&data, "word/document.xml").unwrap();
    let begin = source_xml.find("<w:hyperlink ").unwrap();
    let end = source_xml[begin..].find("</w:hyperlink>").unwrap() + begin + "</w:hyperlink>".len();
    let original_link = &source_xml[begin..end];
    let positions: &[usize] = if namespace_variant.is_some() {
        &[1]
    } else {
        &[1, 6]
    };
    for &at in positions {
        for tracked in [false, true] {
            let mut s = Scenario::open(&relative);
            if super::flow_layout::showing_markup() {
                s.menu("docx.track.show");
            }
            if s.document().track_changes != tracked {
                s.menu("docx.track.record");
            }
            let before = s.document();
            let id = body(&before)
                .into_iter()
                .find(|p| p.text() == "abX Ycd")
                .unwrap()
                .id;
            let old = para(&before, id)
                .runs
                .iter()
                .filter(|r| r.revision.is_some())
                .cloned()
                .collect::<Vec<_>>();
            assert!(!old.is_empty());
            assert!(
                old.iter().all(|r| r.link
                    == Some(ibis_doc_model::Link::Url(
                        "https://example.com/original-insertion".into()
                    ))),
                "qualified relationship must select original URL"
            );
            s.click_text(FlowPos::new(id, at));
            s.type_text("Q");
            let after = s.document();
            assert_eq!(
                final_text(para(&after, id)),
                if at == 1 { "aQbX Ycd" } else { "abX YcQd" }
            );
            assert!(para(&after, id).runs.windows(old.len()).any(|r| r == old));
            let mut outside = after.clone();
            for block in &mut outside.body {
                if let Block::Paragraph(p) = block
                    && p.id == id
                {
                    *p = para(&before, id).clone();
                }
            }
            assert_eq!(outside, before);
            s.key("cmd-z");
            assert_eq!(s.document(), before);
            if !tracked {
                let undone = s.save_as(&format!("{prefix}-typing-undone-{at}.docx"));
                assert_eq!(std::fs::read(undone).unwrap(), data);
            }
            s.key("cmd-shift-z");
            assert_eq!(s.document(), after);
            let f = s.save_as(&format!("{prefix}-typed-{at}-{tracked}.docx"));
            let bytes = std::fs::read(f).unwrap();
            let xml = ibis_pptx::test_files::part_text(&bytes, "word/document.xml").unwrap();
            assert!(xml.contains(&raw));
            assert!(xml.contains(original_link), "original link XML intact");
            assert!(xml.contains("w:history=\"0\" w:tgtFrame=\"frame\""));
            for part in [
                "word/_rels/document.xml.rels",
                "word/styles.xml",
                "word/numbering.xml",
            ] {
                assert_eq!(
                    ibis_pptx::test_files::part_text(&bytes, part),
                    ibis_pptx::test_files::part_text(&data, part)
                );
            }
            let settings = ibis_pptx::test_files::part_text(&bytes, "word/settings.xml").unwrap();
            let source_settings =
                ibis_pptx::test_files::part_text(&data, "word/settings.xml").unwrap();
            assert_eq!(settings.replace("<w:trackRevisions/>", ""), source_settings);
            assert_eq!(settings.contains("<w:trackRevisions/>"), tracked);
            let saved = s.reopen();
            assert_eq!(flow(&saved).track_changes, tracked);
            assert!(
                body(flow(&saved))
                    .iter()
                    .any(|p| p.runs == para(&after, id).runs)
            );
            if tracked {
                s.menu("docx.track.record");
            }
            s.menu("docx.track.show");
        }
    }
}

fn h9_note_id_namespace_typing() {
    use ibis_doc_model::flow_command;
    let root=crate::shell::scenario::repo_root();let original=std::fs::read(root.join(REPORT)).unwrap();
    for variant in 0..3 {
        let data=ibis_pptx::test_files::docx_with_note_id_namespace(&original,variant);let relative=format!("target/scenario-input/docx-note-id-namespace-{variant}.docx");let input=root.join(&relative);std::fs::create_dir_all(input.parent().unwrap()).unwrap();std::fs::write(input,&data).unwrap();
        let mut s=Scenario::open(&relative);if super::flow_layout::showing_markup(){s.menu("docx.track.show");}let before=s.document();let note=&before.footnotes[0];let p=match &note.blocks[0]{Block::Paragraph(p)=>p,_=>panic!()};assert_eq!(final_text(p)," abcd");let id=p.id;
        let mut at=0;for run in &p.runs {if matches!(&run.kind,FlowRunKind::Text(t) if t.starts_with(" ab"))&&run.revision.is_none(){at+=1;break;}at+=run.len();}
        s.click_text(FlowPos::new(id,at));s.type_text("Q");let after=s.document();let edited=flow_command::paragraph(&after,id).unwrap();assert_eq!(final_text(edited)," Qabcd");
        let mut outside=after.clone();outside.footnotes=before.footnotes.clone();assert_eq!(outside,before);for old in &before.footnotes {if old.id!=note.id {assert!(after.footnotes.contains(old));}}
        s.key("cmd-z");assert_eq!(s.document(),before);let undo=s.save_as(&format!("h9-note-namespace-{variant}-undone.docx"));assert_eq!(std::fs::read(undo).unwrap(),data);s.key("cmd-shift-z");assert_eq!(s.document(),after);
        let path=s.save_as(&format!("h9-note-namespace-{variant}-typed.docx"));let bytes=std::fs::read(path).unwrap();let xml=ibis_pptx::test_files::part_text(&bytes,"word/footnotes.xml").unwrap();
        let source_xml=ibis_pptx::test_files::part_text(&data,"word/footnotes.xml").unwrap();assert_eq!(ibis_pptx::test_files::positive_footnote_ids(&xml),ibis_pptx::test_files::positive_footnote_ids(&source_xml),"source note IDs/order must remain unique");assert!(xml.contains(ibis_pptx::test_files::ORIGINAL_DELETION_XML));
        let saved=s.reopen();assert_eq!(flow_command::paragraph(flow(&saved),id).unwrap().runs,edited.runs);
        s.menu("docx.track.show");
    }
}

fn d3_story_reference_settings_preservation() {
    let root = crate::shell::scenario::repo_root();
    let original = std::fs::read(root.join(REPORT)).unwrap();
    for variant in 0..3 {
        let data =
            ibis_pptx::test_files::docx_with_story_relationship_namespace(&original, variant);
        let relative =
            format!("target/scenario-input/docx-story-settings-namespace-{variant}.docx");
        let input = root.join(&relative);
        std::fs::create_dir_all(input.parent().unwrap()).unwrap();
        std::fs::write(input, &data).unwrap();
        let mut s = Scenario::open(&relative);
        let before = s.document();
        let id = body(&before)[0].id;
        s.click_text(FlowPos::new(id, 0));
        s.menu("docx.page.landscape");
        let after = s.document();
        assert!(after.page.size.width > after.page.size.height);
        assert_ne!(after.page.size, before.page.size);
        let mut outside = after.clone();
        outside.page = before.page;
        assert_eq!(outside, before, "only page orientation changes");
        s.key("cmd-z");
        assert_eq!(s.document(), before);
        let undone = s.save_as(&format!("d3-story-settings-{variant}-undone.docx"));
        assert_eq!(std::fs::read(undone).unwrap(), data);
        s.key("cmd-shift-z");
        assert_eq!(s.document(), after);
        let path = s.save_as(&format!("d3-story-settings-{variant}-edited.docx"));
        let bytes = std::fs::read(path).unwrap();
        let before_xml = ibis_pptx::test_files::part_text(&data, "word/document.xml").unwrap();
        let after_xml = ibis_pptx::test_files::part_text(&bytes, "word/document.xml").unwrap();
        assert_eq!(
            ibis_pptx::test_files::story_reference_xmls(&after_xml),
            ibis_pptx::test_files::story_reference_xmls(&before_xml),
            "unrelated page setting must preserve all original reference scopes"
        );
        let saved = s.reopen();
        assert_eq!(flow(&saved).page, after.page);
        for kind in ibis_doc_model::PartKind::ALL {
            assert_eq!(
                ibis_doc_model::flow_command::resolved_part(flow(&saved), 0, kind),
                ibis_doc_model::flow_command::resolved_part(&after, 0, kind)
            );
        }
    }
}

fn d3_story_relationship_namespace() {
    story_relationship_namespace_cases(false);
}

fn d3_all_story_relationship_namespaces() {
    story_relationship_namespace_cases(true);
}

fn story_relationship_namespace_cases(all_types: bool) {
    use ibis_doc_model::{PartKind, flow_command};
    let root = crate::shell::scenario::repo_root();
    let original = std::fs::read(root.join(REPORT)).unwrap();
    let reference = ibis_pptx::read_docx(&original).unwrap();
    for variant in 0..3 {
        let data = if all_types {
            ibis_pptx::test_files::docx_with_all_story_relationship_namespaces(&original, variant)
        } else {
            ibis_pptx::test_files::docx_with_story_relationship_namespace(&original, variant)
        };
        let prefix = if all_types {
            "d3-all-story-namespace"
        } else {
            "d3-story-namespace"
        };
        let relative = if all_types {
            format!("target/scenario-input/docx-all-story-namespace-{variant}.docx")
        } else {
            format!("target/scenario-input/docx-story-namespace-{variant}.docx")
        };
        let input = root.join(&relative);
        std::fs::create_dir_all(input.parent().unwrap()).unwrap();
        std::fs::write(input, &data).unwrap();
        let menus = [
            (PartKind::Header, "docx.section.edit-header"),
            (PartKind::Footer, "docx.section.edit-footer"),
            (PartKind::HeaderFirst, "docx.section.edit-first-header"),
            (PartKind::FooterFirst, "docx.section.edit-first-footer"),
            (PartKind::HeaderEven, "docx.section.edit-even-header"),
            (PartKind::FooterEven, "docx.section.edit-even-footer"),
        ];
        for &(kind, menu) in if all_types { &menus[..] } else { &menus[..2] } {
            let mut s = Scenario::open(&relative);
            let before = s.document();
            let mut expected = flow(&reference).clone();
            expected.file_name = before.file_name.clone();
            expected.file_size = before.file_size;
            assert_eq!(
                before, expected,
                "qualified story references must preserve original whole model"
            );
            let blocks = flow_command::resolved_part(&before, 0, kind);
            let p = blocks
                .iter()
                .find_map(|b| {
                    if let Block::Paragraph(p) = b {
                        Some(p)
                    } else {
                        None
                    }
                })
                .unwrap();
            let id = p.id;
            let body_id = body(&before)[0].id;
            s.click_text(FlowPos::new(body_id, 0));
            s.menu(menu);
            if all_types {
                s.key("cmd-left");
                assert_eq!(
                    s.selection().map(|(_, caret)| caret),
                    Some(FlowPos::new(id, 0)),
                    "menu selects exact story"
                );
            } else {
                s.click_text(FlowPos::new(id, 0));
            }
            s.type_text("Q");
            let after = s.document();
            let edited = flow_command::paragraph(&after, id).unwrap();
            assert_eq!(edited.text(), format!("Q{}", p.text()));
            assert_eq!(after.body, before.body);
            assert_eq!(after.styles, before.styles);
            let mut outside = after.clone();
            match kind {
                PartKind::Header => outside.header = before.header.clone(),
                PartKind::Footer => outside.footer = before.footer.clone(),
                PartKind::HeaderFirst => outside.header_first = before.header_first.clone(),
                PartKind::FooterFirst => outside.footer_first = before.footer_first.clone(),
                PartKind::HeaderEven => outside.header_even = before.header_even.clone(),
                PartKind::FooterEven => outside.footer_even = before.footer_even.clone(),
            }
            assert_eq!(
                outside, before,
                "whole model outside edited story unchanged"
            );
            for other in PartKind::ALL {
                if other != kind {
                    assert_eq!(
                        flow_command::resolved_part(&after, 0, other),
                        flow_command::resolved_part(&before, 0, other)
                    );
                }
            }
            s.key("cmd-z");
            assert_eq!(s.document(), before);
            let undone = s.save_as(&format!("{prefix}-{variant}-{}-undone.docx", kind.index()));
            assert_eq!(std::fs::read(undone).unwrap(), data);
            s.key("cmd-shift-z");
            assert_eq!(s.document(), after);
            let path = s.save_as(&format!("{prefix}-{variant}-{}-edited.docx", kind.index()));
            let bytes = std::fs::read(path).unwrap();
            assert_eq!(
                ibis_pptx::test_files::part_text(&bytes, "word/document.xml"),
                ibis_pptx::test_files::part_text(&data, "word/document.xml")
            );
            let saved = s.reopen();
            assert_eq!(
                flow_command::resolved_part(flow(&saved), 0, kind),
                flow_command::resolved_part(&after, 0, kind)
            );
        }
    }
}

fn h11_picture_relationship_namespace() {
    let root = crate::shell::scenario::repo_root();
    let source = std::fs::read(root.join("test/editing/docx-paste-source.docx")).unwrap();
    let destination = std::fs::read(root.join("test/editing/docx-paste-destination.docx")).unwrap();
    let reference = ibis_pptx::read_docx(&source).unwrap();
    let expected_png = reference.media[0].data.clone();
    let foreign = ibis_pptx::read_docx(&destination).unwrap().media[0]
        .data
        .clone();
    assert_ne!(expected_png, foreign);
    for variant in 0..3 {
        let data = ibis_pptx::test_files::docx_with_picture_relationship_namespace(
            &source, &foreign, variant,
        );
        let relative = format!("target/scenario-input/docx-picture-namespace-{variant}.docx");
        let input = root.join(&relative);
        std::fs::create_dir_all(input.parent().unwrap()).unwrap();
        std::fs::write(input, &data).unwrap();
        let mut s = Scenario::open(&relative);
        let before = s.document();
        let p = body(&before)[0];
        let id = p.id;
        let (media, size) = p
            .runs
            .iter()
            .find_map(|r| match r.kind {
                FlowRunKind::Picture { media, size, .. } => Some((media, size)),
                _ => None,
            })
            .unwrap();
        assert_eq!(size, ibis_doc_model::EmuSize::new(190500, 190500));
        s.with(|e, _| {
            assert_eq!(
                e.presentation()
                    .media
                    .iter()
                    .find(|m| m.id == media)
                    .unwrap()
                    .data,
                expected_png,
                "qualified embed must select source PNG"
            )
        });
        s.click_text(FlowPos::new(id, 0));
        s.key("shift-right");
        s.key("cmd-b");
        let after = s.document();
        assert_ne!(after, before);
        assert_eq!(para(&after, id).text(), p.text());
        let mut outside = after.clone();
        for block in &mut outside.body {
            if let Block::Paragraph(p) = block
                && p.id == id
            {
                *p = para(&before, id).clone();
            }
        }
        assert_eq!(outside, before);
        s.key("cmd-z");
        assert_eq!(s.document(), before);
        let undone = s.save_as(&format!("h11-picture-namespace-{variant}-undone.docx"));
        assert_eq!(std::fs::read(undone).unwrap(), data);
        s.key("cmd-shift-z");
        assert_eq!(s.document(), after);
        let saved_path = s.save_as(&format!("h11-picture-namespace-{variant}-edited.docx"));
        let bytes = std::fs::read(saved_path).unwrap();
        let source_xml = ibis_pptx::test_files::part_text(&data, "word/document.xml").unwrap();
        let begin = source_xml.find("<a:blip ").unwrap();
        let end = source_xml[begin..].find("/>").unwrap() + begin + 2;
        let xml = ibis_pptx::test_files::part_text(&bytes, "word/document.xml").unwrap();
        assert!(
            xml.contains(&source_xml[begin..end]),
            "original drawing reference attrs retained"
        );
        for part in [
            "word/_rels/document.xml.rels",
            "word/styles.xml",
            "word/numbering.xml",
        ] {
            assert_eq!(
                ibis_pptx::test_files::part_text(&bytes, part),
                ibis_pptx::test_files::part_text(&data, part)
            );
        }
        let saved = s.reopen();
        assert_eq!(
            saved.media.iter().find(|m| m.id == media).unwrap().data,
            expected_png
        );
        assert!(
            body(flow(&saved))
                .iter()
                .any(|p| p.runs == para(&after, id).runs)
        );
    }
}

