fn h9_insertion_replacement_save_guard() {
    let root = crate::shell::scenario::repo_root();
    let report = std::fs::read(root.join(REPORT)).unwrap();
    for field in [false, true] {
        for tracked in [false, true] {
            let data = if field {
                ibis_pptx::test_files::docx_with_insertion_page_field(&report)
            } else {
                ibis_pptx::test_files::docx_with_insertion_run_comment(&report)
            };
            let relative = format!(
                "target/scenario-input/docx-insertion-replace-guard-{field}-{tracked}.docx"
            );
            let input = root.join(&relative);
            std::fs::create_dir_all(input.parent().unwrap()).unwrap();
            std::fs::write(input, &data).unwrap();
            let mut s = Scenario::open(&relative);
            if super::flow_layout::showing_markup() {
                s.menu("docx.track.show");
            }
            let baseline = s.document();
            assert!(!baseline.track_changes);
            if tracked {
                s.menu("docx.track.record");
            }
            let before = s.document();
            let path = s.with(|e, _| e.path.clone().unwrap());
            let id = body(&before)
                .into_iter()
                .find(|p| p.runs.iter().any(|r| r.revision.is_some()))
                .unwrap()
                .id;
            s.click_text(FlowPos::new(id, 3));
            s.key("shift-right");
            s.type_text("Q");
            let after = s.document();
            assert_eq!(final_text(para(&after, id)), "abXQYcd");
            s.key("cmd-s");
            assert_eq!(std::fs::read(&path).unwrap(), data);
            assert_eq!(s.document(), after);
            assert!(s.with(|e, _| {
                e.status
                    .as_ref()
                    .is_some_and(|t| t.contains("元の変更履歴"))
            }));
            s.key("cmd-z");
            assert_eq!(s.document(), before);
            if tracked {
                s.key("cmd-z");
                assert_eq!(s.document(), baseline);
            }
            s.key("cmd-s");
            assert_eq!(std::fs::read(&path).unwrap(), data);
            if tracked {
                s.key("cmd-shift-z");
                assert_eq!(s.document(), before);
            }
            s.key("cmd-shift-z");
            assert_eq!(s.document(), after);
            s.key("cmd-s");
            assert_eq!(std::fs::read(&path).unwrap(), data);
            assert_eq!(s.document(), after);
            if tracked {
                s.menu("docx.track.record");
            }
            s.menu("docx.track.show");
        }
    }
}

fn h9_distinct_source_link_frames() {
    let root = crate::shell::scenario::repo_root();
    let data = ibis_pptx::test_files::docx_with_distinct_link_frames(
        &std::fs::read(root.join(REPORT)).unwrap(),
    );
    let input = root.join("target/scenario-input/docx-distinct-link-frames.docx");
    std::fs::create_dir_all(input.parent().unwrap()).unwrap();
    std::fs::write(&input, &data).unwrap();
    let mut s = Scenario::open("target/scenario-input/docx-distinct-link-frames.docx");
    if super::flow_layout::showing_markup() {
        s.menu("docx.track.show");
    }
    let before = s.document();
    assert!(!before.track_changes);
    let id = body(&before)
        .into_iter()
        .find(|p| p.text() == "abX YM Ncd")
        .unwrap()
        .id;
    s.click_text(FlowPos::new(id, 0));
    s.key("shift-right");
    s.key("cmd-k");
    s.type_text("https://example.com/trigger-link");
    s.key("enter");
    s.update(|e, w, cx| e.focus_handle.focus(w, cx));
    let after = s.document();
    assert_ne!(after, before);
    assert_eq!(para(&after, id).text(), "abX YM Ncd");
    let mut outside = after.clone();
    for b in &mut outside.body {
        if let Block::Paragraph(p) = b
            && p.id == id
        {
            *p = para(&before, id).clone();
        }
    }
    outside.styles = before.styles.clone();
    assert_eq!(outside, before);
    s.key("cmd-z");
    assert_eq!(s.document(), before);
    let undo = s.save_as("h9-link-frames-undone.docx");
    assert_eq!(std::fs::read(undo).unwrap(), data);
    s.key("cmd-shift-z");
    assert_eq!(s.document(), after);
    let f = s.save_as("h9-link-frames-edited.docx");
    let bytes = std::fs::read(f).unwrap();
    let xml = ibis_pptx::test_files::part_text(&bytes, "word/document.xml").unwrap();
    for frame in ["first", "second"] {
        assert_eq!(
            xml.matches(&format!("w:history=\"0\" w:tgtFrame=\"{frame}\""))
                .count(),
            1
        );
    }
    let first = ibis_pptx::test_files::ORIGINAL_DELETION_XML
        .replace("w:delText", "w:t")
        .replace("w:del", "w:ins")
        .replace("841", "941");
    let second = first
        .replace("941", "951")
        .replace("ibis:marker=\"old\"", "ibis:marker=\"second\"")
        .replace("old history container", "second history container")
        .replace(">X </w:t>", ">M </w:t>")
        .replace(">Y</w:t>", ">N</w:t>");
    assert!(xml.contains(&first));
    assert!(xml.contains(&second));
    for part in ["word/settings.xml", "word/numbering.xml"] {
        assert_eq!(
            ibis_pptx::test_files::part_text(&bytes, part),
            ibis_pptx::test_files::part_text(&data, part)
        );
    }
    assert!(ibis_pptx::test_files::part_text(&bytes, "word/styles.xml").unwrap().contains("Hyperlink"));
    let saved = s.reopen();
    assert!(
        body(flow(&saved))
            .iter()
            .any(|p| p.runs == para(&after, id).runs)
    );
    s.menu("docx.track.show");
}

fn page_setup_click(s: &mut Scenario, id: &str) {
    let id = id.to_string();
    let b = s.with(|e, _| *e.doc_state().unwrap().helper.page_setup.as_ref().expect("the panel").ui.borrow().get(&id).unwrap_or_else(|| panic!("{id}")));
    s.click((f32::from(b.origin.x + b.size.width / 2.0), f32::from(b.origin.y + b.size.height / 2.0)));
}
/// Focus the page setup panel's input `which` (the row's centre is not the input).
fn page_setup_focus(s: &mut Scenario, which: &str) {
    s.update(|e, window, cx| {
        let p = e.doc_state().unwrap().helper.page_setup.as_ref().expect("the panel");
        let f = match which { "line-pitch" => p.line_pitch.clone(), "char-space" => p.char_space.clone(), "chars" => p.chars.clone(), "lines" => p.lines.clone(), _ => p.start.clone() };
        f.update(cx, |i, cx| i.focus(window, cx));
    });
}
fn page_setup_field(s: &mut Scenario, i: usize, text: &str) {
    // The row's centre is not the input any more (a label and a spinner share the row): focus the input itself.
    s.update(|e, window, cx| { let f = e.doc_state().unwrap().helper.page_setup.as_ref().expect("the panel").fields[i].clone(); f.update(cx, |i, cx| i.focus(window, cx)); });
    s.key("cmd-a");
    s.type_text(text);
}

/// DOCX-PAGE-001・003・004・005・007 表示形式 > ページ設定 > ページ設定…:
/// margins of 20 mm (left 25, right 15), a gutter of 10 mm, mirrored
/// margins and the body centred on its pages: the first page's text starts
/// at 35 mm (left + gutter), the second's at 15 mm (its outside margin on
/// the left); a too large margin refused; saved and read back.
fn page003_page_setup_panel() {
    let mut s = Scenario::open(REPORT);
    s.size(1200.0, 1000.0);
    s.menu("docx.page.setup");
    for (i, v) in [(0, "20"), (1, "20"), (2, "25"), (3, "15"), (4, "10")] {
        page_setup_field(&mut s, i, v);
    }
    page_setup_click(&mut s, "page-mirror");
    page_setup_click(&mut s, "apply");
    let page = s.with(|e, _| flow(e.presentation()).page);
    let mm = |v: f64| (v * 36_000.0) as i64;
    assert_eq!((page.top, page.left, page.right, page.gutter, page.mirror_margins), (mm(20.0), mm(25.0), mm(15.0), mm(10.0), true));
    // Where the pages' lines start.
    let starts = s.with(|e, _| {
        let pages = super::flow_layout::pages(e.flow().unwrap(), &e.resources);
        pages.pages.iter().take(2).map(|p| p.items.iter().filter_map(|i| if let super::flow_layout::Item::Line { x, .. } = i { Some(*x) } else { None }).fold(f32::MAX, f32::min)).collect::<Vec<_>>()
    });
    let pt = |v: f64| (v / 25.4 * 72.0) as f32;
    assert!((starts[0] - pt(35.0)).abs() < 1.0, "{starts:?}");
    assert!((starts[1] - pt(15.0)).abs() < 1.0, "{starts:?}");
    // Centred vertically: the first line lower than the top margin.
    page_setup_click(&mut s, "valign-center");
    page_setup_click(&mut s, "apply");
    assert_eq!(s.with(|e, _| flow(e.presentation()).page.v_align), ibis_doc_model::PageVAlign::Center);
    // Too large.
    page_setup_field(&mut s, 2, "300");
    page_setup_click(&mut s, "apply");
    assert_eq!(s.with(|e, _| flow(e.presentation()).page.left), mm(25.0));
    page_setup_field(&mut s, 2, "25");
    s.save_as("page003.docx");
    let saved = s.reopen();
    let page = flow(&saved).page;
    // (Saved in twips: within one.)
    assert!((page.gutter - mm(10.0)).abs() <= 635, "{}", page.gutter);
    assert_eq!((page.mirror_margins, page.v_align), (true, ibis_doc_model::PageVAlign::Center));
}

/// ページ設定… の文字列の方向（縦書き）と開始ページ番号: set, drawn (the
/// page's lines run down), saved and read back; blank goes on again.
fn page003_direction_and_start() {
    let mut s = Scenario::open(REPORT);
    s.size(1200.0, 1000.0);
    s.menu("docx.page.setup");
    page_setup_click(&mut s, "direction-vertical");
    s.update(|e, window, cx| { let f = e.doc_state().unwrap().helper.page_setup.as_ref().expect("the panel").start.clone(); f.update(cx, |i, cx| i.focus(window, cx)); });
    s.key("cmd-a");
    s.type_text("5");
    page_setup_click(&mut s, "apply");
    let page = s.with(|e, _| flow(e.presentation()).page);
    assert_eq!((page.direction, page.first_page), (ibis_doc_model::CellDirection::TbRl, 5));
    // The first line's box is at the paper's right now.
    let (w, x) = s.with(|e, _| {
        let pages = super::flow_layout::pages(e.flow().unwrap(), &e.resources);
        let p = &pages.pages[0];
        let x = p.items.iter().filter_map(|i| if let super::flow_layout::Item::Text { x, .. } = i { Some(*x) } else { None }).fold(0.0f32, f32::max);
        (p.width, x)
    });
    assert!(x > w * 0.7, "{x} of {w}");
    s.save_as("page003-vertical.docx");
    let saved = s.reopen();
    let page = flow(&saved).page;
    assert_eq!((page.direction, page.first_page), (ibis_doc_model::CellDirection::TbRl, 5));
    menu_closing(&mut s, "docx.page.setup");
    page_setup_click(&mut s, "direction-across");
    page_setup_click(&mut s, "apply");
    assert_eq!(s.with(|e, _| flow(e.presentation()).page.direction), ibis_doc_model::CellDirection::LrTb);
}

