/// DOCX-REF-004・005・006 挿入 > 脚注と文末脚注の設定…: two footnotes
/// numbered ①, ② … from 3 (③, ④) on the pages; the place and the
/// numbering kept; saved (footnotePr) and read back.
fn ref004_note_settings() {
    let mut s = Scenario::open(REPORT);
    let (_, id, _) = text_paragraph(&mut s, 12);
    for (i, at) in [2usize, 5].into_iter().enumerate() {
        s.click_text(FlowPos::new(id, at + i));
        s.menu("docx.footnote");
        s.type_text(&format!("注{}", i + 1));
    }
    s.menu("docx.notes.settings");
    s.update(|e, window, cx| e.edit_notes_panel(|n| n.format = ibis_doc_model::NoteFormat::DecimalEnclosedCircle, window, cx));
    notes_click(&mut s, "start");
    s.key("cmd-a");
    s.type_text("3");
    notes_click(&mut s, "restart-1");
    notes_click(&mut s, "apply");
    let page = s.with(|e, _| flow(e.presentation()).page);
    assert_eq!((page.footnotes.format, page.footnotes.start, page.footnotes.restart), (ibis_doc_model::NoteFormat::DecimalEnclosedCircle, 3, ibis_doc_model::NoteRestart::EachSection));
    let texts = s.with(|e, _| {
        let pages = super::flow_layout::pages(e.flow().unwrap(), &e.resources);
        pages.pages.iter().flat_map(|p| p.items.iter()).filter_map(|i| if let super::flow_layout::Item::Text { text, .. } = i { Some(text.to_string()) } else { None }).collect::<String>()
    });
    assert!(texts.contains('③') && texts.contains('④') && !texts.contains('①'), "the marks numbered from ③");
    s.save_as("ref004.docx");
    let saved = s.reopen();
    let page = flow(&saved).page;
    assert_eq!((page.footnotes.format, page.footnotes.start, page.footnotes.restart), (ibis_doc_model::NoteFormat::DecimalEnclosedCircle, 3, ibis_doc_model::NoteRestart::EachSection));
}

