/// DOCX-REF-008 挿入 > ブックマーク…: a bad name refused; 見出し1 added at
/// one paragraph, moved to another by adding it again there; the caret
/// sent to it by ジャンプ from elsewhere; a second one deleted; saved
/// and read back.
fn ref008_bookmarks() {
    let mut s = Scenario::open(REPORT);
    let (_, a, _) = text_paragraph(&mut s, 12);
    let b = {
        let doc = s.document();
        body(&doc).into_iter().find(|p| p.id != a && p.len() >= 12 && !p.text().contains('\u{fffc}') && p.list.is_none()).expect("a second paragraph").id
    };
    let marks = |s: &mut Scenario| s.with(|e, _| body(flow(e.presentation())).iter().flat_map(|p| p.bookmarks.iter().map(|n| (n.clone(), p.id)).collect::<Vec<_>>()).filter(|(n, _)| !n.starts_with('_')).collect::<Vec<_>>());
    let before = marks(&mut s);
    s.click_text(FlowPos::new(a, 1));
    s.menu("docx.bookmark");
    bookmark_click(&mut s, "name");
    s.type_text("1st");
    bookmark_click(&mut s, "add");
    assert_eq!(marks(&mut s), before, "a name starting with a digit refused");
    s.key("cmd-a");
    s.type_text("見出し1");
    bookmark_click(&mut s, "add");
    assert!(marks(&mut s).contains(&("見出し1".into(), a)));
    // The bookmark dialog is modal: the caret moves without the mouse.
    s.update(|e, _, cx| e.set_caret(FlowPos::new(b, 1), false, cx));
    bookmark_click(&mut s, "add");
    let now = marks(&mut s);
    let msg = s.with(|e, _| (e.doc_state().unwrap().helper.bookmarks.as_ref().map(|p| p.message.clone()), e.ordered_selection().map(|(p, _)| p.para)));
    assert!(now.contains(&("見出し1".into(), b)) && !now.contains(&("見出し1".into(), a)), "moved: {now:?} a={a} b={b} {msg:?}");
    bookmark_click(&mut s, "name");
    s.key("cmd-a");
    s.type_text("Temp_2");
    bookmark_click(&mut s, "add");
    assert!(marks(&mut s).contains(&("Temp_2".into(), b)));
    bookmark_click(&mut s, "delete");
    assert!(!marks(&mut s).iter().any(|(n, _)| n == "Temp_2"));
    s.update(|e, _, cx| e.set_caret(FlowPos::new(a, 3), false, cx));
    bookmark_click(&mut s, "item-見出し1");
    bookmark_click(&mut s, "jump");
    assert_eq!(s.with(|e, _| e.ordered_selection().map(|(p, _)| p.para)), Some(b), "jumped to 見出し1");
    s.save_as("ref008.docx");
    let saved = s.reopen();
    let back: Vec<(String, u32)> = body(flow(&saved)).iter().flat_map(|p| p.bookmarks.iter().map(|n| (n.clone(), p.id)).collect::<Vec<_>>()).collect();
    assert_eq!(back.iter().filter(|(n, _)| n == "見出し1").count(), 1);
    assert!(!back.iter().any(|(n, _)| n == "Temp_2"));
}

