/// The parts of a saved file whose text has `needle`.
fn parts_with(path: &std::path::Path, needle: &str) -> Vec<String> {
    let bytes = std::fs::read(path).unwrap();
    (1..=6).flat_map(|i| [format!("word/header{i}.xml")]).filter(|name| ibis_pptx::test_files::part_text(&bytes, name).is_some_and(|t| t.contains(needle))).collect()
}

/// DOCX-PAGE-019 デザイン > 透かし…: Word's 社外秘, red, horizontal, drawn
/// behind every page's text; saved as Word's WordArt in the headers and
/// read back; then removed. A new document (no header) gets a header for
/// it.
fn page019_watermark() {
    let mut s = Scenario::open(REPORT);
    s.menu("docx.watermark");
    watermark_click(&mut s, "text-0");
    watermark_click(&mut s, "color-3");
    watermark_click(&mut s, "horizontal");
    watermark_click(&mut s, "apply");
    let w = s.with(|e, _| flow(e.presentation()).watermark.clone()).expect("a watermark");
    assert_eq!((w.text.as_str(), w.color.0, w.diagonal(), w.semitransparent), ("社外秘", 0xFF0000, false, true));
    let firsts = s.with(|e, _| {
        let pages = super::flow_layout::pages(e.flow().unwrap(), &e.resources);
        // One shape a character (a CJK watermark), first on the page.
        pages.pages.iter().map(|p| p.items.iter().take(3).filter_map(|i| if let super::flow_layout::Item::Shape { shape, .. } = i { shape.text_body().map(|b| b.text()) } else { None }).collect::<String>() == "社外秘").collect::<Vec<_>>()
    });
    assert!(!firsts.is_empty() && firsts.iter().all(|&f| f), "behind every page: {firsts:?}");
    s.screenshot("page019-watermark.png");
    s.update(|e,w,cx|e.close_panel_dialog(w,cx));
    let file = s.save_as("page019.docx");
    assert!(!parts_with(&file, "PowerPlusWaterMarkObject").is_empty(), "in a header");
    let saved = s.reopen();
    let back = flow(&saved).watermark.clone().expect("read back");
    assert!(back.size.is_some(), "the size written");
    assert_eq!(ibis_doc_model::Watermark { size: None, ..back }, w);
    // Removed: no header keeps it.
    s.menu("docx.watermark");
    watermark_click(&mut s, "remove");
    assert!(s.with(|e, _| flow(e.presentation()).watermark.is_none()));
    let file = s.save_as("page019-removed.docx");
    assert!(parts_with(&file, "PowerPlusWaterMarkObject").is_empty());
    assert!(flow(&s.reopen()).watermark.is_none());
    drop(s);

    // A new document: a header made for it, diagonal by default.
    let mut s = Scenario::start_view();
    s.menu("file.new.document");
    assert!(s.with(|e, _| e.flow().is_some_and(|d| d.header.is_empty())));
    s.menu("docx.watermark");
    watermark_click(&mut s, "custom");
    watermark_click(&mut s, "text");
    s.key("cmd-a");
    s.type_text("DRAFT");
    watermark_click(&mut s, "apply");
    let file = s.save_as("page019-new.docx");
    assert_eq!(parts_with(&file, "string=\"DRAFT\"").len(), 1);
    let back = flow(&s.reopen()).watermark.clone().expect("read back");
    assert_eq!((back.text.as_str(), back.diagonal(), back.color.0), ("DRAFT", true, 0xC0C0C0));
}

