/// DOCX-STYLE-005・007 スタイルの一覧 > 新しいスタイル…: a paragraph
/// style 要点 (bold) from the caret's formatting, based on its style and
/// applied to its paragraph; a name taken refused; a character style 赤字
/// (red) on a selection; heading 2's base taken off; saved and read back.
fn style005_new_style() {
    let mut s = Scenario::open(REPORT);
    let (_, a, _) = text_paragraph(&mut s, 12);
    let b = {
        let doc = s.document();
        body(&doc).into_iter().find(|p| p.id != a && p.len() >= 12 && !p.text().contains('\u{fffc}') && p.list.is_none()).expect("a second paragraph").id
    };
    let style_of = |s: &mut Scenario, id: u32| s.with(move |e, _| body(flow(e.presentation())).into_iter().find(|p| p.id == id).unwrap().style.clone());
    // The paragraph's style (its own, else the default one).
    let before = style_of(&mut s, a).or_else(|| s.with(|e, _| flow(e.presentation()).styles.default_paragraph.clone()));
    s.click_text(FlowPos::new(a, 2));
    s.toolbar_menu("style", "docx.style.new");
    new_style_click(&mut s, "name");
    s.type_text("要点");
    new_style_click(&mut s, "bold");
    s.screenshot("style005-panel.png");
    new_style_click(&mut s, "create");
    let (id, style) = s.with(|e, _| flow(e.presentation()).styles.styles.iter().find(|(_, st)| st.name == "要点").map(|(i, st)| (i.clone(), st.clone()))).unwrap_or_else(|| panic!("made: {:?}", s.with(|e, cx| e.doc_state().and_then(|st| st.helper.new_style.as_ref()).map(|p| (p.message.clone(), p.name.read(cx).value().to_string())))));
    assert_eq!((style.kind, style.based_on.clone(), style.next.clone(), style.run.bold), (ibis_doc_model::StyleKind::Paragraph, before.clone(), Some(id.clone()), Some(true)));
    assert_eq!(style_of(&mut s, a), Some(id.clone()), "applied");
    assert!(s.with(move |e, _| body(flow(e.presentation())).into_iter().find(|p| p.id == a).unwrap().runs.iter().all(|r| r.style.bold)), "drawn bold");
    assert!(s.with(|e, _| e.doc_state().unwrap().helper.new_style.is_none()), "closed when made");
    // The same name again: refused.
    s.toolbar_menu("style", "docx.style.new");
    new_style_click(&mut s, "name");
    s.type_text("要点");
    new_style_click(&mut s, "create");
    assert_eq!(s.with(|e, _| flow(e.presentation()).styles.styles.values().filter(|st| st.name == "要点").count()), 1);
    s.update(|e,w,cx|e.close_panel_dialog(w,cx));
    // A character style on three characters of another paragraph.
    s.click_text(FlowPos::new(b, 1));
    for _ in 0..3 {
        s.key("shift-right");
    }
    s.toolbar_menu("style", "docx.style.new");
    new_style_click(&mut s, "character");
    new_style_click(&mut s, "name");
    s.type_text("赤字");
    new_style_click(&mut s, "color");
    s.key("cmd-a");
    s.type_text("FF0000");
    new_style_click(&mut s, "create");
    let red = s.with(|e, _| flow(e.presentation()).styles.styles.iter().find(|(_, st)| st.name == "赤字").map(|(i, _)| i.clone())).expect("made");
    let marked = s.with(move |e, _| body(flow(e.presentation())).into_iter().find(|p| p.id == b).unwrap().runs.iter().filter(|r| r.char_style.is_some()).map(|r| (r.char_style.clone(), r.len(), r.style.color.0)).collect::<Vec<_>>());
    assert_eq!(marked, vec![(Some(red.clone()), 3, 0xFF0000)]);
    // Heading 2's base taken off.
    let heading = s.with(|e, _| body(flow(e.presentation())).into_iter().find(|p| p.style.as_deref() == Some("2")).map(|p| p.id)).expect("a heading 2");
    s.click_text(FlowPos::new(heading, 1));
    s.toolbar_menu("style", "docx.style.new");
    new_style_click(&mut s, "rebase-apply");
    assert_eq!(s.with(|e, _| flow(e.presentation()).styles.styles["2"].based_on.clone()), None);
    s.save_as("style005.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let made = d.styles.styles.get(&id).expect("要点 saved");
    assert_eq!((made.name.as_str(), made.based_on.clone(), made.run.bold), ("要点", before, Some(true)));
    assert_eq!(body(d).into_iter().find(|p| p.id == a).and_then(|p| p.style.clone()), Some(id));
    let red_style = d.styles.styles.get(&red).expect("赤字 saved");
    assert_eq!((red_style.kind, red_style.run.color, red_style.run.bold), (ibis_doc_model::StyleKind::Character, Some(ibis_doc_model::Rgb(0xFF0000)), None));
    assert!(body(d).into_iter().any(|p| p.runs.iter().any(|r| r.char_style.as_ref() == Some(&red) && r.style.color.0 == 0xFF0000)));
    assert_eq!(d.styles.styles["2"].based_on, None);
}

/// DOCX-STYLE-002 スタイルの一覧 > 文字スタイル: the document's
/// character styles (Intense Emphasis, Intense Reference; not the
/// headings' linked ones) on a selection, on the word at the caret (no
/// selection), and taken off; saved and read back.
fn style002_character_styles() {
    let mut s = Scenario::open(REPORT);
    let offered = s.with(|e, _| super::style_new::document_character_styles(flow(e.presentation())));
    assert_eq!(offered.iter().map(|(_, l)| l.as_str()).collect::<Vec<_>>(), ["Intense Emphasis", "Intense Reference"]);
    let (emphasis, reference) = (offered[0].0.clone(), offered[1].0.clone());
    let (_, a, _) = text_paragraph(&mut s, 12);
    let runs = |s: &mut Scenario| s.with(move |e, _| body(flow(e.presentation())).into_iter().find(|p| p.id == a).unwrap().runs.iter().filter(|r| r.char_style.is_some()).map(|r| (r.char_style.clone().unwrap(), r.len())).collect::<Vec<_>>());
    s.click_text(FlowPos::new(a, 1));
    for _ in 0..3 {
        s.key("shift-right");
    }
    s.toolbar_menu("style", "docx.cstyle.1");
    assert_eq!(runs(&mut s), vec![(emphasis.clone(), 3)]);
    assert_eq!(s.selection(), Some((FlowPos::new(a, 1), FlowPos::new(a, 4))), "the selection kept");
    // No selection: the word at the caret.
    let text = s.with(move |e, _| body(flow(e.presentation())).into_iter().find(|p| p.id == a).unwrap().text());
    let at = text.chars().count() - 3;
    s.click_text(FlowPos::new(a, at));
    s.toolbar_menu("style", "docx.cstyle.2");
    let marked = runs(&mut s);
    assert!(marked.iter().any(|(id, len)| *id == reference && *len >= 1), "{marked:?}");
    // Taken off the first.
    s.click_text(FlowPos::new(a, 1));
    for _ in 0..3 {
        s.key("shift-right");
    }
    s.toolbar_menu("style", "docx.cstyle.clear");
    assert!(!runs(&mut s).iter().any(|(id, _)| *id == emphasis));
    s.save_as("style002.docx");
    let saved = s.reopen();
    let p = body(flow(&saved)).into_iter().find(|p| p.id == a).unwrap().clone();
    assert!(p.runs.iter().any(|r| r.char_style.as_ref() == Some(&reference)));
    assert!(!p.runs.iter().any(|r| r.char_style.as_ref() == Some(&emphasis)));
}

/// DOCX-STYLE-003: リンクスタイルの適用 — create link with ⌘K, verify automatic
/// `Hyperlink` character style application (blue #0563C1 and single underline),
/// 1-step undo/redo of link & style together, save and reopen retaining style,
/// and removal of link clearing the character style and restoring format.
fn style003_hyperlink_style() {
    let mut s = Scenario::open(REPORT);
    let (_, id, _) = text_paragraph(&mut s, 10);
    s.click_text(FlowPos::new(id, 2));
    for _ in 0..4 {
        s.key("shift-right");
    }
    s.key("cmd-k");
    assert!(s.with(|e, _| e.doc_state().is_some_and(|st| st.link.is_some())), "link panel opened");
    s.type_text("https://ibis.inc/");
    s.key("enter");

    // Verify link & style applied
    let run_info = |s: &mut Scenario| {
        s.with(|e, _| {
            para(flow(e.presentation()), id)
                .runs
                .iter()
                .find(|r| r.link == Some(ibis_doc_model::Link::Url("https://ibis.inc/".into())))
                .map(|r| (r.char_style.clone(), r.style.color, r.style.underline, para(flow(e.presentation()), id).runs.iter().filter(|r|r.link==Some(ibis_doc_model::Link::Url("https://ibis.inc/".into()))).map(|r|r.len()).sum::<usize>()))
        })
    };
    let info = run_info(&mut s).expect("linked run exists");
    assert_eq!(info.0.as_deref(), Some("Hyperlink"), "char_style is Hyperlink");
    assert_eq!(info.1, ibis_doc_model::Rgb(0x0563C1), "color is Office hyperlink blue #0563C1");
    assert!(info.2, "underline is enabled");
    assert_eq!(info.3, 4, "4 characters styled");

    // 1-step Undo restores original text without link and without Hyperlink style
    s.menu("edit.undo");
    assert!(run_info(&mut s).is_none(), "link undone");
    let unstyled = s.with(|e, _| {
        para(flow(e.presentation()), id).runs.iter().all(|r| r.char_style.as_deref() != Some("Hyperlink"))
    });
    assert!(unstyled, "style undone");

    // 1-step Redo reapplies link and Hyperlink style
    s.menu("edit.redo");
    let redone = run_info(&mut s).expect("link redone");
    assert_eq!(redone.0.as_deref(), Some("Hyperlink"));
    assert_eq!(redone.1, ibis_doc_model::Rgb(0x0563C1));
    assert!(redone.2);

    // Save and reopen persists w:hyperlink and w:rStyle w:val="Hyperlink"
    s.save_as("style003_link.docx");
    let saved = s.reopen();
    let saved_para = body(flow(&saved)).into_iter().find(|p| p.id == id).expect("target paragraph exists");
    let saved_run = saved_para
        .runs
        .iter()
        .find(|r| r.link == Some(ibis_doc_model::Link::Url("https://ibis.inc/".into())))
        .expect("saved linked run exists");
    assert_eq!(saved_run.char_style.as_deref(), Some("Hyperlink"));
    assert_eq!(saved_run.style.color, ibis_doc_model::Rgb(0x0563C1));
    assert!(saved_run.style.underline);

    // Select linked text with the caret API; ordinary clicking now opens its URL.
    s.update(|e,_,cx|e.set_caret(FlowPos::new(id,2),false,cx));
    for _ in 0..4 {
        s.key("shift-right");
    }
    s.update(|e, _, cx| e.set_link("", cx));
    assert!(run_info(&mut s).is_none(), "link removed");
    let cleared = s.with(|e, _| {
        para(flow(e.presentation()), id).runs.iter().all(|r| r.char_style.as_deref() != Some("Hyperlink"))
    });
    assert!(cleared, "Hyperlink character style cleared on removal");

    // Save and reopen persists removal
    s.save_as("style003_link_cleared.docx");
    let reopened = s.reopen();
    let p_cleared = body(flow(&reopened)).into_iter().find(|p| p.id == id).expect("paragraph exists");
    assert!(!p_cleared.runs.iter().any(|r| r.link.is_some() || r.char_style.as_deref() == Some("Hyperlink")));
}

/// DOCX-LIST-003・010 表示形式 > 段落番号 > 番号の書式・番号の後: two
/// paragraphs numbered, then in ① ② (drawn so), with nothing after the
/// number; a paragraph out of a list numbered 一、 from the library;
/// saved and read back.
fn list003_number_formats() {
    let mut s = Scenario::open(REPORT);
    let (_, id, _) = text_paragraph(&mut s, 12);
    s.click_text(FlowPos::new(id, 0));
    s.update(|e, _, cx| e.toggle_list(false, cx));
    s.menu("docx.list.format-circled");
    let level = |s: &mut Scenario, id: u32| s.with(move |e, _| {
        let d = flow(e.presentation());
        let p = body(d).into_iter().find(|p| p.id == id).unwrap();
        let l = p.list.unwrap();
        let lv = d.styles.numbering.level(l.num_id, l.level).unwrap();
        (lv.format.clone(), lv.text.clone(), lv.suffix)
    });
    assert_eq!(level(&mut s, id), ("decimalEnclosedCircle".into(), "%1".into(), ibis_doc_model::ListSuffix::Tab));
    let texts = s.with(|e, _| {
        let pages = super::flow_layout::pages(e.flow().unwrap(), &e.resources);
        pages.pages.iter().flat_map(|p| p.items.iter()).filter_map(|i| if let super::flow_layout::Item::Text { text, .. } = i { Some(text.to_string()) } else { None }).collect::<String>()
    });
    assert!(texts.contains('①'), "drawn as ①");
    assert_eq!(s.menu_state("docx.list.format-circled").map(|m| m.1), Some(true));
    s.menu("docx.list.suffix-none");
    assert_eq!(level(&mut s, id).2, ibis_doc_model::ListSuffix::Nothing);
    // Out of a list: a new list in the library's format.
    let (_, other, _) = text_paragraph(&mut s, 20);
    s.click_text(FlowPos::new(other, 0));
    s.menu("docx.list.format-kanji");
    assert_eq!(level(&mut s, other).0, "japaneseCounting");
    s.save_as("list003.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let formats: Vec<String> = body(d).iter().filter_map(|p| p.list).filter_map(|l| d.styles.numbering.level(l.num_id, l.level)).map(|lv| lv.format.clone()).collect();
    assert!(formats.contains(&"decimalEnclosedCircle".to_string()) && formats.contains(&"japaneseCounting".to_string()), "{formats:?}");
}

/// DOCX-JA-008 縦書きと横書きの切り替え、メニューのチェック状態、キャレット操作・当たり判定
fn ja008_vertical_horizontal() {
    let mut s = Scenario::open(REPORT);
    let (_, id, _) = text_paragraph(&mut s, 10);
    // 最初は横書き
    assert_eq!(s.with(|e, _| flow(e.presentation()).page.direction), ibis_doc_model::CellDirection::LrTb);
    assert_eq!(s.menu_state("docx.page.direction.horizontal").map(|m| m.1), Some(true));
    assert_eq!(s.menu_state("docx.page.direction.vertical").map(|m| m.1), Some(false));

    // メニューから縦書きに切り替え
    s.menu("docx.page.direction.vertical");
    assert_eq!(s.with(|e, _| flow(e.presentation()).page.direction), ibis_doc_model::CellDirection::TbRl);
    assert_eq!(s.menu_state("docx.page.direction.horizontal").map(|m| m.1), Some(false));
    assert_eq!(s.menu_state("docx.page.direction.vertical").map(|m| m.1), Some(true));

    // レイアウトの行が vertical であることを確認
    let lines = s.with(|e, _| e.flow_lines());
    assert!(lines.iter().any(|l| l.vertical), "vertical lines exist");

    // クリックしてキャレットを配置
    s.click_text(FlowPos::new(id, 0));
    assert_eq!(s.selection().map(|(_, c)| c), Some(FlowPos::new(id, 0)));

    // 縦書き時のキャレットボックス
    let box0 = s.with(|e, _| e.caret_box(&e.flow_lines(), FlowPos::new(id, 0)).unwrap());

    // 縦書きで ↓ キーを押すと次の文字へ進む（横書きの右キー相当）
    s.key("down");
    assert_eq!(s.selection().map(|(_, c)| c), Some(FlowPos::new(id, 1)));
    let box1 = s.with(|e, _| e.caret_box(&e.flow_lines(), FlowPos::new(id, 1)).unwrap());
    assert!(box1.2 > box0.2, "caret moved down: {} > {}", box1.2, box0.2);

    // ↑ キーで前の文字へ戻る
    s.key("up");
    assert_eq!(s.selection().map(|(_, c)| c), Some(FlowPos::new(id, 0)));

    // 保存して開き直しても縦書きが保持される
    s.save_as("ja008_vertical.docx");
    let saved = s.reopen();
    assert_eq!(flow(&saved).page.direction, ibis_doc_model::CellDirection::TbRl);

    // 再度横書きに戻す
    s.menu("docx.page.direction.horizontal");
    assert_eq!(s.with(|e, _| flow(e.presentation()).page.direction), ibis_doc_model::CellDirection::LrTb);
    assert_eq!(s.menu_state("docx.page.direction.horizontal").map(|m| m.1), Some(true));
    assert_eq!(s.menu_state("docx.page.direction.vertical").map(|m| m.1), Some(false));
}

/// DOCX-FONT-009 文字の網かけと囲い線のメニュー操作、トグル、保存・再オープン
fn font009_character_border_and_shading() {
    let mut s = Scenario::open(REPORT);
    let (_, id, _) = text_paragraph(&mut s, 10);
    s.click_text(FlowPos::new(id, 2));
    for _ in 0..3 {
        s.key("shift-right");
    }
    assert_eq!(s.selection(), Some((FlowPos::new(id, 2), FlowPos::new(id, 5))));

    // 最初は囲み線・網かけともにオフ
    assert_eq!(s.menu_state("docx.text.border").map(|m| m.1), Some(false));
    assert_eq!(s.menu_state("docx.text.shading").map(|m| m.1), Some(false));

    // 文字の囲み線を適用
    s.menu("docx.text.border");
    assert_eq!(s.menu_state("docx.text.border").map(|m| m.1), Some(true));
    let doc = s.document();
    let p = para(&doc, id);
    assert!(p.runs.iter().any(|r| r.style.border.is_some()), "border is applied to run");

    // 文字の網かけを適用
    s.menu("docx.text.shading");
    assert_eq!(s.menu_state("docx.text.shading").map(|m| m.1), Some(true));
    let doc = s.document();
    let p = para(&doc, id);
    assert!(p.runs.iter().any(|r| r.style.highlight == Some(ibis_doc_model::Rgb(0xd9d9d9))), "shading is applied to run");

    // 保存して開き直しても保持される
    s.save_as("font009_border_shading.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let p_saved = para(d, id);
    assert!(p_saved.runs.iter().any(|r| r.style.border.is_some()), "border saved and reopened");
    assert!(p_saved.runs.iter().any(|r| r.style.highlight == Some(ibis_doc_model::Rgb(0xd9d9d9))), "shading saved and reopened");

    // トグルして解除
    s.menu("docx.text.border");
    assert_eq!(s.menu_state("docx.text.border").map(|m| m.1), Some(false));
    let doc = s.document();
    let p = para(&doc, id);
    assert!(!p.runs.iter().any(|r| r.style.border.is_some()), "border removed");

    s.menu("docx.text.shading");
    assert_eq!(s.menu_state("docx.text.shading").map(|m| m.1), Some(false));
    let doc = s.document();
    let p = para(&doc, id);
    assert!(!p.runs.iter().any(|r| r.style.highlight == Some(ibis_doc_model::Rgb(0xd9d9d9))), "shading removed");
}

/// DOCX-JA-020 文字種の変換（全角半角・大文字小文字・ひらがなカタカナ）
fn ja020_case_conversion() {
    let mut s = Scenario::open(REPORT);
    let (_, id, _) = text_paragraph(&mut s, 10);
    s.click_text(FlowPos::new(id, 0));
    // The text is typed as it stands: the case conversions below are what is tested.
    s.menu("docx.edit.autocorrect");
    s.type_text("hello world. this is ibis.\n");

    let doc = s.document();
    let p_new = body(&doc).into_iter().find(|p| p.text().starts_with("hello world.")).unwrap();
    let new_id = p_new.id;
    let new_len = p_new.len();
    s.click_text(FlowPos::new(new_id, 0));
    for _ in 0..new_len {
        s.key("shift-right");
    }

    // UPPERCASE
    s.menu("docx.text.case.upper");
    assert_eq!(para(&s.document(), new_id).text(), "HELLO WORLD. THIS IS IBIS.");

    // Undo -> lowercase
    s.key("cmd-z");
    assert_eq!(para(&s.document(), new_id).text(), "hello world. this is ibis.");

    // Capitalize Each Word (Title Case)
    s.menu("docx.text.case.title");
    assert_eq!(para(&s.document(), new_id).text(), "Hello World. This Is Ibis.");

    // Sentence case
    s.menu("docx.text.case.sentence");
    assert_eq!(para(&s.document(), new_id).text(), "Hello world. This is ibis.");

    // tOGGLE cASE
    s.menu("docx.text.case.toggle");
    assert_eq!(para(&s.document(), new_id).text(), "hELLO WORLD. tHIS IS IBIS.");

    // 日本語カナ・全角半角変換
    s.click_text(FlowPos::new(new_id, 0));
    for _ in 0..para(&s.document(), new_id).len() {
        s.key("shift-right");
    }
    s.type_text("あいうえお がぎぐげご ＡＢＣ１２３");
    s.click_text(FlowPos::new(new_id, 0));
    for _ in 0..para(&s.document(), new_id).len() {
        s.key("shift-right");
    }

    // カタカナ
    s.menu("docx.text.case.katakana");
    assert_eq!(para(&s.document(), new_id).text(), "アイウエオ ガギグゲゴ ＡＢＣ１２３");

    // 半角
    s.menu("docx.text.case.half-width");
    assert_eq!(para(&s.document(), new_id).text(), "ｱｲｳｴｵ ｶﾞｷﾞｸﾞｹﾞｺﾞ ABC123");

    // 全角
    s.menu("docx.text.case.full-width");
    assert_eq!(para(&s.document(), new_id).text(), "アイウエオ　ガギグゲゴ　ＡＢＣ１２３");

    // ひらがな
    s.menu("docx.text.case.hiragana");
    assert_eq!(para(&s.document(), new_id).text(), "あいうえお　がぎぐげご　ＡＢＣ１２３");

    // 保存して開き直しても保持される
    s.save_as("ja020_case_conversion.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let p_saved = body(d).into_iter().find(|p| p.id == new_id).unwrap();
    assert_eq!(p_saved.text(), "あいうえお　がぎぐげご　ＡＢＣ１２３");
}

fn tblfmt007_distribute_columns_and_rows() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");
    // 表の挿入 (3x3)
    s.menu("docx.table.insert-3x3");
    let table = |s: &mut Scenario| {
        s.document()
            .body
            .into_iter()
            .rev()
            .find_map(|b| if let Block::Table(t) = b { Some(t) } else { None })
            .unwrap()
    };
    let t_init = table(&mut s);
    assert_eq!(t_init.rows.len(), 3);
    assert_eq!(t_init.columns.len(), 3);

    // 列幅を均等化 (EqualColumns)
    s.menu("docx.table.equal-columns");
    let t_eq_cols = table(&mut s);
    let total_w: i64 = t_eq_cols.columns.iter().sum();
    assert_eq!(total_w, t_init.columns.iter().sum::<i64>());
    assert_eq!(t_eq_cols.columns[0], t_eq_cols.columns[1]);

    // 行高を均等化 (EqualRows)
    s.menu("docx.table.equal-rows");
    let after_equal = s.document();
    let t_eq_rows = table(&mut s);
    assert_eq!(t_eq_rows.rows.len(), 3);
    assert_eq!(t_eq_rows.rows[0].height, ibis_doc_model::RowHeight::AtLeast(20 * 12700));
    assert_eq!(t_eq_rows.rows[1].height, ibis_doc_model::RowHeight::AtLeast(20 * 12700));
    assert_eq!(t_eq_rows.rows[2].height, ibis_doc_model::RowHeight::AtLeast(20 * 12700));

    // Undo で元の行高 (Auto) に戻る
    s.key("cmd-z");
    let t_undone = table(&mut s);
    assert_eq!(t_undone.rows[0].height, ibis_doc_model::RowHeight::Auto);

    // Redo で均等化が再適用される
    s.key("cmd-shift-z");
    assert_eq!(s.document(), after_equal);

    // 保存して開き直しても trHeight が保持される
    s.save_as("tblfmt007_distribute.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let t_saved = d.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_saved.rows[0].height, ibis_doc_model::RowHeight::AtLeast(20 * 12700));
    assert_eq!(t_saved.rows[1].height, ibis_doc_model::RowHeight::AtLeast(20 * 12700));
    assert_eq!(t_saved.rows[2].height, ibis_doc_model::RowHeight::AtLeast(20 * 12700));
}

fn tblfmt011_cell_text_direction() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");
    // 表の挿入 (2x2)
    s.menu("docx.table.insert-2x2");
    let table = |s: &mut Scenario| {
        s.document()
            .body
            .into_iter()
            .rev()
            .find_map(|b| if let Block::Table(t) = b { Some(t) } else { None })
            .unwrap()
    };
    let t_init = table(&mut s);
    assert_eq!(t_init.rows[0].cells[0].direction, ibis_doc_model::CellDirection::LrTb);

    // Initial check state
    assert_eq!(s.menu_state("docx.cell.direction.lrtb"), Some((true, true)));
    assert_eq!(s.menu_state("docx.cell.direction.tbrl"), Some((true, false)));

    // 1. Change text direction to vertical right-to-left (tbRl)
    s.menu("docx.cell.direction.tbrl");
    let t_v1 = table(&mut s);
    assert_eq!(t_v1.rows[0].cells[0].direction, ibis_doc_model::CellDirection::TbRl);
    assert_eq!(s.menu_state("docx.cell.direction.tbrl"), Some((true, true)));
    assert_eq!(s.menu_state("docx.cell.direction.lrtb"), Some((true, false)));

    // 2. Change text direction to rotated 270 (btLr)
    s.menu("docx.cell.direction.btlr");
    let t_v2 = table(&mut s);
    assert_eq!(t_v2.rows[0].cells[0].direction, ibis_doc_model::CellDirection::BtLr);
    assert_eq!(s.menu_state("docx.cell.direction.btlr"), Some((true, true)));
    assert_eq!(s.menu_state("docx.cell.direction.tbrl"), Some((true, false)));

    // 3. Undo / Redo
    s.key("cmd-z");
    let t_u1 = table(&mut s);
    assert_eq!(t_u1.rows[0].cells[0].direction, ibis_doc_model::CellDirection::TbRl);

    s.key("cmd-z");
    let t_u2 = table(&mut s);
    assert_eq!(t_u2.rows[0].cells[0].direction, ibis_doc_model::CellDirection::LrTb);

    s.key("cmd-shift-z");
    let t_r1 = table(&mut s);
    assert_eq!(t_r1.rows[0].cells[0].direction, ibis_doc_model::CellDirection::TbRl);

    // 4. Save and reopen
    s.save_as("tblfmt011_direction.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let t_saved = d.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_saved.rows[0].cells[0].direction, ibis_doc_model::CellDirection::TbRl);
}

fn tblfmt008_cell_margins() {
    use crate::docx::toolbar::{CELL_MARGIN_NARROW, CELL_MARGIN_NONE, CELL_MARGIN_NORMAL, CELL_MARGIN_WIDE};

    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");
    // 表の挿入 (2x2)
    s.menu("docx.table.insert-2x2");
    let table = |s: &mut Scenario| {
        s.document()
            .body
            .into_iter()
            .rev()
            .find_map(|b| if let Block::Table(t) = b { Some(t) } else { None })
            .unwrap()
    };
    let t_init = table(&mut s);
    assert_eq!(t_init.rows[0].cells[0].margins, CELL_MARGIN_NORMAL);

    // Initial check state
    assert_eq!(s.menu_state("docx.cell.margins.normal"), Some((true, true)));
    assert_eq!(s.menu_state("docx.cell.margins.narrow"), Some((true, false)));
    assert_eq!(s.menu_state("docx.cell.margins.none"), Some((true, false)));
    assert_eq!(s.menu_state("docx.cell.margins.wide"), Some((true, false)));

    // 1. Change cell margins to narrow (上下 2pt, 左右 3pt)
    s.menu("docx.cell.margins.narrow");
    let t_v1 = table(&mut s);
    assert_eq!(t_v1.rows[0].cells[0].margins, CELL_MARGIN_NARROW);
    assert_eq!(s.menu_state("docx.cell.margins.narrow"), Some((true, true)));
    assert_eq!(s.menu_state("docx.cell.margins.normal"), Some((true, false)));

    // 2. Change cell margins to none (0pt)
    s.menu("docx.cell.margins.none");
    let t_v2 = table(&mut s);
    assert_eq!(t_v2.rows[0].cells[0].margins, CELL_MARGIN_NONE);
    assert_eq!(s.menu_state("docx.cell.margins.none"), Some((true, true)));
    assert_eq!(s.menu_state("docx.cell.margins.narrow"), Some((true, false)));

    // 3. Change cell margins to wide (上下 4pt, 左右 8pt)
    s.menu("docx.cell.margins.wide");
    let t_v3 = table(&mut s);
    assert_eq!(t_v3.rows[0].cells[0].margins, CELL_MARGIN_WIDE);
    assert_eq!(s.menu_state("docx.cell.margins.wide"), Some((true, true)));
    assert_eq!(s.menu_state("docx.cell.margins.none"), Some((true, false)));

    // 4. Undo / Redo
    s.key("cmd-z");
    let t_u1 = table(&mut s);
    assert_eq!(t_u1.rows[0].cells[0].margins, CELL_MARGIN_NONE);

    s.key("cmd-z");
    let t_u2 = table(&mut s);
    assert_eq!(t_u2.rows[0].cells[0].margins, CELL_MARGIN_NARROW);

    s.key("cmd-z");
    let t_u3 = table(&mut s);
    assert_eq!(t_u3.rows[0].cells[0].margins, CELL_MARGIN_NORMAL);

    s.key("cmd-shift-z");
    let t_r1 = table(&mut s);
    assert_eq!(t_r1.rows[0].cells[0].margins, CELL_MARGIN_NARROW);

    // 5. Save and reopen (narrow margins)
    s.save_as("tblfmt008_margins_narrow.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let t_saved = d.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_saved.rows[0].cells[0].margins, CELL_MARGIN_NARROW);

    // 6. Reset to normal margins and save/reopen (default margins / tcMar omitted)
    s.menu("docx.cell.margins.normal");
    let t_norm = table(&mut s);
    assert_eq!(t_norm.rows[0].cells[0].margins, CELL_MARGIN_NORMAL);
    assert_eq!(s.menu_state("docx.cell.margins.normal"), Some((true, true)));

    s.save_as("tblfmt008_margins_normal.docx");
    let saved_norm = s.reopen();
    let d_norm = flow(&saved_norm);
    let t_saved_norm = d_norm.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_saved_norm.rows[0].cells[0].margins, CELL_MARGIN_NORMAL);
}

fn tblfmt001_table_alignment_and_indent() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");
    // 表の挿入 (2x2)
    s.menu("docx.table.insert-2x2");
    let table = |s: &mut Scenario| {
        s.document()
            .body
            .into_iter()
            .rev()
            .find_map(|b| if let Block::Table(t) = b { Some(t) } else { None })
            .unwrap()
    };
    let t_init = table(&mut s);
    assert_eq!(t_init.align, ibis_doc_model::FlowAlign::Left);
    assert_eq!(t_init.indent, 0);

    // Initial check state
    assert_eq!(s.menu_state("docx.table.align.left"), Some((true, true)));
    assert_eq!(s.menu_state("docx.table.align.center"), Some((true, false)));
    assert_eq!(s.menu_state("docx.table.align.right"), Some((true, false)));
    assert_eq!(s.menu_state("docx.table.indent.0"), Some((true, true)));
    assert_eq!(s.menu_state("docx.table.indent.1"), Some((true, false)));
    assert_eq!(s.menu_state("docx.table.indent.2"), Some((true, false)));

    // 1. Change alignment to Center
    s.menu("docx.table.align.center");
    let t_center = table(&mut s);
    assert_eq!(t_center.align, ibis_doc_model::FlowAlign::Center);
    assert_eq!(s.menu_state("docx.table.align.center"), Some((true, true)));
    assert_eq!(s.menu_state("docx.table.align.left"), Some((true, false)));

    // 2. Change alignment to Right
    s.menu("docx.table.align.right");
    let t_right = table(&mut s);
    assert_eq!(t_right.align, ibis_doc_model::FlowAlign::Right);
    assert_eq!(s.menu_state("docx.table.align.right"), Some((true, true)));
    assert_eq!(s.menu_state("docx.table.align.center"), Some((true, false)));

    // 3. Change indent to 2 characters (21 pt = 266_700 emu)
    s.menu("docx.table.indent.2");
    let t_ind2 = table(&mut s);
    assert_eq!(t_ind2.indent, 266_700);
    assert_eq!(s.menu_state("docx.table.indent.2"), Some((true, true)));
    assert_eq!(s.menu_state("docx.table.indent.0"), Some((true, false)));

    // 4. Undo / Redo
    s.key("cmd-z");
    let t_u1 = table(&mut s);
    assert_eq!(t_u1.indent, 0);

    s.key("cmd-z");
    let t_u2 = table(&mut s);
    assert_eq!(t_u2.align, ibis_doc_model::FlowAlign::Center);

    s.key("cmd-z");
    let t_u3 = table(&mut s);
    assert_eq!(t_u3.align, ibis_doc_model::FlowAlign::Left);

    s.key("cmd-shift-z");
    let t_r1 = table(&mut s);
    assert_eq!(t_r1.align, ibis_doc_model::FlowAlign::Center);

    s.key("cmd-shift-z");
    let t_r2 = table(&mut s);
    assert_eq!(t_r2.align, ibis_doc_model::FlowAlign::Right);

    s.key("cmd-shift-z");
    let t_r3 = table(&mut s);
    assert_eq!(t_r3.indent, 266_700);

    // 5. Save and reopen (Right align + 2 characters indent)
    s.save_as("tblfmt001_right_indent.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let t_saved = d.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_saved.align, ibis_doc_model::FlowAlign::Right);
    assert_eq!(t_saved.indent, 266_700);

    // 6. Reset to Left align and 0 indent and save/reopen
    s.menu("docx.table.align.left");
    s.menu("docx.table.indent.0");
    let t_def = table(&mut s);
    assert_eq!(t_def.align, ibis_doc_model::FlowAlign::Left);
    assert_eq!(t_def.indent, 0);
    assert_eq!(s.menu_state("docx.table.align.left"), Some((true, true)));
    assert_eq!(s.menu_state("docx.table.indent.0"), Some((true, true)));

    s.save_as("tblfmt001_default.docx");
    let saved_def = s.reopen();
    let d_def = flow(&saved_def);
    let t_saved_def = d_def.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_saved_def.align, ibis_doc_model::FlowAlign::Left);
    assert_eq!(t_saved_def.indent, 0);
}

fn table007_split_table() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");
    // 表の挿入 (4x4)
    s.menu("docx.table.insert-4x4");
    let tables = |s: &mut Scenario| {
        s.document()
            .body
            .into_iter()
            .filter_map(|b| if let Block::Table(t) = b { Some(t) } else { None })
            .collect::<Vec<_>>()
    };
    let initial_tables = tables(&mut s);
    let initial_count = initial_tables.len();
    assert_eq!(initial_tables.last().unwrap().rows.len(), 4);

    // 表内キャレットで can_split_table が有効
    assert!(s.with(|e, _| e.can_split_table()));

    // 1. row 0 で表分割を実行 → 表の直前に空段落が挿入され、表の行数は4のまま
    s.menu("docx.table.split");
    let after_split0 = tables(&mut s);
    assert_eq!(after_split0.len(), initial_count);
    assert_eq!(after_split0.last().unwrap().rows.len(), 4);

    // 2. Undo で戻る
    s.key("cmd-z");
    let undone = tables(&mut s);
    assert_eq!(undone.len(), initial_count);
    assert_eq!(undone.last().unwrap().rows.len(), 4);

    // 3. 2行目（row index 1）に移動して表分割（メニューから）
    s.key("down");
    s.menu("docx.table.split");
    let after_split1 = tables(&mut s);
    // 表が 2 つに分割されたことを確認
    assert_eq!(after_split1.len(), initial_count + 1);
    let top = &after_split1[after_split1.len() - 2];
    let bottom = &after_split1[after_split1.len() - 1];
    assert_eq!(top.rows.len(), 1, "top table has 1 row");
    assert_eq!(bottom.rows.len(), 3, "bottom table has 3 rows");

    // 4. Undo / Redo
    s.key("cmd-z");
    let undone1 = tables(&mut s);
    assert_eq!(undone1.len(), initial_count);
    assert_eq!(undone1.last().unwrap().rows.len(), 4);

    s.key("cmd-shift-z");
    let redone1 = tables(&mut s);
    assert_eq!(redone1.len(), initial_count + 1);
    assert_eq!(redone1[redone1.len() - 2].rows.len(), 1);
    assert_eq!(redone1[redone1.len() - 1].rows.len(), 3);

    // 5. 保存と再オープン
    s.save_as("table007_split.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let saved_tables: Vec<_> = d.body.iter().filter_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).collect();
    assert_eq!(saved_tables.len(), initial_count + 1);
    assert_eq!(saved_tables[saved_tables.len() - 2].rows.len(), 1);
    assert_eq!(saved_tables[saved_tables.len() - 1].rows.len(), 3);
}

fn page016_column_break() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");
    s.type_text("FirstColumnSecondColumn");
    let p_id = s.with(|e, _| {
        let doc = e.presentation().flow.clone().unwrap();
        let p = doc.body.iter().rev().find_map(|b| if let Block::Paragraph(p) = b { Some(p) } else { None }).unwrap();
        p.id
    });
    // "FirstColumn" (11文字) の後ろにキャレットを置く
    s.click_text(FlowPos::new(p_id, 11));

    // 挿入メニューから「段区切り」を実行
    s.menu("docx.column-break");
    let after_menu = s.document();
    let p = para(&after_menu, p_id);
    assert!(p.runs.iter().any(|r| matches!(r.kind, FlowRunKind::ColumnBreak)));

    // Undo で段区切りが削除される
    s.key("cmd-z");
    let doc_undone = s.document();
    let p_undone = para(&doc_undone, p_id);
    assert!(!p_undone.runs.iter().any(|r| matches!(r.kind, FlowRunKind::ColumnBreak)));

    // Redo で段区切りが復元される
    s.key("cmd-shift-z");
    let doc_redone = s.document();
    let p_redone = para(&doc_redone, p_id);
    assert!(p_redone.runs.iter().any(|r| matches!(r.kind, FlowRunKind::ColumnBreak)));

    // 保存して開き直しても FlowRunKind::ColumnBreak (w:br w:type="column") が保持される
    s.save_as("page016_column_break.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let p_saved = body(d).into_iter().find(|p| p.text().contains("FirstColumn")).unwrap();
    assert!(p_saved.runs.iter().any(|r| matches!(r.kind, FlowRunKind::ColumnBreak)));
}

fn tblfmt005_table_autofit() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");
    // 表の挿入 (2x2)
    s.menu("docx.table.insert-2x2");
    let table = |s: &mut Scenario| {
        s.document()
            .body
            .into_iter()
            .rev()
            .find_map(|b| if let Block::Table(t) = b { Some(t) } else { None })
            .unwrap()
    };
    let t_init = table(&mut s);
    assert_eq!(t_init.rows.len(), 2);
    assert_eq!(t_init.columns.len(), 2);
    let p1_id = match &t_init.rows[0].cells[0].blocks[0] {
        Block::Paragraph(p) => p.id,
        _ => panic!(),
    };
    let p2_id = match &t_init.rows[0].cells[1].blocks[0] {
        Block::Paragraph(p) => p.id,
        _ => panic!(),
    };

    // セル 1 に短いテキスト、セル 2 に長いテキストを入力
    s.click_text(FlowPos::new(p1_id, 0));
    s.type_text("A");
    s.click_text(FlowPos::new(p2_id, 0));
    s.type_text("VeryLongTextContentHere");

    let doc_typed = s.document();

    // 1. 文字列の幅に自動調整 (AutoFitContents)
    s.menu("docx.table.autofit-contents");
    let t_fit = table(&mut s);
    assert!(t_fit.columns[1] > t_fit.columns[0], "longer text produces wider column");
    assert!(t_fit.autofit.is_some());

    // Undo で入力直後の状態に復元
    s.key("cmd-z");
    assert_eq!(s.document(), doc_typed);

    // Redo で自動調整が再適用
    s.key("cmd-shift-z");
    let t_fit_redo = table(&mut s);
    assert!(t_fit_redo.columns[1] > t_fit_redo.columns[0]);

    // 2. ウィンドウサイズに自動調整 (AutoFitWindow)
    s.menu("docx.table.autofit-window");
    let t_win = table(&mut s);
    let total_w: i64 = t_win.columns.iter().sum();
    let doc = s.document();
    let avail = doc.page.size.width - doc.page.left - doc.page.right;
    assert_eq!(total_w, avail);
    assert_eq!(t_win.autofit.as_ref().unwrap().width, ibis_doc_model::PreferredWidth::Percent(5000));

    // 3. 列の幅を固定 (FixedColumns)
    s.menu("docx.table.autofit-fixed");
    let t_fixed = table(&mut s);
    assert!(t_fixed.autofit.is_none());
    assert_eq!(t_fixed.columns.iter().sum::<i64>(), avail);

    // 保存して開き直しても正常に保持される
    s.save_as("tblfmt005_autofit.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let t_saved = d.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_saved.columns.iter().sum::<i64>(), avail);
}

/// DOCX-PAGE-020: ページの色 (Page Color)
/// メニュー操作（「薄い黄」の設定、「色なし」による解除）、Undo/Redo、
/// docx 保存・再オープンによる `w:background` および `displayBackgroundShape` の保持を検証する。
fn page020_page_color() {
    let mut s = Scenario::open(REPORT);

    // 初期状態は page_color: None
    assert!(s.document().page_color.is_none());

    // 1. ページの色メニューから「薄い黄」（#FFF2CC）を選択
    s.menu("docx.page.color.light-yellow");
    let yellow = ibis_doc_model::Rgb(0xFFF2CC);
    assert_eq!(s.document().page_color, Some(yellow));

    // スクリーンショット撮影
    s.screenshot("page020-page-color-yellow.png");

    // 2. Undo で元の None に戻る
    s.key("cmd-z");
    assert!(s.document().page_color.is_none());

    // 3. Redo で再び「薄い黄」が適用される
    s.key("cmd-shift-z");
    assert_eq!(s.document().page_color, Some(yellow));

    // 4. docx 保存して再オープンし、page_color が維持されていることを確認
    s.save_as("page020-color.docx");
    let reloaded = s.reopen();
    assert_eq!(flow(&reloaded).page_color, Some(yellow));

    // 5. 別の色（「薄い青」#DDEBF7）に変更
    s.menu("docx.page.color.light-blue");
    let blue = ibis_doc_model::Rgb(0xDDEBF7);
    assert_eq!(s.document().page_color, Some(blue));

    // 6. 「色なし」（docx.page.color.none）を選択してクリア
    s.menu("docx.page.color.none");
    assert!(s.document().page_color.is_none());

    // 7. 保存して再オープンし、page_color が None のまま保持されることを確認
    s.save_as("page020-none.docx");
    let reloaded_none = s.reopen();
    assert!(flow(&reloaded_none).page_color.is_none());
}

/// DOCX-VIEW-001/007: the print layout stacks the pages vertically; scrolling the wheel moves on through the pages and back.
fn view007_scroll_pages_vertically() {
    let mut s = Scenario::open(REPORT);
    let count = s.with(|e, _| e.presentation().slides.len());
    assert!(count >= 2, "the report has several pages ({count})");
    assert_eq!(s.with(|e, _| e.visible_page()), 0, "opens at the first page");
    for _ in 0..40 { s.wheel((600.0, 500.0), -400.0); }
    let down = s.with(|e, _| e.visible_page());
    assert!(down >= 1 && down < count, "scrolled down to page index {down}");
    let status = s.status_texts().join(" ");
    assert!(status.contains(&format!("{}", down + 1)), "the status bar shows the page: {status}");
    for _ in 0..80 { s.wheel((600.0, 500.0), 400.0); }
    assert_eq!(s.with(|e, _| e.visible_page()), 0, "scrolled back to the first page");
}

/// DOCX-FLOAT-003/004: a picture's wrap switched to tight, through and top-and-bottom from the menu (one step of undo each),
/// kept in the file (`wp:wrapTight`, `wp:wrapThrough`, `wp:wrapTopAndBottom`).
fn float003_wrap_tight_through_top_bottom() {
    use ibis_doc_model::PictureWrapType as W;
    let mut s = Scenario::open(REPORT);
    let (id, offset) = s.with(|e, _| {
        for p in body(flow(e.presentation())) {
            let mut offset = 0;
            for r in &p.runs {
                if let FlowRunKind::Picture { .. } = r.kind {
                    return (p.id, offset);
                }
                offset += r.len();
            }
        }
        panic!("a picture in REPORT");
    });
    s.click_text(FlowPos::new(id, offset));
    for (menu, kind, xml) in [("docx.picture.wrap.tight", W::Tight, "wrapTight"), ("docx.picture.wrap.through", W::Through, "wrapThrough"), ("docx.picture.wrap.top-and-bottom", W::TopAndBottom, "wrapTopAndBottom")] {
        let before = s.document();
        s.menu(menu);
        assert_eq!(s.with(|e, _| e.picture_wrap_at_caret()), Some(kind), "{menu}");
        assert_eq!(s.menu_state(menu), Some((true, true)), "{menu} is checked");
        s.key("cmd-z");
        assert_eq!(s.document(), before, "{menu}: one undo");
        s.key("cmd-shift-z");
        let path = s.save_as(&format!("float003-{xml}.docx"));
        let xml_text = ibis_pptx::test_files::part_text(&std::fs::read(&path).unwrap(), "word/document.xml").unwrap();
        assert!(xml_text.contains(&format!("<wp:{xml}")), "{menu} is saved as wp:{xml}");
        s.menu("docx.picture.wrap.inline");
    }
}

/// DOCX-FCODE-021/033/034/044/046/050/055: the document-information fields (FILENAME, KEYWORDS, LASTSAVEDBY, NUMCHARS, NUMWORDS,
/// PRINTDATE, REVNUM) inserted at the caret show their value, and are kept as fields in the saved file.
fn fcode_document_info_fields() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");
    let codes = ["FILENAME", "KEYWORDS", "LASTSAVEDBY", "NUMCHARS", "NUMWORDS", "PRINTDATE", "REVNUM"];
    for code in codes {
        s.update(|e, _, cx| {
            let doc = e.flow().unwrap();
            let range = e.ordered_selection();
            let (cmds, new_pos) = ibis_doc_model::flow_command::insert_field_at_range(doc, range, code, false).unwrap();
            if e.run_flow(cmds, cx) {
                e.set_caret(new_pos, false, cx);
            }
        });
        s.type_text(" ");
    }
    let fields = |doc: &FlowDocument| -> Vec<(String, String)> {
        body(doc).iter().flat_map(|p| p.runs.iter()).filter_map(|r| if let FlowRunKind::Field { instruction, shown } = &r.kind { Some((instruction.clone(), shown.clone())) } else { None }).collect()
    };
    // The values come with the update of the fields (F9).
    s.update(|e, _, cx| {
        let doc = e.flow().unwrap();
        let cmds = ibis_doc_model::updated_fields_in_range(doc, None, None);
        for cmd in cmds {
            e.execute(vec![ibis_doc_model::Command::Flow(cmd)], cx);
        }
    });
    let shown = fields(&s.document());
    for code in codes {
        assert!(shown.iter().any(|(i, _)| i.trim() == code), "{code} is a field: {shown:?}");
    }
    let value = |code: &str| shown.iter().find(|(i, _)| i.trim() == code).map(|(_, v)| v.clone()).unwrap();
    assert!(!value("FILENAME").is_empty(), "the file's name");
    assert!(value("NUMWORDS").trim().parse::<u32>().is_ok_and(|n| n > 0), "NUMWORDS: {}", value("NUMWORDS"));
    assert!(value("NUMCHARS").trim().parse::<u32>().is_ok_and(|n| n > 0), "NUMCHARS: {}", value("NUMCHARS"));
    let path = s.save_as("fcode-info.docx");
    let xml = ibis_pptx::test_files::part_text(&std::fs::read(&path).unwrap(), "word/document.xml").unwrap();
    for code in codes {
        assert!(xml.contains(&format!(" {code} ")) || xml.contains(&format!(" {code}\"")) || xml.contains(&format!("{code} \\")) || xml.contains(&format!(">{code}<")) || xml.contains(&format!(" {code}<")), "{code} is kept as a field in the file");
    }
    let saved = s.reopen();
    let text: String = body(flow(&saved)).iter().map(|p| p.text()).collect::<Vec<_>>().join("\n");
    assert!(text.contains(value("NUMWORDS").trim()) && text.contains(value("NUMCHARS").trim()), "the values are in the file's text: {text}");
}

/// Word's Mac shortcuts that the menus show or that people type: ⌘⇧D (double underline), ⌘⇧W (words only), ⌘⌥F (footnote), ⌘⌥E
/// (endnote) and ⌘⇧L (bullets); each toggles back or makes one step of undo.
fn edit016_word_shortcuts() {
    use ibis_doc_model::UnderlineStyle as U;
    let mut s = Scenario::open(REPORT);
    let (index, id) = {
        let doc = s.document();
        let (i, p) = body(&doc).into_iter().enumerate().find(|(_, p)| p.len() >= 12 && !p.text().contains('\u{fffc}') && p.list.is_none() && p.runs.iter().all(|r| !r.style.underline)).expect("a plain paragraph");
        (i, p.id)
    };
    s.click_text(FlowPos::new(id, 2));
    for _ in 0..4 { s.key("shift-right"); }
    let style = |s: &mut Scenario| para(&s.document(), id).runs.iter().find(|r| r.style.underline).map(|r| r.style.underline_style);
    assert_eq!(style(&mut s), None);
    s.key("cmd-shift-d");
    assert_eq!(style(&mut s), Some(U::Double), "⌘⇧D: double underline");
    s.key("cmd-shift-d");
    assert_eq!(style(&mut s), None, "⌘⇧D again takes it off");
    s.key("cmd-shift-w");
    assert_eq!(style(&mut s), Some(U::Words), "⌘⇧W: words only");
    s.key("cmd-shift-w");
    assert_eq!(style(&mut s), None);
    s.click_text(FlowPos::new(id, 6));
    let notes = |s: &mut Scenario| (s.document().footnotes.len(), s.document().endnotes.len());
    s.key("cmd-alt-f");
    assert_eq!(notes(&mut s), (1, 0), "⌘⌥F: a footnote");
    s.type_text("fn");
    s.click_text(FlowPos::new(id, 9));
    s.key("cmd-alt-e");
    assert_eq!(notes(&mut s), (1, 1), "⌘⌥E: an endnote");
    s.type_text("en");
    s.click_text(FlowPos::new(id, 0));
    assert!(s.with(|e, _| body(flow(e.presentation()))[index].list.is_none()));
    s.key("cmd-shift-l");
    assert!(s.with(|e, _| body(flow(e.presentation()))[index].list.is_some()), "⌘⇧L: a bullet");
    s.key("cmd-shift-l");
    assert!(s.with(|e, _| body(flow(e.presentation()))[index].list.is_none()), "⌘⇧L again takes it off");
}

/// DOCX-EDIT-007: copy leaves the text, cut removes it (one step of undo); both put it on the clipboard and paste puts it back; saved and read back.
fn edit007_cut_and_copy() {
    let mut s = Scenario::open(REPORT);
    let (index, id, text) = text_paragraph(&mut s, 8);
    let first: String = text.chars().take(3).collect();
    s.click_text(FlowPos::new(id, 0));
    for _ in 0..3 { s.key("shift-right"); }
    s.key("cmd-c");
    assert_eq!(s.paragraph(index).1, text, "copy leaves the text");
    assert_eq!(s.update(|_, _, cx| cx.read_from_clipboard().and_then(|c| c.text())).as_deref(), Some(first.as_str()));
    let before = s.document();
    s.key("cmd-x");
    assert_eq!(s.paragraph(index).1, text.chars().skip(3).collect::<String>(), "cut removes it");
    s.key("cmd-z");
    assert_eq!(s.document(), before, "one undo restores the text");
    s.key("cmd-shift-z");
    s.key("cmd-v");
    assert_eq!(s.paragraph(index).1, text, "paste puts it back");
    s.save_as("edit007.docx");
    let saved = s.reopen();
    assert_eq!(body(flow(&saved))[index].text(), text);
}

/// DOCX-EDIT-010: paste as plain text (⇧⌘V) takes the destination's character format, not the copied one.
fn edit010_paste_plain() {
    let mut s = Scenario::open(REPORT);
    let (index, id, text) = text_paragraph(&mut s, 8);
    let first: String = text.chars().take(3).collect();
    let len = text.chars().count();
    s.click_text(FlowPos::new(id, 0));
    for _ in 0..3 { s.key("shift-right"); }
    s.key("cmd-b");
    s.key("cmd-c");
    assert!(para(&s.document(), id).runs[0].style.bold, "the copied text is bold");
    let tail_bold = |s: &mut Scenario| para(&s.document(), id).runs.last().unwrap().style.bold;
    s.click_text(FlowPos::new(id, len));
    assert!(!tail_bold(&mut s), "the end of the paragraph is not bold");
    s.key("cmd-shift-v");
    assert_eq!(s.paragraph(index).1, format!("{}{}", text, first));
    assert!(!tail_bold(&mut s), "plain paste: the pasted text is not bold");
    s.key("cmd-z");
    assert_eq!(s.paragraph(index).1, text, "one undo removes the pasted text");
    s.key("cmd-v");
    assert!(tail_bold(&mut s), "ordinary paste keeps the copied format (bold)");
}

/// DOCX-LIST-006/012: Tab at the start of a list item makes it a deeper level, Shift+Tab a shallower one; kept in the file.
fn list012_level_with_tab() {
    let mut s = Scenario::open(REPORT);
    let (index, id, _) = text_paragraph(&mut s, 10);
    s.click_text(FlowPos::new(id, 0));
    s.toolbar("bullets");
    let level = |s: &mut Scenario| s.with(|e, _| body(flow(e.presentation()))[index].list.map(|l| l.level));
    assert_eq!(level(&mut s), Some(0));
    s.key("tab");
    assert_eq!(level(&mut s), Some(1), "Tab: one level deeper");
    s.key("tab");
    assert_eq!(level(&mut s), Some(2));
    s.key("shift-tab");
    assert_eq!(level(&mut s), Some(1), "Shift+Tab: one level up");
    s.key("cmd-z");
    assert_eq!(level(&mut s), Some(2), "undo");
    s.key("cmd-shift-z");
    s.save_as("list012.docx");
    let saved = s.reopen();
    assert_eq!(body(flow(&saved))[index].list.map(|l| l.level), Some(1));
}

/// DOCX-EDIT-009: 貼付先の書式へ統合 (Paste and Match Style / Match Destination Formatting)
/// コピー元のインライン強調（太字・斜体）を維持しつつ、貼り付け先（宛先）のフォント・サイズ・文字色に
/// 統合して挿入されること、Undo/Redo、保存・再オープンを検証する。
fn edit009_paste_match_format() {
    let mut source = Scenario::open(REPORT);
    let (_, id, text) = text_paragraph(&mut source, 8);
    source.click_text(FlowPos::new(id, 0));
    for _ in 0..3 { source.key("shift-right"); }
    // コピー元テキストに太字・斜体・赤色を適用
    source.key("cmd-b");
    source.key("cmd-i");
    source.toolbar_menu("text-color", "docx.color.red");
    let copied_text: String = text.chars().take(3).collect();
    let source_style = para(&source.document(), id).runs[0].style.clone();
    assert!(source_style.bold);
    assert!(source_style.italic);
    assert_eq!(source_style.color, ibis_doc_model::Rgb(0xff0000));
    source.key("cmd-c");
    let clipboard = source.update(|_, _, cx| cx.read_from_clipboard().unwrap());
    drop(source);

    // 貼り付け先ドキュメントを開く
    let mut s = Scenario::open(STATEMENT);
    s.update(|_, _, cx| cx.write_to_clipboard(clipboard));
    let (_, dest_id, _) = text_paragraph(&mut s, 8);
    s.click_text(FlowPos::new(dest_id, 0));
    let dest_style = para(&s.document(), dest_id).runs[0].style.clone();
    let before = s.document();

    // 1. メニュー「編集 > 貼り付け先の書式に合わせて貼り付け」を実行
    s.menu("edit.paste-match");
    let after = s.document();
    let p = para(&after, dest_id);
    assert!(p.text().starts_with(&copied_text));
    let pasted_run = &p.runs[0];

    // 貼り付け先書式への統合の検証：
    // - インライン強調（bold, italic）はコピー元から維持
    assert!(pasted_run.style.bold, "bold is preserved from source");
    assert!(pasted_run.style.italic, "italic is preserved from source");
    // - 文字色は貼り付け先（dest_style）に統合（赤色にはならず、dest_style の色になる）
    assert_eq!(pasted_run.style.color, dest_style.color, "color is matched to destination");

    // 2. Undo で元の状態に戻る
    s.key("cmd-z");
    assert_eq!(s.document(), before);

    // 3. Redo で再適用
    s.key("cmd-shift-z");
    assert_eq!(s.document(), after);

    // 4. 保存して開き直しても保持される
    s.save_as("edit009-paste-match.docx");
    let saved = s.reopen();
    let p_saved = body(flow(&saved)).into_iter().find(|p| p.text() == para(&after, dest_id).text()).unwrap();
    assert!(p_saved.runs[0].style.bold);
    assert_eq!(p_saved.runs[0].style.color, dest_style.color);
}

/// DOCX-HEADER-010: ページ番号の開始値（任意の開始番号の設定、前のセクションから継続、メニュー・UI連動、Undo/Redo、保存・再オープン）
fn header010_page_number_start() {
    let mut s = Scenario::open(REPORT);

    // 1. 初期状態：開始番号は 1（継続モード）
    assert_eq!(s.document().page.first_page, 1);
    assert!(!s.document().restart_numbering);
    assert_eq!(s.menu_state("docx.section.page-start-continue"), Some((true, true)));
    assert_eq!(s.menu_state("docx.section.page-start-5"), Some((true, false)));

    // 2. メニューから開始番号 5 を選択
    s.menu("docx.section.page-start-5");
    assert_eq!(s.document().page.first_page, 5);
    assert!(s.document().restart_numbering);
    assert_eq!(s.menu_state("docx.section.page-start-continue"), Some((true, false)));
    assert_eq!(s.menu_state("docx.section.page-start-5"), Some((true, true)));

    // 3. フッターにページ番号を挿入
    s.menu("docx.page-number");
    assert!(!s.document().footer.is_empty());

    // 4. Undo でページ番号挿入を取り消し、さらに Undo で開始番号設定を取り消し
    s.key("cmd-z"); // Undo ページ番号挿入
    s.key("cmd-z"); // Undo 開始番号設定
    assert_eq!(s.document().page.first_page, 1);
    assert!(!s.document().restart_numbering);
    assert_eq!(s.menu_state("docx.section.page-start-continue"), Some((true, true)));

    // 5. Redo で開始番号 5 を再適用
    s.key("cmd-shift-z");
    assert_eq!(s.document().page.first_page, 5);
    assert!(s.document().restart_numbering);

    // 6. 保存して再オープンし、w:pgNumType w:start="5" の保持を検証
    s.save_as("header010-page-start.docx");
    let saved = s.reopen();
    let doc = flow(&saved);
    assert_eq!(doc.page.first_page, 5);
    assert!(doc.restart_numbering);

    // 7. 「前のセクションから継続」メニューで解除できることを検証
    s.menu("docx.section.page-start-continue");
    assert_eq!(s.document().page.first_page, 1);
    assert!(!s.document().restart_numbering);
    assert_eq!(s.menu_state("docx.section.page-start-continue"), Some((true, true)));
}

/// DOCX-HEADER-008: ページ番号の位置（ヘッダー上部/フッター下部、左揃え/中央揃え/右揃え、現在の位置への挿入、Undo/Redo、保存・再オープン）
fn header008_page_number_position() {
    let mut s = Scenario::open(REPORT);

    // 1. ヘッダー上部・右揃えにページ番号を挿入
    s.menu("docx.page-number.top-right");
    let doc = s.document();
    let header_paras: Vec<&FlowParagraph> = doc.header.iter().filter_map(|b| if let Block::Paragraph(p) = b { Some(p) } else { None }).collect();
    assert!(!header_paras.is_empty(), "header has paragraph");
    assert!(header_paras.iter().any(|p| p.runs.iter().any(|r| matches!(r.kind, FlowRunKind::PageNumber)) && p.align == FlowAlign::Right));

    // 2. Undo でヘッダーのページ番号挿入が取り消されることを検証
    s.key("cmd-z");
    let doc = s.document();
    assert!(doc.header.is_empty() || doc.header.iter().all(|b| matches!(b, Block::Paragraph(p) if !p.runs.iter().any(|r| matches!(r.kind, FlowRunKind::PageNumber)))));

    // 3. フッター下部・左揃えにページ番号を挿入
    s.menu("docx.page-number.bottom-left");
    let doc = s.document();
    let footer_paras: Vec<&FlowParagraph> = doc.footer.iter().filter_map(|b| if let Block::Paragraph(p) = b { Some(p) } else { None }).collect();
    assert!(!footer_paras.is_empty(), "footer has paragraph");
    assert!(footer_paras.iter().any(|p| p.runs.iter().any(|r| matches!(r.kind, FlowRunKind::PageNumber)) && p.align == FlowAlign::Left));

    // 4. 本文のキャレット位置にページ番号を挿入
    let (_, id, _) = text_paragraph(&mut s, 4);
    s.click_text(FlowPos::new(id, 2));
    s.menu("docx.page-number.current");
    let doc = s.document();
    let p_after = para(&doc, id);
    assert!(p_after.runs.iter().any(|r| matches!(r.kind, FlowRunKind::PageNumber)));

    // 5. 保存して再オープンし、フッター左揃えおよび本文のページ番号が保持されていることを検証
    s.save_as("header008-page-pos.docx");
    let saved = s.reopen();
    let doc = flow(&saved);
    assert!(doc.footer.iter().any(|b| matches!(b, Block::Paragraph(p) if p.runs.iter().any(|r| matches!(r.kind, FlowRunKind::PageNumber)) && p.align == FlowAlign::Left)));
}

/// DOCX-VIEW-016: 編集記号の表示（¶ボタン、すべての表示マーク）
/// メニュー、ショートカットキー（cmd-8, cmd-shift-8）によるトグル切替、チェック状態追従、
/// タブ・スペース・全角スペース・手動改行・段落記号（¶）を含む画面描画を検証。
fn view016_formatting_marks() {
    let mut s = Scenario::open(REPORT);

    // 1. 初期状態：formatting_marks_open は false、メニュー docx.formatting-marks はチェックなし
    assert!(!s.with(|e, _| e.formatting_marks_open), "formatting marks should be hidden initially");
    assert_eq!(s.menu_state("docx.formatting-marks"), Some((true, false)), "docx.formatting-marks menu item should be enabled and unchecked");

    // 2. メニューをクリックして表示にする
    s.menu("docx.formatting-marks");
    assert!(s.with(|e, _| e.formatting_marks_open), "formatting marks should be visible after menu click");
    assert_eq!(s.menu_state("docx.formatting-marks"), Some((true, true)), "docx.formatting-marks menu item should be enabled and checked");

    // 3. 再度メニューをクリックして非表示に戻す
    s.menu("docx.formatting-marks");
    assert!(!s.with(|e, _| e.formatting_marks_open), "formatting marks should be hidden again after second click");
    assert_eq!(s.menu_state("docx.formatting-marks"), Some((true, false)), "docx.formatting-marks menu item should be enabled and unchecked again");

    // 4. ショートカットキー（cmd-8）でトグル切替
    s.key("cmd-8");
    assert!(s.with(|e, _| e.formatting_marks_open), "formatting marks should be visible after shortcut cmd-8");
    assert_eq!(s.menu_state("docx.formatting-marks"), Some((true, true)));

    s.key("cmd-8");
    assert!(!s.with(|e, _| e.formatting_marks_open), "formatting marks should be hidden after second shortcut cmd-8");
    assert_eq!(s.menu_state("docx.formatting-marks"), Some((true, false)));

    // 5. ショートカットキー（cmd-shift-8）でトグル切替
    s.key("cmd-shift-8");
    assert!(s.with(|e, _| e.formatting_marks_open), "formatting marks should be visible after shortcut cmd-shift-8");
    assert_eq!(s.menu_state("docx.formatting-marks"), Some((true, true)));

    // 6. テキスト入力（タブ・スペース・全角スペース・手動改行）を行い描画検証
    s.key("cmd-down");
    s.key("enter");
    s.type_text("Formatting marks test: Hello World!\tTabbed\u{3000}FullWidthSpace");
    s.key("shift-enter");
    s.type_text("Manual Line Break Line");
    s.key("enter");

    // 7. スクリーンショット撮影（クラッシュせず描画されることを確認）
    s.screenshot("docx-view016-formatting-marks");

    // 8. 再度トグルして非表示にし、スクリーンショット撮影
    s.key("cmd-8");
    assert!(!s.with(|e, _| e.formatting_marks_open));
    assert_eq!(s.menu_state("docx.formatting-marks"), Some((true, false)));
    s.screenshot("docx-view016-formatting-marks-off");

    // 9. ツールバーの「¶」ボタンの on 状態連動を検証
    let tool_on = |s: &mut Scenario| {
        s.with(|e, _| {
            crate::docx::toolbar::toolbar_right(e)
                .into_iter()
                .find_map(|it| if let crate::shell::chrome::ToolItem::Button(b) = it && b.id == "formatting-marks" { Some(b.on) } else { None })
        })
    };
    assert_eq!(tool_on(&mut s), Some(false), "toolbar ¶ button should be off initially");
    s.key("cmd-8");
    assert_eq!(tool_on(&mut s), Some(true), "toolbar ¶ button should be on when active");
    s.key("cmd-8");
    assert_eq!(tool_on(&mut s), Some(false), "toolbar ¶ button should be off again");
}

/// DOCX-IMAGE-008: 画像の枠線（Picture Border: 太さ・色・線種・なし）の
/// 設定、UI/メニューチェック追従、Undo/Redo、OOXML (pic:spPr/a:ln) 保存と再読込保持の検証。
fn image008_picture_border() {
    let mut s = Scenario::open(REPORT);

    // 1. REPORT ドキュメント内の画像の位置を探索
    let (id, offset, _media) = s.with(|e, _| {
        for p in body(flow(e.presentation())) {
            let mut offset = 0;
            for r in &p.runs {
                if let FlowRunKind::Picture { media, .. } = r.kind {
                    return (p.id, offset, media);
                }
                offset += r.len();
            }
        }
        panic!("a picture in REPORT");
    });

    // 2. キャレットを画像位置に移動し、初期状態を検証
    s.click_text(FlowPos::new(id, offset));
    assert_eq!(s.menu_state("docx.picture.border.none"), Some((true, true)), "border none should be checked initially");
    assert!(s.with(|e, _| e.picture_stroke_at_caret()).is_none(), "picture should have no stroke initially");

    // 3. 枠線の太さを 1.5 pt (19,050 EMU) に設定
    s.menu("docx.picture.border.w150");
    assert_eq!(s.menu_state("docx.picture.border.none"), Some((true, false)), "border none should be unchecked");
    assert_eq!(s.menu_state("docx.picture.border.w150"), Some((true, true)), "border w150 should be checked");
    let stroke = s.with(|e, _| e.picture_stroke_at_caret().expect("stroke after setting width"));
    assert_eq!(stroke.width, 19_050, "width should be 1.5 pt");
    assert_eq!(stroke.color.rgb.0, 0x000000, "default color should be black");

    // 4. 枠線の色を赤 (0xD32F2F) に設定
    s.menu("docx.picture.border.color.red");
    assert_eq!(s.menu_state("docx.picture.border.color.red"), Some((true, true)), "border color red should be checked");
    let stroke = s.with(|e, _| e.picture_stroke_at_caret().expect("stroke after setting color"));
    assert_eq!(stroke.color.rgb.0, 0xD32F2F, "color should be red");
    assert_eq!(stroke.width, 19_050, "width should remain 1.5 pt");

    // 5. 枠線の線種を破線 (Dash) に設定
    s.menu("docx.picture.border.dash.dash");
    assert_eq!(s.menu_state("docx.picture.border.dash.dash"), Some((true, true)), "border dash should be checked");
    let stroke = s.with(|e, _| e.picture_stroke_at_caret().expect("stroke after setting dash"));
    assert_eq!(stroke.dash, ibis_doc_model::LineDash::Dash, "dash should be Dash");
    assert!(stroke.dashed, "dashed flag should be true");

    // 6. Undo / Redo の検証
    s.key("cmd-z");
    let stroke_after_undo = s.with(|e, _| e.picture_stroke_at_caret().expect("stroke after undo"));
    assert_eq!(stroke_after_undo.dash, ibis_doc_model::LineDash::Solid, "dash should be restored to Solid after undo");
    s.key("cmd-shift-z");
    let stroke_after_redo = s.with(|e, _| e.picture_stroke_at_caret().expect("stroke after redo"));
    assert_eq!(stroke_after_redo.dash, ibis_doc_model::LineDash::Dash, "dash should be re-applied after redo");

    // 7. スクリーンショット撮影
    s.screenshot("docx-image008-picture-border");

    // 8. ファイル保存 (save_as) と再読込 (reopen) による OOXML (pic:spPr/a:ln) 保持検証
    s.save_as("image008-picture-border.docx");
    let saved = s.reopen();
    let saved_pic_stroke = {
        let mut found = None;
        for p in body(flow(&saved)) {
            for r in &p.runs {
                if let FlowRunKind::Picture { look, .. } = &r.kind {
                    if let Some(s) = &look.stroke {
                        found = Some(s.clone());
                    }
                }
            }
        }
        found.expect("saved picture should have stroke")
    };
    assert_eq!(saved_pic_stroke.width, 19_050, "saved stroke width should be 1.5 pt");
    assert_eq!(saved_pic_stroke.color.rgb.0, 0xD32F2F, "saved stroke color should be red");
    assert_eq!(saved_pic_stroke.dash, ibis_doc_model::LineDash::Dash, "saved stroke dash should be Dash");

    // 9. 枠線なし（クリア）の検証
    s.click_text(FlowPos::new(id, offset));
    s.menu("docx.picture.border.none");
    assert_eq!(s.menu_state("docx.picture.border.none"), Some((true, true)), "border none should be checked after clear");
    assert!(s.with(|e, _| e.picture_stroke_at_caret()).is_none(), "picture should have no stroke after clear");

    // 10. 枠線なし状態での保存と再読込
    s.save_as("image008-picture-border-cleared.docx");
    let saved_cleared = s.reopen();
    let has_stroke = body(flow(&saved_cleared)).iter().any(|p| {
        p.runs.iter().any(|r| {
            if let FlowRunKind::Picture { look, .. } = &r.kind {
                look.stroke.is_some()
            } else {
                false
            }
        })
    });
    assert!(!has_stroke, "cleared picture should have no stroke after reopen");
}

fn tblfmt009_cell_spacing() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");
    // 表の挿入 (2x2)
    s.menu("docx.table.insert-2x2");
    let table = |s: &mut Scenario| {
        s.document()
            .body
            .into_iter()
            .rev()
            .find_map(|b| if let Block::Table(t) = b { Some(t) } else { None })
            .unwrap()
    };
    let t_init = table(&mut s);
    assert_eq!(t_init.cell_spacing, None);

    // 初期状態のメニューチェック確認
    assert_eq!(s.menu_state("docx.table.cell-spacing.none"), Some((true, true)));
    assert_eq!(s.menu_state("docx.table.cell-spacing.1pt"), Some((true, false)));
    assert_eq!(s.menu_state("docx.table.cell-spacing.2pt"), Some((true, false)));

    // 1. セル間隔を 2 pt (25_400 EMU) に設定
    s.menu("docx.table.cell-spacing.2pt");
    let t_2pt = table(&mut s);
    assert_eq!(t_2pt.cell_spacing, Some(25_400));
    assert_eq!(s.menu_state("docx.table.cell-spacing.2pt"), Some((true, true)));
    assert_eq!(s.menu_state("docx.table.cell-spacing.none"), Some((true, false)));

    // 2. セル間隔を 4 pt (50_800 EMU) に変更
    s.menu("docx.table.cell-spacing.4pt");
    let t_4pt = table(&mut s);
    assert_eq!(t_4pt.cell_spacing, Some(50_800));
    assert_eq!(s.menu_state("docx.table.cell-spacing.4pt"), Some((true, true)));

    // 3. Undo / Redo
    s.key("cmd-z");
    let t_u1 = table(&mut s);
    assert_eq!(t_u1.cell_spacing, Some(25_400));

    s.key("cmd-z");
    let t_u2 = table(&mut s);
    assert_eq!(t_u2.cell_spacing, None);

    s.key("cmd-shift-z");
    let t_r1 = table(&mut s);
    assert_eq!(t_r1.cell_spacing, Some(25_400));

    // 4. 保存と再読込（2 pt セル間隔の復元検証）
    s.save_as("tblfmt009_cell_spacing_2pt.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let t_saved = d.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_saved.cell_spacing, Some(25_400));

    // 5. 「なし」（None）にリセットして保存・再読込
    s.menu("docx.table.cell-spacing.none");
    let t_none = table(&mut s);
    assert_eq!(t_none.cell_spacing, None);
    assert_eq!(s.menu_state("docx.table.cell-spacing.none"), Some((true, true)));

    s.save_as("tblfmt009_cell_spacing_none.docx");
    let saved_none = s.reopen();
    let d_none = flow(&saved_none);
    let t_saved_none = d_none.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_saved_none.cell_spacing, None);
}

fn tblfmt019_cell_no_wrap() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");
    // 表の挿入 (2x2)
    s.menu("docx.table.insert-2x2");
    let cell_00 = |s: &mut Scenario| {
        let t = s.document()
            .body
            .into_iter()
            .rev()
            .find_map(|b| if let Block::Table(t) = b { Some(t) } else { None })
            .unwrap();
        t.rows[0].cells[0].clone()
    };
    let c_init = cell_00(&mut s);
    assert_eq!(c_init.no_wrap, false);

    // 初期状態のメニューチェック確認（折り返し有効 = checked true）
    assert_eq!(s.menu_state("docx.cell.wrap-text"), Some((true, true)));

    // 1. 折り返しをトグル（no_wrap = true、チェックが外れる）
    s.menu("docx.cell.wrap-text");
    let c_nowrap = cell_00(&mut s);
    assert_eq!(c_nowrap.no_wrap, true);
    assert_eq!(s.menu_state("docx.cell.wrap-text"), Some((true, false)));

    // 2. Undo / Redo
    s.key("cmd-z");
    let c_undo = cell_00(&mut s);
    assert_eq!(c_undo.no_wrap, false);
    assert_eq!(s.menu_state("docx.cell.wrap-text"), Some((true, true)));

    s.key("cmd-shift-z");
    let c_redo = cell_00(&mut s);
    assert_eq!(c_redo.no_wrap, true);
    assert_eq!(s.menu_state("docx.cell.wrap-text"), Some((true, false)));

    // 3. 保存と再読込（w:noWrap の復元検証）
    s.save_as("tblfmt019_cell_no_wrap.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let t_saved = d.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_saved.rows[0].cells[0].no_wrap, true);

    // 4. 再度トグルして折り返しを有効化（no_wrap = false、チェック戻る）
    s.menu("docx.cell.wrap-text");
    let c_wrap_back = cell_00(&mut s);
    assert_eq!(c_wrap_back.no_wrap, false);
    assert_eq!(s.menu_state("docx.cell.wrap-text"), Some((true, true)));

    s.save_as("tblfmt019_cell_wrap_restored.docx");
    let saved_back = s.reopen();
    let d_back = flow(&saved_back);
    let t_saved_back = d_back.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_saved_back.rows[0].cells[0].no_wrap, false);
}

fn table014_select_table_row_column_cell() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");
    // 表の挿入 (2x2)
    s.menu("docx.table.insert-2x2");
    s.type_text("A1");
    s.key("tab");
    s.type_text("B1");
    s.key("tab");
    s.type_text("A2");
    s.key("tab");
    s.type_text("B2");

    let doc = s.document();
    let table = doc.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let p_00 = match &table.rows[0].cells[0].blocks[0] { Block::Paragraph(p) => p.id, _ => panic!() };
    let p_01 = match &table.rows[0].cells[1].blocks[0] { Block::Paragraph(p) => p.id, _ => panic!() };
    let p_10 = match &table.rows[1].cells[0].blocks[0] { Block::Paragraph(p) => p.id, _ => panic!() };
    let p_11 = match &table.rows[1].cells[1].blocks[0] { Block::Paragraph(p) => p.id, _ => panic!() };

    // キャレットは現在セル(1, 1)にある
    // 1. セルを選択 (Select Cell)
    s.menu("docx.table.select.cell");
    let (sel_a, sel_b) = s.selection().unwrap();
    assert_eq!(sel_a, FlowPos::new(p_11, 0));
    assert_eq!(sel_b, FlowPos::new(p_11, 2));

    // 2. 行を選択 (Select Row: row 1)
    s.menu("docx.table.select.row");
    let (sel_a, sel_b) = s.selection().unwrap();
    assert_eq!(sel_a, FlowPos::new(p_10, 0));
    assert_eq!(sel_b, FlowPos::new(p_11, 2));

    // 3. 列を選択 (Select Column: column 1)
    s.menu("docx.table.select.column");
    let (sel_a, sel_b) = s.selection().unwrap();
    assert_eq!(sel_a, FlowPos::new(p_01, 0));
    assert_eq!(sel_b, FlowPos::new(p_11, 2));

    // 4. 表を選択 (Select Table: entire table)
    s.menu("docx.table.select.table");
    let (sel_a, sel_b) = s.selection().unwrap();
    assert_eq!(sel_a, FlowPos::new(p_00, 0));
    assert_eq!(sel_b, FlowPos::new(p_11, 2));

    // 5. セル選択状態で太字 (cmd-b) を適用
    s.menu("docx.table.select.cell");
    s.key("cmd-b");
    let doc_bold = s.document();
    let t_bold = doc_bold.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let p_bold = match &t_bold.rows[1].cells[1].blocks[0] { Block::Paragraph(p) => p, _ => panic!() };
    assert!(p_bold.runs.iter().all(|r| r.style.bold), "selected cell (1, 1) should be bold");

    // 6. Undo / Redo
    s.key("cmd-z");
    let doc_undone = s.document();
    let t_undone = doc_undone.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let p_undone = match &t_undone.rows[1].cells[1].blocks[0] { Block::Paragraph(p) => p, _ => panic!() };
    assert!(!p_undone.runs.iter().any(|r| r.style.bold), "bold should be undone");

    s.key("cmd-shift-z");

    // 7. ファイル保存と再読込
    s.save_as("table014_selected_bold.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let t_saved = d.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let p_saved = match &t_saved.rows[1].cells[1].blocks[0] { Block::Paragraph(p) => p, _ => panic!() };
    assert!(p_saved.runs.iter().all(|r| r.style.bold), "bold should persist across reopen");
}

fn table004_insert_delete_cell_shift() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");
    // 表の挿入 (2x2)
    s.menu("docx.table.insert-2x2");
    s.type_text("A1");
    s.key("tab");
    s.type_text("B1");
    s.key("tab");
    s.type_text("A2");
    s.key("tab");
    s.type_text("B2");

    // 現在キャレットはセル (1, 1) "B2" にある
    // 1. セルを挿入（右方向にシフト）
    s.menu("docx.table.cell-insert.shift-right");
    let doc = s.document();
    let table = doc.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(table.rows[0].cells.len(), 2, "row 0 has 2 cells");
    assert_eq!(table.rows[1].cells.len(), 3, "row 1 now has 3 cells");
    let p_12 = match &table.rows[1].cells[2].blocks[0] { Block::Paragraph(p) => p.text(), _ => panic!() };
    assert_eq!(p_12, "B2");

    // 2. Undo
    s.key("cmd-z");
    let doc_undo = s.document();
    let t_undo = doc_undo.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_undo.rows[1].cells.len(), 2, "undo restores 2 cells in row 1");

    // 3. Redo
    s.key("cmd-shift-z");
    let doc_redo = s.document();
    let t_redo = doc_redo.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_redo.rows[1].cells.len(), 3, "redo restores 3 cells in row 1");

    // 4. ファイル保存と再読込
    s.save_as("table004_shift_right.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let t_saved = d.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_saved.rows[0].cells.len(), 2);
    assert_eq!(t_saved.rows[1].cells.len(), 3);
    let p_saved_12 = match &t_saved.rows[1].cells[2].blocks[0] { Block::Paragraph(p) => p.text(), _ => panic!() };
    assert_eq!(p_saved_12, "B2");

    // 5. セルを削除（左方向にシフト）
    // (1, 1) の空セルにキャレットを設定して削除
    let doc_cur = s.document();
    let t_cur = doc_cur.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let p_11_id = match &t_cur.rows[1].cells[1].blocks[0] { Block::Paragraph(p) => p.id, _ => panic!() };
    s.update(|e, _, cx| e.set_caret(FlowPos::new(p_11_id, 0), false, cx));
    s.menu("docx.table.cell-delete.shift-left");
    let doc_del = s.document();
    let t_del = doc_del.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_del.rows[1].cells.len(), 2, "row 1 returns to 2 cells");
    let p_del_11 = match &t_del.rows[1].cells[1].blocks[0] { Block::Paragraph(p) => p.text(), _ => panic!() };
    assert_eq!(p_del_11, "B2", "B2 shifted back to cell (1, 1)");

    // 6. セルを挿入（下方向にシフト）
    // (0, 0) "A1" にキャレットを設定
    let p_00_id = match &t_del.rows[0].cells[0].blocks[0] { Block::Paragraph(p) => p.id, _ => panic!() };
    s.update(|e, _, cx| e.set_caret(FlowPos::new(p_00_id, 0), false, cx));
    s.menu("docx.table.cell-insert.shift-down");
    let doc_down = s.document();
    let t_down = doc_down.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_down.rows.len(), 3, "table expanded to 3 rows");
    let p_down_10 = match &t_down.rows[1].cells[0].blocks[0] { Block::Paragraph(p) => p.text(), _ => panic!() };
    assert_eq!(p_down_10, "A1", "A1 shifted down to row 1");

    // 7. Undo down
    s.key("cmd-z");
    let doc_down_undo = s.document();
    let t_down_undo = doc_down_undo.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_down_undo.rows.len(), 2, "undo down restores 2 rows");
}

fn table008_nested_table_insert() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");
    // 親テーブルの挿入 (2x2)
    s.menu("docx.table.insert-2x2");
    s.type_text("親セル");

    // 現在、キャレットは親テーブルのセル (0, 0) にある
    // ここで子の入れ子の表 (2x2) を挿入
    s.menu("docx.table.insert-2x2");

    let doc = s.document();
    let parent_table = doc.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let cell_00_blocks = &parent_table.rows[0].cells[0].blocks;
    assert!(cell_00_blocks.len() >= 2, "cell has nested table and paragraphs");
    let nested_table = cell_00_blocks.iter().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).expect("nested table found in cell");
    assert_eq!(nested_table.rows.len(), 2);
    assert_eq!(nested_table.rows[0].cells.len(), 2);

    // 子テーブルの幅が親テーブルの列幅以下であることを確認
    let parent_col0_w = parent_table.columns[0];
    let nested_w: i64 = nested_table.columns.iter().sum();
    assert!(nested_w <= parent_col0_w, "nested table width ({nested_w}) <= parent column width ({parent_col0_w})");

    // 1-step Undo
    s.key("cmd-z");
    let doc_undo = s.document();
    let parent_undo = doc_undo.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let has_nested = parent_undo.rows[0].cells[0].blocks.iter().any(|b| matches!(b, Block::Table(_)));
    assert!(!has_nested, "1-step undo removed nested table");

    // 1-step Redo
    s.key("cmd-shift-z");
    let doc_redo = s.document();
    let parent_redo = doc_redo.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let nested_redo = parent_redo.rows[0].cells[0].blocks.iter().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).expect("nested table restored");
    assert_eq!(nested_redo.rows.len(), 2);

    // 子テーブルのセル (0, 0) にキャレットを設定して文字入力
    let child_p_id = match &nested_redo.rows[0].cells[0].blocks[0] { Block::Paragraph(p) => p.id, _ => panic!() };
    s.update(|e, _, cx| e.set_caret(FlowPos::new(child_p_id, 0), false, cx));
    s.type_text("子1");

    // ファイル保存と再読込
    s.save_as("table008_nested_table.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let parent_saved = d.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let nested_saved = parent_saved.rows[0].cells[0].blocks.iter().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).expect("nested table persisted across reopen");
    assert_eq!(nested_saved.rows.len(), 2);
    assert_eq!(nested_saved.rows[0].cells.len(), 2);
    let p_child = match &nested_saved.rows[0].cells[0].blocks[0] { Block::Paragraph(p) => p.text(), _ => panic!() };
    assert_eq!(p_child, "子1");
}

fn table013_cell_paragraphs_and_lists() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");

    // 1. 2x2 表の挿入
    s.menu("docx.table.insert-2x2");
    let doc_init = s.document();
    let t_init = doc_init.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let c00_p1 = match &t_init.rows[0].cells[0].blocks[0] {
        Block::Paragraph(p) => p.id,
        _ => panic!("Expected paragraph in cell 0,0"),
    };

    // 2. セル (0, 0) 内で改行による複数段落作成
    s.click_text(FlowPos::new(c00_p1, 0));
    s.type_text("項目1");
    s.key("enter");
    s.type_text("項目2");
    s.key("enter");
    s.type_text("項目3");

    let doc_multi = s.document();
    let t_multi = doc_multi.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let c00_blocks = &t_multi.rows[0].cells[0].blocks;
    assert_eq!(c00_blocks.len(), 3, "セル内に3つの段落が作成されること");
    let (_p1_id, p2_id, p3_id) = match (&c00_blocks[0], &c00_blocks[1], &c00_blocks[2]) {
        (Block::Paragraph(p1), Block::Paragraph(p2), Block::Paragraph(p3)) => {
            assert_eq!(p1.text(), "項目1");
            assert_eq!(p2.text(), "項目2");
            assert_eq!(p3.text(), "項目3");
            (p1.id, p2.id, p3.id)
        }
        _ => panic!("Expected 3 paragraphs in cell 0,0"),
    };

    // 3. セル (0, 0) を選択して箇条書き（Bullets）を適用
    s.menu("docx.table.select.cell");
    s.menu("docx.bullet.toggle");

    let doc_bullet = s.document();
    let t_bullet = doc_bullet.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    for b in &t_bullet.rows[0].cells[0].blocks {
        let Block::Paragraph(p) = b else { panic!() };
        assert!(p.list.is_some(), "全段落に箇条書きが適用されること");
        let list = p.list.unwrap();
        assert_eq!(list.level, 0, "初期レベルは0");
        let fmt = doc_bullet.styles.numbering.level(list.num_id, list.level).unwrap();
        assert_eq!(fmt.format, "bullet");
    }

    // 4. セル内リスト項目のレベル変更（インデント増・減）
    s.update(|e, _, cx| e.set_caret(FlowPos::new(p2_id, 0), false, cx));
    s.update(|e, _, cx| e.step_indent(true, cx));
    let doc_ind = s.document();
    let t_ind = doc_ind.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let p2_after_inc = match &t_ind.rows[0].cells[0].blocks[1] { Block::Paragraph(p) => p, _ => panic!() };
    assert_eq!(p2_after_inc.list.unwrap().level, 1, "インデント増でレベルが1に昇格すること");

    s.update(|e, _, cx| e.step_indent(false, cx));
    let doc_deind = s.document();
    let t_deind = doc_deind.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let p2_after_dec = match &t_deind.rows[0].cells[0].blocks[1] { Block::Paragraph(p) => p, _ => panic!() };
    assert_eq!(p2_after_dec.list.unwrap().level, 0, "インデント減でレベルが0に戻ること");

    // 5. セル内リスト項目での改行による継続と、空項目でのEnterによるリスト解除
    s.click_text(FlowPos::new(p3_id, 3)); // "項目3"の末尾
    s.key("enter");
    let doc_enter = s.document();
    let t_enter = doc_enter.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_enter.rows[0].cells[0].blocks.len(), 4, "Enterで4番目の段落が追加されること");
    let p4_new = match &t_enter.rows[0].cells[0].blocks[3] { Block::Paragraph(p) => p, _ => panic!() };
    assert!(p4_new.list.is_some(), "Enterで生成された段落も箇条書きを引き継ぐこと");
    assert!(p4_new.is_empty());

    // 空の段落でEnter -> リスト解除
    s.key("enter");
    let doc_exit = s.document();
    let t_exit = doc_exit.body.clone().into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let p4_exited = match &t_exit.rows[0].cells[0].blocks[3] { Block::Paragraph(p) => p, _ => panic!() };
    assert!(p4_exited.list.is_none(), "空リスト項目でのEnterによりリストが解除されること");

    // 6. 表全体を選択して番号付きリスト（Numbered list）への切り替え
    s.menu("docx.table.select.table");
    s.menu("docx.list.toggle");
    let doc_numbered = s.document();
    let t_numbered = doc_numbered.body.clone().into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    // 表内のすべてのセルの段落が番号付きリストになっていることを確認
    for row in &t_numbered.rows {
        for cell in &row.cells {
            for b in &cell.blocks {
                let Block::Paragraph(p) = b else { panic!() };
                assert!(p.list.is_some(), "表選択による一括番号付きリストが適用されること");
                let list = p.list.unwrap();
                let fmt = doc_numbered.styles.numbering.level(list.num_id, list.level).unwrap();
                assert_ne!(fmt.format, "bullet", "番号付きリストであること");
            }
        }
    }

    // 7. 1ステップ Undo / Redo
    s.key("cmd-z");
    assert_eq!(s.document(), doc_exit, "Undoで表全体番号付きリスト適用前の状態に完全一致");
    s.key("cmd-shift-z");
    assert_eq!(s.document(), doc_numbered, "Redoで表全体番号付きリスト適用後の状態に完全一致");

    // 8. ファイル保存と再オープンによる OOXML 永続化検証
    s.save_as("table013_cell_paragraphs_lists.docx");
    let saved = s.reopen();
    let d = flow(&saved);
    let t_saved = d.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).expect("table persisted");
    assert_eq!(t_saved.rows[0].cells[0].blocks.len(), 4);
    let p1_saved = match &t_saved.rows[0].cells[0].blocks[0] { Block::Paragraph(p) => p, _ => panic!() };
    assert_eq!(p1_saved.text(), "項目1");
    assert!(p1_saved.list.is_some(), "セル内段落のリスト設定が保存・再読込で保持されること");
    let l_saved = p1_saved.list.unwrap();
    let fmt_saved = d.styles.numbering.level(l_saved.num_id, l_saved.level).expect("numbering level defined in styles");
    assert_ne!(fmt_saved.format, "bullet", "番号付きリスト形式が保持されること");
}

fn table011_sort_table() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");

    // 1. 3x3 の表を挿入
    s.menu("docx.table.insert-3x3");
    let doc_init = s.document();
    let t_init = doc_init.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).expect("table inserted");
    assert_eq!(t_init.rows.len(), 3);
    assert_eq!(t_init.columns.len(), 3);

    let cell_para_id = |t: &ibis_doc_model::FlowTable, r: usize, c: usize| {
        match &t.rows[r].cells[c].blocks[0] {
            Block::Paragraph(p) => p.id,
            _ => panic!("expected paragraph"),
        }
    };
    let cell_text = |t: &ibis_doc_model::FlowTable, r: usize, c: usize| {
        match &t.rows[r].cells[c].blocks[0] {
            Block::Paragraph(p) => p.text(),
            _ => panic!("expected paragraph"),
        }
    };

    // 表のセルにデータを入力する
    // Header (Row 0): [ "Fruit", "Price", "Qty" ]
    // Row 1:          [ "Banana", "300", "5" ]
    // Row 2:          [ "Apple", "100", "20" ]
    let p_h0 = cell_para_id(t_init, 0, 0);
    let p_h1 = cell_para_id(t_init, 0, 1);
    let p_h2 = cell_para_id(t_init, 0, 2);

    let p_r1_c0 = cell_para_id(t_init, 1, 0);
    let p_r1_c1 = cell_para_id(t_init, 1, 1);
    let p_r1_c2 = cell_para_id(t_init, 1, 2);

    let p_r2_c0 = cell_para_id(t_init, 2, 0);
    let p_r2_c1 = cell_para_id(t_init, 2, 1);
    let p_r2_c2 = cell_para_id(t_init, 2, 2);

    s.click_text(FlowPos::new(p_h0, 0));
    s.type_text("Fruit");
    s.click_text(FlowPos::new(p_h1, 0));
    s.type_text("Price");
    s.click_text(FlowPos::new(p_h2, 0));
    s.type_text("Qty");

    s.click_text(FlowPos::new(p_r1_c0, 0));
    s.type_text("Banana");
    s.click_text(FlowPos::new(p_r1_c1, 0));
    s.type_text("300");
    s.click_text(FlowPos::new(p_r1_c2, 0));
    s.type_text("5");

    s.click_text(FlowPos::new(p_r2_c0, 0));
    s.type_text("Apple");
    s.click_text(FlowPos::new(p_r2_c1, 0));
    s.type_text("100");
    s.click_text(FlowPos::new(p_r2_c2, 0));
    s.type_text("20");

    let doc_data = s.document();
    let t_data = doc_data.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(cell_text(t_data, 1, 0), "Banana");
    assert_eq!(cell_text(t_data, 2, 0), "Apple");

    // 2. 列0（Fruit: テキスト）で昇順ソート（タイトル行を除く）
    // Banana (row 1), Apple (row 2) -> Apple (row 1), Banana (row 2)
    s.click_text(FlowPos::new(p_r1_c0, 0));
    s.menu("docx.table.sort.asc");

    let doc_asc = s.document();
    let t_asc = doc_asc.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(cell_text(t_asc, 0, 0), "Fruit");
    assert_eq!(cell_text(t_asc, 1, 0), "Apple");
    assert_eq!(cell_text(t_asc, 1, 1), "100");
    assert_eq!(cell_text(t_asc, 2, 0), "Banana");
    assert_eq!(cell_text(t_asc, 2, 1), "300");

    // 3. 1ステップ Undo で元順序（Banana, Apple）に復帰
    s.key("cmd-z");
    let doc_undo = s.document();
    let t_undo = doc_undo.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(cell_text(t_undo, 1, 0), "Banana");
    assert_eq!(cell_text(t_undo, 2, 0), "Apple");

    // 4. Redo で昇順状態に復帰
    s.key("cmd-shift-z");
    let doc_redo = s.document();
    let t_redo = doc_redo.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(cell_text(t_redo, 1, 0), "Apple");
    assert_eq!(cell_text(t_redo, 2, 0), "Banana");

    // 5. 列1（Price: 数値）で降順ソート（タイトル行を除く）
    // Apple (100), Banana (300) -> 降順: Banana (300), Apple (100)
    let cur_r1_c1 = cell_para_id(t_redo, 1, 1);
    s.click_text(FlowPos::new(cur_r1_c1, 0));
    s.menu("docx.table.sort.desc");

    let doc_desc = s.document();
    let t_desc = doc_desc.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(cell_text(t_desc, 0, 0), "Fruit");
    assert_eq!(cell_text(t_desc, 1, 0), "Banana");
    assert_eq!(cell_text(t_desc, 1, 1), "300");
    assert_eq!(cell_text(t_desc, 2, 0), "Apple");
    assert_eq!(cell_text(t_desc, 2, 1), "100");

    // 6. 保存と再読込による永続化検証
    s.save_as("table011_sorted_table.docx");
    let saved = s.reopen();
    let d_saved = flow(&saved);
    let t_saved = d_saved.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).expect("table persisted");
    assert_eq!(cell_text(t_saved, 0, 0), "Fruit");
    assert_eq!(cell_text(t_saved, 1, 0), "Banana");
    assert_eq!(cell_text(t_saved, 1, 1), "300");
    assert_eq!(cell_text(t_saved, 2, 0), "Apple");
    assert_eq!(cell_text(t_saved, 2, 1), "100");
}

fn tblfmt020_table_floating() {
    use ibis_doc_model::{TableAlign, TableAnchor};

    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");

    // 1. 2x2 の表を挿入
    s.menu("docx.table.insert-2x2");
    let doc_init = s.document();
    let t_init = doc_init.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).expect("table inserted");
    assert_eq!(t_init.rows.len(), 2);
    assert_eq!(t_init.columns.len(), 2);
    // 初期状態はインライン配置（floating == None）
    assert_eq!(t_init.floating, None, "初期状態はインライン表");

    // 表セル内にテキストを入力（挿入直後はセル (0, 0) にキャレットがある）
    s.type_text("FloatTable");

    // 2. 文字列の折り返しを「周囲に配置（左）」に設定
    s.menu("docx.table.wrap.around-left");
    let doc_float = s.document();
    let t_float = doc_float.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let f1 = t_float.floating.expect("floating table created");
    assert_eq!(f1.horz_anchor, TableAnchor::Margin);
    assert_eq!(f1.x_align, Some(TableAlign::Start));
    assert_eq!(f1.distance, [180 * 635, 180 * 635, 0, 0], "既定の距離: 左右 9pt, 上下 0pt");

    // 3. 1ステップ Undo でインライン（None）に戻る
    s.key("cmd-z");
    let doc_undo = s.document();
    let t_undo = doc_undo.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_undo.floating, None, "Undo でインライン表に復帰");

    // 4. Redo で浮動表に復帰
    s.key("cmd-shift-z");
    let doc_redo = s.document();
    let t_redo = doc_redo.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert!(t_redo.floating.is_some(), "Redo で浮動表に復帰");

    // 5. 周囲の文字列からの距離を「中（左右 9 pt / 上下 6 pt）」に変更
    s.menu("docx.table.float-distance.medium");
    let doc_dist = s.document();
    let t_dist = doc_dist.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let f2 = t_dist.floating.expect("floating table exists");
    assert_eq!(f2.distance, [180 * 635, 180 * 635, 120 * 635, 120 * 635], "距離が中に変更されること");

    // 6. 配置を「周囲に配置（中央）」に変更
    s.menu("docx.table.wrap.around-center");
    let doc_center = s.document();
    let t_center = doc_center.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let f3 = t_center.floating.expect("floating table exists");
    assert_eq!(f3.x_align, Some(TableAlign::Center), "水平配置が中央に変更されること");

    // 7. 保存と再読込による永続化検証
    s.save_as("tblfmt020_floating_table.docx");
    let saved = s.reopen();
    let d_saved = flow(&saved);
    let t_saved = d_saved.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).expect("table persisted");
    let f_saved = t_saved.floating.expect("floating persisted");
    assert_eq!(f_saved.horz_anchor, TableAnchor::Margin);
    assert_eq!(f_saved.x_align, Some(TableAlign::Center));
    assert_eq!(f_saved.distance, [180 * 635, 180 * 635, 120 * 635, 120 * 635]);

    // 8. 折り返しを「なし（行内）」に変更してインラインに戻す
    let doc_cur = s.document();
    let t_cur = doc_cur.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let p_00_id = match &t_cur.rows[0].cells[0].blocks[0] { Block::Paragraph(p) => p.id, _ => panic!() };
    s.update(|e, _, cx| e.set_caret(FlowPos::new(p_00_id, 0), false, cx));
    s.menu("docx.table.wrap.none");
    let doc_inline = s.document();
    let t_inline = doc_inline.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_inline.floating, None, "折り返しなしでインライン表に戻る");

    // 9. インライン状態を保存・再オープンして保持されることを検証
    s.save_as("tblfmt020_inline_table.docx");
    let saved_inline = s.reopen();
    let d_saved_inline = flow(&saved_inline);
    let t_saved_inline = d_saved_inline.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).expect("table persisted");
    assert_eq!(t_saved_inline.floating, None, "再オープン後もインライン表が保持される");
}

fn table016_apply_table_style() {
    let mut s = Scenario::open(REPORT);
    s.key("cmd-down");
    s.key("enter");

    // 1. 2x2 の表を挿入
    s.menu("docx.table.insert-2x2");
    let doc_init = s.document();
    let t_init = doc_init.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).expect("table inserted");
    assert_eq!(t_init.rows.len(), 2);
    assert_eq!(t_init.columns.len(), 2);
    // 初期状態は規定の表スタイル TableGrid
    assert_eq!(t_init.style.as_ref().map(|st| st.id.as_str()), Some("TableGrid"), "初期状態は TableGrid");

    // 表セル内にテキストを入力
    s.type_text("StyledTable");

    // 2. 表スタイルを一旦解除（docx.table.style.none）
    s.menu("docx.table.style.none");
    let doc_none = s.document();
    let t_none = doc_none.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_none.style, None, "スタイル解除で None");

    // 3. 表スタイル「表のグリッド（TableGrid）」を適用
    s.menu("docx.table.style.table-grid");
    let doc_grid = s.document();
    let t_grid = doc_grid.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_grid.style.as_ref().map(|st| st.id.as_str()), Some("TableGrid"));

    // 4. 1ステップ Undo でスタイルなしに戻る
    s.key("cmd-z");
    let doc_undo = s.document();
    let t_undo = doc_undo.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_undo.style, None, "Undo でスタイルなしに復帰");

    // 5. Redo で TableGrid に復帰
    s.key("cmd-shift-z");
    let doc_redo = s.document();
    let t_redo = doc_redo.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_redo.style.as_ref().map(|st| st.id.as_str()), Some("TableGrid"), "Redo で TableGrid に復帰");

    // 5. 保存と再読込による永続化検証
    s.save_as("table016_table_style.docx");
    let saved = s.reopen();
    let d_saved = flow(&saved);
    let t_saved = d_saved.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).expect("table persisted");
    assert_eq!(t_saved.style.as_ref().map(|st| st.id.as_str()), Some("TableGrid"), "保存再オープン後も TableGrid が保持される");

    // 6. 表スタイルを解除（なし）
    let doc_cur = s.document();
    let t_cur = doc_cur.body.into_iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    let p_00_id = match &t_cur.rows[0].cells[0].blocks[0] { Block::Paragraph(p) => p.id, _ => panic!() };
    s.update(|e, _, cx| e.set_caret(FlowPos::new(p_00_id, 0), false, cx));
    s.menu("docx.table.style.none");
    let doc_none = s.document();
    let t_none = doc_none.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).unwrap();
    assert_eq!(t_none.style, None, "スタイル解除で None に戻る");

    // 7. 解除状態を保存・再オープンして保持されることを検証
    s.save_as("table016_no_style.docx");
    let saved_none = s.reopen();
    let d_saved_none = flow(&saved_none);
    let t_saved_none = d_saved_none.body.iter().rev().find_map(|b| if let Block::Table(t) = b { Some(t) } else { None }).expect("table persisted");
    assert_eq!(t_saved_none.style, None, "再オープン後もスタイル解除が保持される");
}

fn float002_picture_wrap_and_floating() {
    let mut s = Scenario::open(REPORT);

    // 1. REPORT ドキュメント内の画像の位置を探索
    let (id, offset, _media) = s.with(|e, _| {
        for p in body(flow(e.presentation())) {
            let mut offset = 0;
            for r in &p.runs {
                if let FlowRunKind::Picture { media, .. } = r.kind {
                    return (p.id, offset, media);
                }
                offset += r.len();
            }
        }
        panic!("a picture in REPORT");
    });

    // 2. キャレットを画像位置に移動し、初期状態（行内画像）を検証
    s.click_text(FlowPos::new(id, offset));
    assert_eq!(s.with(|e, _| e.picture_wrap_at_caret()), Some(ibis_doc_model::PictureWrapType::Inline), "初期状態は行内画像");
    assert_eq!(s.menu_state("docx.picture.wrap.inline"), Some((true, true)), "wrap inline がチェックされている");

    // 3. 折り返しを「四角形（Square）」に変更
    s.menu("docx.picture.wrap.square");
    assert_eq!(s.with(|e, _| e.picture_wrap_at_caret()), Some(ibis_doc_model::PictureWrapType::Square));
    assert_eq!(s.menu_state("docx.picture.wrap.square"), Some((true, true)));
    assert_eq!(s.menu_state("docx.picture.wrap.inline"), Some((true, false)));
    let anchor = s.with(|e, _| e.picture_floating_at_caret()).expect("floating anchor exists");
    assert_eq!(anchor.wrap, "square");

    // 4. 水平配置を「中央揃え（Center）」に変更
    s.menu("docx.picture.align-h.center");
    assert_eq!(s.menu_state("docx.picture.align-h.center"), Some((true, true)));
    let anchor_center = s.with(|e, _| e.picture_floating_at_caret()).expect("floating anchor");
    assert_eq!(anchor_center.align_h.as_deref(), Some("center"));

    // 4b. 垂直配置を「上揃え（Top）」に変更
    s.menu("docx.picture.align-v.top");
    assert_eq!(s.menu_state("docx.picture.align-v.top"), Some((true, true)));
    let anchor_top = s.with(|e, _| e.picture_floating_at_caret()).expect("floating anchor");
    assert_eq!(anchor_top.align_v.as_deref(), Some("top"));

    // 5. 文字との距離を「中（左右 9 pt / 上下 6 pt）」に変更
    s.menu("docx.picture.distance.medium");
    assert_eq!(s.menu_state("docx.picture.distance.medium"), Some((true, true)));
    let anchor_dist = s.with(|e, _| e.picture_floating_at_caret()).expect("floating anchor");
    assert_eq!(anchor_dist.dist_l, 114_300);
    assert_eq!(anchor_dist.dist_r, 114_300);
    assert_eq!(anchor_dist.dist_t, 76_200);
    assert_eq!(anchor_dist.dist_b, 76_200);

    // 6. 折り返しを「前面（InFrontOfText）」に変更
    s.menu("docx.picture.wrap.in-front-of-text");
    assert_eq!(s.with(|e, _| e.picture_wrap_at_caret()), Some(ibis_doc_model::PictureWrapType::InFrontOfText));
    assert_eq!(s.menu_state("docx.picture.wrap.in-front-of-text"), Some((true, true)));

    // 6b. アンカー固定（locked）をオン、オーバーラップ許可をオフ、表のセル内で配置（layout-in-cell）をオフに変更
    assert_eq!(s.menu_state("docx.picture.lock-anchor"), Some((true, false)));
    assert_eq!(s.menu_state("docx.picture.allow-overlap"), Some((true, true)));
    assert_eq!(s.menu_state("docx.picture.layout-in-cell"), Some((true, true)), "初期は表のセル内で配置がオン");
    s.menu("docx.picture.lock-anchor");
    s.menu("docx.picture.allow-overlap");
    s.menu("docx.picture.layout-in-cell");
    assert_eq!(s.menu_state("docx.picture.lock-anchor"), Some((true, true)));
    assert_eq!(s.menu_state("docx.picture.allow-overlap"), Some((true, false)));
    assert_eq!(s.menu_state("docx.picture.layout-in-cell"), Some((true, false)), "トグルで表のセル内で配置がオフ");
    let anchor_opt = s.with(|e, _| e.picture_floating_at_caret()).expect("floating anchor");
    assert!(anchor_opt.locked);
    assert!(!anchor_opt.allow_overlap);
    assert!(!anchor_opt.layout_in_cell);

    // 6c. 本文と一緒に移動（move-with-text）とページ上の位置固定（fix-position-on-page）の検証
    assert_eq!(s.menu_state("docx.picture.move-with-text"), Some((true, true)), "初期は本文と一緒に移動がオン");
    assert_eq!(s.menu_state("docx.picture.fix-position-on-page"), Some((true, false)), "初期はページ上の位置固定がオフ");
    s.menu("docx.picture.fix-position-on-page");
    assert_eq!(s.menu_state("docx.picture.move-with-text"), Some((true, false)), "ページ固定時は本文と一緒に移動がオフ");
    assert_eq!(s.menu_state("docx.picture.fix-position-on-page"), Some((true, true)), "ページ固定がオン");
    let anchor_fixed = s.with(|e, _| e.picture_floating_at_caret()).expect("floating anchor");
    assert_eq!(anchor_fixed.relative_v, "page");
    assert!(!anchor_fixed.moves_with_text());

    // 6d. 重なり順（Z-order: front, backward, back, forward）の検証
    let h_init = anchor_fixed.relative_height;
    s.menu("docx.picture.zorder.front");
    let anchor_front = s.with(|e, _| e.picture_floating_at_caret()).expect("floating anchor");
    assert!(anchor_front.relative_height > h_init, "最前面へ移動で relative_height が増加");
    let h_front = anchor_front.relative_height;
    s.menu("docx.picture.zorder.backward");
    let anchor_back = s.with(|e, _| e.picture_floating_at_caret()).expect("floating anchor");
    assert!(anchor_back.relative_height < h_front, "背面へ移動で relative_height が減少");
    let h_target = anchor_back.relative_height;

    // 7. Undo / Redo の検証
    s.key("cmd-z");
    let anchor_undo1 = s.with(|e, _| e.picture_floating_at_caret()).expect("floating anchor after undo");
    assert_eq!(anchor_undo1.relative_height, h_front, "Undo で relative_height が復帰");
    s.key("cmd-shift-z");
    let anchor_redo1 = s.with(|e, _| e.picture_floating_at_caret()).expect("floating anchor after redo");
    assert_eq!(anchor_redo1.relative_height, h_target, "Redo で relative_height が復帰");
    assert_eq!(anchor_redo1.relative_v, "page");
    assert!(!anchor_redo1.allow_overlap, "Redo で allow_overlap が false に復帰");
    assert!(!anchor_redo1.layout_in_cell, "Redo で layout_in_cell が false に復帰");

    // 8. 保存と再読込による永続化検証（浮動画像）
    s.save_as("float002_picture_floating.docx");
    let saved = s.reopen();
    let d_saved = flow(&saved);
    let mut found_floating = false;
    for p in body(d_saved) {
        for r in &p.runs {
            if let FlowRunKind::Shape(ref shape) = r.kind {
                if let ibis_doc_model::ShapeKind::Picture(_) = shape.kind {
                    if let Some(ref fl) = shape.floating {
                        assert_eq!(ibis_doc_model::PictureWrapType::from_anchor(fl), ibis_doc_model::PictureWrapType::InFrontOfText);
                        assert_eq!(fl.align_h.as_deref(), Some("center"));
                        assert_eq!(fl.align_v.as_deref(), Some("top"));
                        assert_eq!(fl.dist_l, 114_300);
                        assert_eq!(fl.dist_t, 76_200);
                        assert!(fl.locked, "再オープン後も locked が保持される");
                        assert!(!fl.allow_overlap, "再オープン後も allow_overlap が保持される");
                        assert!(!fl.layout_in_cell, "再オープン後も layout_in_cell が保持される");
                        assert_eq!(fl.relative_v, "page", "再オープン後も relative_v=page が保持される");
                        assert_eq!(fl.relative_height, h_target, "再オープン後も relative_height が保持される");
                        found_floating = true;
                    }
                }
            }
        }
    }
    assert!(found_floating, "再オープン後も浮動画像とその設定が保持される");

    // 9. 行内に戻す検証
    let (id_reopen, offset_reopen) = s.with(|e, _| {
        for p in body(flow(e.presentation())) {
            let mut offset = 0;
            for r in &p.runs {
                let is_pic = match r.kind {
                    FlowRunKind::Picture { .. } => true,
                    FlowRunKind::Shape(ref sh) => matches!(sh.kind, ibis_doc_model::ShapeKind::Picture(_)),
                    _ => false,
                };
                if is_pic {
                    return (p.id, offset);
                }
                offset += r.len();
            }
        }
        panic!("picture after reopen");
    });
    s.click_text(FlowPos::new(id_reopen, offset_reopen));
    s.menu("docx.picture.move-with-text");
    assert_eq!(s.menu_state("docx.picture.move-with-text"), Some((true, true)));
    assert_eq!(s.with(|e, _| e.picture_floating_at_caret()).unwrap().relative_v, "paragraph");
    s.menu("docx.picture.wrap.inline");
    assert_eq!(s.with(|e, _| e.picture_wrap_at_caret()), Some(ibis_doc_model::PictureWrapType::Inline));
    s.save_as("float002_picture_inline.docx");
    let saved_inline = s.reopen();
    let d_saved_inline = flow(&saved_inline);
    let mut found_inline = false;
    for p in body(d_saved_inline) {
        for r in &p.runs {
            if let FlowRunKind::Picture { .. } = r.kind {
                found_inline = true;
            }
        }
    }
    assert!(found_inline, "再オープン後も行内画像に戻っている");
}

fn float015_picture_align_and_distribute() {
    let mut s = Scenario::open(REPORT);

    // 1. 画像データを取得して段落に計 3 つの画像を挿入
    let data: Vec<u8> = s.with(|e, _| e.presentation().media.iter().find(|m| m.format == ibis_doc_model::MediaFormat::Png).map(|m| m.data.to_vec())).expect("a PNG in the report");
    let (_, id1, _) = text_paragraph(&mut s, 2);
    let (_, id2, _) = text_paragraph(&mut s, 4);

    s.click_text(FlowPos::new(id1, 0));
    s.update(|e, _, cx| e.doc_insert_picture(data.clone(), ibis_doc_model::MediaFormat::Png, cx));
    s.click_text(FlowPos::new(id1, 0));
    s.menu("docx.picture.wrap.square");

    s.click_text(FlowPos::new(id1, 5));
    s.update(|e, _, cx| e.doc_insert_picture(data.clone(), ibis_doc_model::MediaFormat::Png, cx));
    s.click_text(FlowPos::new(id1, 5));
    s.menu("docx.picture.wrap.square");

    s.click_text(FlowPos::new(id2, 0));
    s.update(|e, _, cx| e.doc_insert_picture(data.clone(), ibis_doc_model::MediaFormat::Png, cx));
    s.click_text(FlowPos::new(id2, 0));
    s.menu("docx.picture.wrap.square");

    // 3 つの浮動画像が存在することを確認
    let pics = s.with(|e, _| e.document_floating_pictures());
    assert_eq!(pics.len(), 3, "3 つの浮動画像が取得できる");

    // 2. 整列の基準（余白／用紙）の切り替えとメニュー状態の検証
    s.click_text(pics[0].at);
    s.menu("docx.picture.align-to.page");
    assert_eq!(s.menu_state("docx.picture.align-to.page"), Some((true, true)));
    assert_eq!(s.with(|e, _| e.picture_floating_at_caret().unwrap().relative_h), "page");
    assert_eq!(s.with(|e, _| e.picture_floating_at_caret().unwrap().relative_v), "page");

    s.menu("docx.picture.align-to.margin");
    assert_eq!(s.menu_state("docx.picture.align-to.margin"), Some((true, true)));
    assert_eq!(s.with(|e, _| e.picture_floating_at_caret().unwrap().relative_h), "margin");
    assert_eq!(s.with(|e, _| e.picture_floating_at_caret().unwrap().relative_v), "margin");

    // 3. 整列メニュー（左・中央・右・上・上下中央・下）の動作とメニュー状態の検証
    s.menu("docx.picture.align.left");
    assert_eq!(s.menu_state("docx.picture.align.left"), Some((true, true)));
    assert_eq!(s.with(|e, _| e.picture_floating_at_caret().unwrap().align_h).as_deref(), Some("left"));

    s.menu("docx.picture.align.center");
    assert_eq!(s.menu_state("docx.picture.align.center"), Some((true, true)));
    assert_eq!(s.with(|e, _| e.picture_floating_at_caret().unwrap().align_h).as_deref(), Some("center"));

    s.menu("docx.picture.align.right");
    assert_eq!(s.menu_state("docx.picture.align.right"), Some((true, true)));
    assert_eq!(s.with(|e, _| e.picture_floating_at_caret().unwrap().align_h).as_deref(), Some("right"));

    s.menu("docx.picture.align.top");
    assert_eq!(s.menu_state("docx.picture.align.top"), Some((true, true)));
    assert_eq!(s.with(|e, _| e.picture_floating_at_caret().unwrap().align_v).as_deref(), Some("top"));

    s.menu("docx.picture.align.middle");
    assert_eq!(s.menu_state("docx.picture.align.middle"), Some((true, true)));
    assert_eq!(s.with(|e, _| e.picture_floating_at_caret().unwrap().align_v).as_deref(), Some("center"));

    s.menu("docx.picture.align.bottom");
    assert_eq!(s.menu_state("docx.picture.align.bottom"), Some((true, true)));
    assert_eq!(s.with(|e, _| e.picture_floating_at_caret().unwrap().align_v).as_deref(), Some("bottom"));

    // 4. 水平方向の均等配置（左右に整列）の検証
    s.update(|e, _, cx| {
        let mut pics = e.document_floating_pictures();
        pics[0].anchor.offset_x = 100_000;
        pics[0].anchor.align_h = None;
        pics[1].anchor.offset_x = 150_000;
        pics[1].anchor.align_h = None;
        pics[2].anchor.offset_x = 500_000;
        pics[2].anchor.align_h = None;
        let cmds = pics.into_iter().map(|p| ibis_doc_model::FlowCommand::SetPictureFloating { at: p.at, anchor: Some(p.anchor) }).collect();
        e.run_flow(cmds, cx);
    });

    s.menu("docx.picture.distribute.horizontally");
    let distributed_x = s.with(|e, _| {
        let mut pics = e.document_floating_pictures();
        pics.sort_by_key(|p| p.anchor.offset_x);
        pics.into_iter().map(|p| p.anchor.offset_x).collect::<Vec<_>>()
    });
    assert_eq!(distributed_x.len(), 3);
    assert_eq!(distributed_x[0], 100_000, "左端画像の位置は保持される");
    assert!(distributed_x[1] > 100_000 && distributed_x[1] < distributed_x[2], "中間の画像が均等に配分される");

    // Undo で元のオフセットに戻る
    s.key("cmd-z");
    let reverted_x = s.with(|e, _| {
        let mut pics = e.document_floating_pictures();
        pics.sort_by_key(|p| p.anchor.offset_x);
        pics.into_iter().map(|p| p.anchor.offset_x).collect::<Vec<_>>()
    });
    assert_eq!(reverted_x[1], 150_000, "Undo で元の X 座標に復帰");

    // Redo で等間隔に戻る
    s.key("cmd-shift-z");
    let redone_x = s.with(|e, _| {
        let mut pics = e.document_floating_pictures();
        pics.sort_by_key(|p| p.anchor.offset_x);
        pics.into_iter().map(|p| p.anchor.offset_x).collect::<Vec<_>>()
    });
    assert_eq!(redone_x, distributed_x, "Redo で均等配置に戻る");

    // 5. 垂直方向の均等配置（上下に整列）の検証
    s.update(|e, _, cx| {
        let mut pics = e.document_floating_pictures();
        pics[0].anchor.offset_y = 50_000;
        pics[0].anchor.align_v = None;
        pics[1].anchor.offset_y = 80_000;
        pics[1].anchor.align_v = None;
        pics[2].anchor.offset_y = 450_000;
        pics[2].anchor.align_v = None;
        let cmds = pics.into_iter().map(|p| ibis_doc_model::FlowCommand::SetPictureFloating { at: p.at, anchor: Some(p.anchor) }).collect();
        e.run_flow(cmds, cx);
    });

    s.menu("docx.picture.distribute.vertically");
    let distributed_y = s.with(|e, _| {
        let mut pics = e.document_floating_pictures();
        pics.sort_by_key(|p| p.anchor.offset_y);
        pics.into_iter().map(|p| p.anchor.offset_y).collect::<Vec<_>>()
    });
    assert_eq!(distributed_y.len(), 3);
    assert_eq!(distributed_y[0], 50_000, "上端画像の位置は保持される");
    assert!(distributed_y[1] > 50_000 && distributed_y[1] < distributed_y[2], "中間の画像が均等に配分される");

    // 6. 保存と再読込による永続化検証
    s.save_as("float015_align_distribute.docx");
    let saved = s.reopen();
    let d_saved = flow(&saved);
    let mut saved_floating_count = 0;
    for p in body(d_saved) {
        for r in &p.runs {
            if let FlowRunKind::Shape(ref shape) = r.kind {
                if let ibis_doc_model::ShapeKind::Picture(_) = shape.kind {
                    if shape.floating.is_some() {
                        saved_floating_count += 1;
                    }
                }
            }
        }
    }
    assert_eq!(saved_floating_count, 3, "保存再オープン後も 3 つの浮動画像とその設定が保持される");
}

fn page018_page_borders() {
    let mut s = Scenario::open(REPORT);

    // 1. 初期状態：ページ罫線なし
    assert_eq!(s.menu_state("docx.page.borders.none"), Some((true, true)), "初期状態は枠線なし");
    assert_eq!(s.menu_state("docx.page.borders.box-medium"), Some((true, false)));
    assert!(!s.document().page.borders.iter().any(Option::is_some));

    // 2. 「囲む（1 pt）」を適用
    s.menu("docx.page.borders.box-medium");
    assert_eq!(s.menu_state("docx.page.borders.none"), Some((true, false)));
    assert_eq!(s.menu_state("docx.page.borders.box-medium"), Some((true, true)));
    assert_eq!(s.menu_state("docx.page.borders.from-page"), Some((true, true)), "既定は用紙の端から");
    {
        let doc = s.document();
        for i in 0..4 {
            let b = doc.page.borders[i].as_ref().expect("border exists");
            assert_eq!(b.style, ibis_doc_model::BorderStyle::Single);
            assert_eq!(b.width, 12_700);
            assert_eq!(b.space, 24 * 12_700);
        }
        assert!(!doc.page.borders_from_text);
    }

    // 3. 基準位置を「本文から」に変更
    s.menu("docx.page.borders.from-text");
    assert_eq!(s.menu_state("docx.page.borders.from-text"), Some((true, true)));
    assert_eq!(s.menu_state("docx.page.borders.from-page"), Some((true, false)));
    {
        let doc = s.document();
        assert!(doc.page.borders_from_text);
        for i in 0..4 {
            let b = doc.page.borders[i].as_ref().expect("border exists");
            assert_eq!(b.space, 12_700);
        }
    }

    // 4. 二重線に変更
    s.menu("docx.page.borders.box-double");
    assert_eq!(s.menu_state("docx.page.borders.box-double"), Some((true, true)));
    assert_eq!(s.menu_state("docx.page.borders.box-medium"), Some((true, false)));
    {
        let doc = s.document();
        for i in 0..4 {
            let b = doc.page.borders[i].as_ref().expect("double border exists");
            assert_eq!(b.style, ibis_doc_model::BorderStyle::Double);
        }
    }

    // 5. Undo / Redo の検証
    s.key("cmd-z");
    assert_eq!(s.menu_state("docx.page.borders.box-medium"), Some((true, true)), "Undo で実線1ptに復帰");
    s.key("cmd-shift-z");
    assert_eq!(s.menu_state("docx.page.borders.box-double"), Some((true, true)), "Redo で二重線に復帰");

    // 6. 保存と再読込による永続化検証
    s.save_as("page018_page_borders.docx");
    let saved = s.reopen();
    let doc_saved = flow(&saved);
    assert!(doc_saved.page.borders_from_text, "再読込後も borders_from_text が保持される");
    for i in 0..4 {
        let b = doc_saved.page.borders[i].as_ref().expect("再読込後も border が保持される");
        assert_eq!(b.style, ibis_doc_model::BorderStyle::Double);
        assert_eq!(b.width, 19_050);
        assert_eq!(b.space, 12_700);
    }

    // 7. 枠線なしに戻す検証
    s.menu("docx.page.borders.none");
    assert_eq!(s.menu_state("docx.page.borders.none"), Some((true, true)));
    assert!(!s.document().page.borders.iter().any(Option::is_some));
    s.save_as("page018_page_borders_none.docx");
    let saved_none = s.reopen();
    assert!(!flow(&saved_none).page.borders.iter().any(Option::is_some));
}

fn ja011_overflow_punct() {
    let mut s = Scenario::open(REPORT);

    // 1. 初期状態：句読点のぶら下げは有効（既定値 true）
    assert_eq!(s.menu_state("docx.para.overflow-punct"), Some((true, true)), "初期状態は句読点のぶら下げ有効");
    {
        let doc = s.document();
        let p = body(&doc)[0];
        assert!(p.overflow_punct, "初期状態の段落は overflow_punct = true");
    }

    // 2. トグル切替で無効化
    s.menu("docx.para.overflow-punct");
    assert_eq!(s.menu_state("docx.para.overflow-punct"), Some((true, false)), "トグルで無効化");
    {
        let doc = s.document();
        let p = body(&doc)[0];
        assert!(!p.overflow_punct, "トグル後の段落は overflow_punct = false");
        assert_eq!(p.direct.overflow_punct, Some(false));
    }

    // 3. Undo / Redo 検証
    s.key("cmd-z");
    assert_eq!(s.menu_state("docx.para.overflow-punct"), Some((true, true)), "Undo で有効に復帰");
    {
        let doc = s.document();
        let p = body(&doc)[0];
        assert!(p.overflow_punct);
    }
    s.key("cmd-shift-z");
    assert_eq!(s.menu_state("docx.para.overflow-punct"), Some((true, false)), "Redo で無効に復帰");
    {
        let doc = s.document();
        let p = body(&doc)[0];
        assert!(!p.overflow_punct);
    }

    // 4. 保存と再読込による永続化検証（false の保存）
    s.save_as("ja011_overflow_punct_off.docx");
    let saved = s.reopen();
    let doc_saved = flow(&saved);
    let p_saved = body(doc_saved)[0];
    assert!(!p_saved.overflow_punct, "再読込後も overflow_punct = false が保持される");
    assert_eq!(p_saved.direct.overflow_punct, Some(false));

    // 5. 再度トグル切替で有効化
    s.menu("docx.para.overflow-punct");
    assert_eq!(s.menu_state("docx.para.overflow-punct"), Some((true, true)), "再度トグルで有効化");
    {
        let doc = s.document();
        let p = body(&doc)[0];
        assert!(p.overflow_punct, "段落は overflow_punct = true");
        assert_eq!(p.direct.overflow_punct, Some(true));
    }

    // 6. 保存と再読込による永続化検証（true の保存）
    s.save_as("ja011_overflow_punct_on.docx");
    let saved_on = s.reopen();
    let doc_saved_on = flow(&saved_on);
    let p_saved_on = body(doc_saved_on)[0];
    assert!(p_saved_on.overflow_punct, "再読込後も overflow_punct = true が保持される");
    assert_eq!(p_saved_on.direct.overflow_punct, Some(true));
}

fn ja013_auto_space() {
    let mut s = Scenario::open(REPORT);

    // 1. 初期状態：日本語と英字／数字の間隔自動調整は有効（既定値 true）
    assert_eq!(s.menu_state("docx.para.auto-space-de"), Some((true, true)), "初期状態はautoSpaceDE有効");
    assert_eq!(s.menu_state("docx.para.auto-space-dn"), Some((true, true)), "初期状態はautoSpaceDN有効");
    {
        let doc = s.document();
        let p = body(&doc)[0];
        assert!(p.auto_space_letters, "初期状態の段落は auto_space_letters = true");
        assert!(p.auto_space_digits, "初期状態の段落は auto_space_digits = true");
    }

    // 2. トグル切替で両方無効化
    s.menu("docx.para.auto-space-de");
    assert_eq!(s.menu_state("docx.para.auto-space-de"), Some((true, false)), "トグルでautoSpaceDE無効化");
    s.menu("docx.para.auto-space-dn");
    assert_eq!(s.menu_state("docx.para.auto-space-dn"), Some((true, false)), "トグルでautoSpaceDN無効化");
    {
        let doc = s.document();
        let p = body(&doc)[0];
        assert!(!p.auto_space_letters);
        assert!(!p.auto_space_digits);
        assert_eq!(p.direct.auto_space_letters, Some(false));
        assert_eq!(p.direct.auto_space_digits, Some(false));
    }

    // 3. Undo / Redo 検証
    s.key("cmd-z");
    assert_eq!(s.menu_state("docx.para.auto-space-dn"), Some((true, true)));
    s.key("cmd-z");
    assert_eq!(s.menu_state("docx.para.auto-space-de"), Some((true, true)));
    {
        let doc = s.document();
        let p = body(&doc)[0];
        assert!(p.auto_space_letters);
        assert!(p.auto_space_digits);
    }
    s.key("cmd-shift-z");
    s.key("cmd-shift-z");
    assert_eq!(s.menu_state("docx.para.auto-space-de"), Some((true, false)));
    assert_eq!(s.menu_state("docx.para.auto-space-dn"), Some((true, false)));

    // 4. 保存と再読込による永続化検証（false の保存）
    s.save_as("ja013_auto_space_off.docx");
    let saved = s.reopen();
    let doc_saved = flow(&saved);
    let p_saved = body(doc_saved)[0];
    assert!(!p_saved.auto_space_letters, "再読込後も auto_space_letters = false が保持される");
    assert!(!p_saved.auto_space_digits, "再読込後も auto_space_digits = false が保持される");
    assert_eq!(p_saved.direct.auto_space_letters, Some(false));
    assert_eq!(p_saved.direct.auto_space_digits, Some(false));

    // 5. 再度トグル切替で有効化
    s.menu("docx.para.auto-space-de");
    s.menu("docx.para.auto-space-dn");
    assert_eq!(s.menu_state("docx.para.auto-space-de"), Some((true, true)));
    assert_eq!(s.menu_state("docx.para.auto-space-dn"), Some((true, true)));

    // 6. 保存と再読込による永続化検証（true の保存）
    s.save_as("ja013_auto_space_on.docx");
    let saved_on = s.reopen();
    let doc_saved_on = flow(&saved_on);
    let p_saved_on = body(doc_saved_on)[0];
    assert!(p_saved_on.auto_space_letters, "再読込後も auto_space_letters = true が保持される");
    assert!(p_saved_on.auto_space_digits, "再読込後も auto_space_digits = true が保持される");
    assert_eq!(p_saved_on.direct.auto_space_letters, Some(true));
    assert_eq!(p_saved_on.direct.auto_space_digits, Some(true));
}

